INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac2d077-1ba7-48e6-994a-b7d152d5adbb', '福州神光寺塔', '福州神光寺塔', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["良匠用材爲塔了，神光寺更得高名。","風雲會處千尋出，日月中時八面明。","海水旋流倭國野，天文方戴福州城。","相輪頂上望浮世，塵裏人心應總平。"]', '["良匠用材爲塔了，神光寺更得高名。","风云會处千尋出，日月中时八面明。","海水旋流倭国野，天文方戴福州城。","相輪頂上望浮世，塵裏人心應總平。"]', '诗', 'shi', '', NULL, '福州神光寺塔 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1a435f-9941-48bd-bf81-80fa01d04b48', '福州開元寺塔', '福州开元寺塔', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["開元寺裏七重塔，遙對方山影擬齊。","雜俗人看離世界，孤高僧上覺天低。","唯堪片片紫霞映，不與濛濛白霧迷。","心若無私羅漢在，參差免向日虹西。"]', '["开元寺裏七重塔，遙对方山影擬齊。","杂俗人看離世界，孤高僧上覺天低。","唯堪片片紫霞映，不與濛濛白霧迷。","心若無私羅漢在，參差免向日虹西。"]', '诗', 'shi', '', NULL, '福州開元寺塔 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cb331b8-ffef-42be-ab42-e30fc2e7d383', '春日秦國懷古', '春日秦国懷古', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["荒郊一望欲消魂，涇水縈紆傍遠村。","牛馬放多春草盡，原田耕破古碑存。","雲和積雪蒼山晚，煙伴殘陽綠樹昏。","數里黃沙行客路，不堪回首思秦原。"]', '["荒郊一望欲消魂，涇水縈紆傍远村。","牛马放多春草尽，原田耕破古碑存。","云和積雪蒼山晚，煙伴殘陽綠樹昏。","數里黄沙行客路，不堪回首思秦原。"]', '诗', 'shi', '', NULL, '春日秦國懷古 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8e7a3ea-0e05-45fc-9468-362527d15798', '春日遊北園寄韓侍郎', '春日游北园寄韓侍郎', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["灼灼春園晚色分，露珠千點映寒雲。","多情舞蝶穿花去，解語流鶯隔水聞。","冷酒桮中宜泛灩，暖風林下自氛氳。","仙桃不肯全開拆，應借餘芳待使君。"]', '["灼灼春园晚色分，露珠千点映寒云。","多情舞蝶穿花去，解語流鶯隔水闻。","冷酒桮中宜泛灩，暖风林下自氛氳。","仙桃不肯全开拆，應借餘芳待使君。"]', '诗', 'shi', '', NULL, '春日遊北園寄韓侍郎 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b21673f-2700-4605-a4f2-78d0efaf1060', '喜賀拔先輩衡陽除正字', '喜賀拔先輩衡陽除正字', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["黃紙晴空墜一緘，聖朝恩澤洗冤讒。","李膺門客爲閑客，梅福官銜改舊銜。","名自石渠書典籍，香從芸閣著衣衫。","寰中不用憂天旱，霖雨看看屬傅巖。"]', '["黄紙晴空墜一緘，聖朝恩澤洗冤讒。","李膺门客爲闲客，梅福官銜改旧銜。","名自石渠书典籍，香從芸閣著衣衫。","寰中不用憂天旱，霖雨看看屬傅巖。"]', '诗', 'shi', '', NULL, '喜賀拔先輩衡陽除正字 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('549a98db-6f91-41d2-a98c-8f06b26a9ef2', '客州賃居寄蕭郎中', '客州賃居寄蕭郎中', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["松店茅軒向水開，東頭舍賃一裴徊。","窗吟苦爲秋江靜，枕夢驚因曉角催。","鄰舍見愁賒酒與，主人知去索錢來。","眼看白筆爲霖雨，肯使紅鱗便曝腮。"]', '["松店茅軒向水开，东头舍賃一裴徊。","窗吟苦爲秋江静，枕梦驚因晓角催。","鄰舍见愁賒酒與，主人知去索錢来。","眼看白笔爲霖雨，肯使紅鱗便曝腮。"]', '诗', 'shi', '', NULL, '客州賃居寄蕭郎中 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434fe02b-98e9-4068-912c-29e513cd811c', '贈李裕先輩', '贈李裕先輩', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["曉擎弓箭入初場，一發曾穿百步楊。","仙籍舊題前進士，聖朝新奏校書郎。","馬疑金馬門前馬，香認芸香閣上香。","閑伴李膺紅燭下，慢吟絲竹淺飛觴。"]', '["晓擎弓箭入初場，一發曾穿百步楊。","仙籍旧題前進士，聖朝新奏校书郎。","马疑金马门前马，香認芸香閣上香。","闲伴李膺紅燭下，慢吟絲竹淺飞觴。"]', '诗', 'shi', '', NULL, '贈李裕先輩 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62881fc4-7cf5-4e38-8e75-aacd47fdb453', '桐栢觀', '桐栢观', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["東南一境清心目，有此千峰插翠微。","人在下方衝月上，鶴從高處破煙飛。","巖深水落寒侵骨，門靜花開色照衣。","欲識蓬萊今便是，更於何處學忘機。"]', '["东南一境清心目，有此千峰插翠微。","人在下方衝月上，鹤從高处破煙飞。","巖深水落寒侵骨，门静花开色照衣。","欲識蓬萊今便是，更於何处学忘機。"]', '诗', 'shi', '', NULL, '桐栢觀 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3931b1-3b65-44f9-a979-1c749ac7d430', '塞上', '塞上', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["受降城必破，回落隴頭移。","蕃道北海北，謀生今始知。"]', '["受降城必破，回落隴头移。","蕃道北海北，謀生今始知。"]', '诗', 'shi', '', NULL, '塞上 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527b7fc3-3898-4e30-b649-f8a9cbf16353', '塞上曲', '塞上曲', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["一陣風來一陣砂，有人行處沒人家。","黃河九曲冰先合，紫塞三春不見花。"]', '["一陣风来一陣砂，有人行处沒人家。","黄河九曲冰先合，紫塞三春不见花。"]', '诗', 'shi', '', NULL, '塞上曲 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dfd76b7-11e6-43d5-ab9d-8145553c4c5b', '塞下曲', '塞下曲', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["石國胡兒向磧東，愛吹橫笛引秋風。","夜來雲雨皆飛盡，月照平沙萬里空。"]', '["石国胡兒向磧东，愛吹橫笛引秋风。","夜来云雨皆飞尽，月照平沙万里空。"]', '诗', 'shi', '', NULL, '塞下曲 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e794434-0677-4f98-a588-aca026ea2ea5', '詠猨', '詠猨', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["生在巫山更向西，不知何事到巴溪。","中宵爲憶秋雲伴，遙隔朱門向月啼。"]', '["生在巫山更向西，不知何事到巴溪。","中宵爲憶秋云伴，遙隔朱门向月啼。"]', '诗', 'shi', '', NULL, '詠猨 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b021697a-0896-4e93-93a1-29e78e0817ac', '桃花', '桃花', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["桃花春色暖先開，明媚誰人不看來。","可惜狂風吹落後，殷紅片片點莓苔。"]', '["桃花春色暖先开，明媚誰人不看来。","可惜狂风吹落後，殷紅片片点莓苔。"]', '诗', 'shi', '', NULL, '桃花 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b78ae39-ccbf-4836-a4d0-6dc37ed0ce3a', '薛老峰', '薛老峰', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["薛老峰頭三箇字，須知此與石齊生。","直叫截斷蒼苔色，浮世人儕眼始明。"]', '["薛老峰头三箇字，須知此與石齊生。","直叫截斷蒼苔色，浮世人儕眼始明。"]', '诗', 'shi', '', NULL, '薛老峰 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81a259d8-fd33-49f0-820b-64228f1bba38', '弔李羣玉', '弔李羣玉', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["羣玉詩名冠李唐，投詩換得校書郎。","吟魂醉魄知何處，空有幽蘭隔岸香。"]', '["羣玉诗名冠李唐，投诗換得校书郎。","吟魂醉魄知何处，空有幽蘭隔岸香。"]', '诗', 'shi', '', NULL, '弔李羣玉 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('459c03be-e75f-4801-8732-d9cd022204a6', '無等巌', '無等巌', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["建造上方藤影裏，高僧往往似天台。","不知名樹簷前長，曾問道人巖下來。"]', '["建造上方藤影裏，高僧往往似天台。","不知名樹簷前长，曾问道人巖下来。"]', '诗', 'shi', '', NULL, '無等巌 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3c6a742-bef3-40ef-9e4b-2205c6f4802d', '句', '句', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["古陵寒雨集，高鳥夕陽明。","高情千里外，長嘯一聲初。","月離山一丈，風吹花數苞。","曉來山鳥鬧，雨過杏花稀。","曲渚回灣鎖釣舟，平潮晚影沈清底。","遠岳危欄等翠尖。","白日纔離滄海底，清光先照戶窗前。","連雲天塹有山色，極目海門無鴈行。","可憐黃雀銜將去，從此莊周夢不成。","禪是大溈詩是朴，大唐天子只三人。"]', '["古陵寒雨集，高鸟夕陽明。","高情千里外，长嘯一声初。","月離山一丈，风吹花數苞。","晓来山鸟鬧，雨過杏花稀。","曲渚回灣鎖釣舟，平潮晚影沈清底。","远岳危欄等翠尖。","白日纔離滄海底，清光先照戶窗前。","連云天塹有山色，極目海门無鴈行。","可怜黄雀銜將去，從此莊周梦不成。","禪是大溈诗是朴，大唐天子只三人。"]', '诗', 'shi', '', NULL, '句 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9475130c-3a09-49e2-ac32-eaf4866227a6', '感興', '感兴', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["禾黍不陽豔，競栽桃李春。","翻令力耕者，半作賣花人。"]', '["禾黍不陽豔，競栽桃李春。","翻令力耕者，半作賣花人。"]', '诗', 'shi', '', NULL, '感興 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2e399d8-82da-454c-bbb0-388f4e589a30', '望湘亭', '望湘亭', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["湘水似伊水，湘人非故人。","登臨獨無語，風柳自搖春。"]', '["湘水似伊水，湘人非故人。","登臨独無語，风柳自搖春。"]', '诗', 'shi', '', NULL, '望湘亭 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d958afe-1ba1-4056-b2f3-68dda8805daf', '採桑', '採桑', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["曉陌攜籠去，桑林路隔淮。","何如鬬百草，賭取鳳皇釵。"]', '["晓陌携籠去，桑林路隔淮。","何如鬬百草，賭取鳳皇釵。"]', '诗', 'shi', '', NULL, '採桑 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f54ebdbc-a17a-4125-8d95-49bf7698810a', '悶題', '悶題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["落第春相困，無心惜落花。","荆山歸不得，歸得亦無家。"]', '["落第春相困，無心惜落花。","荆山归不得，归得亦無家。"]', '诗', 'shi', '', NULL, '悶題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c0d244-7834-4623-b101-9672acd41f0a', '中臺五題 乳毛松', '中台五題 乳毛松', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["松格一何高，何人號乳毛。","霜天寓直夜，媿爾伴閑曹。"]', '["松格一何高，何人號乳毛。","霜天寓直夜，媿爾伴闲曹。"]', '诗', 'shi', '', NULL, '中臺五題 乳毛松 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e306ef99-7a58-4d13-a94d-47352bb464dd', '中臺五題 樗里子墓', '中台五題 樗里子墓', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["賢人骨已銷，墓樹幾榮凋。","正直魂如在，齋心願一招。"]', '["賢人骨已銷，墓樹幾榮凋。","正直魂如在，斋心願一招。"]', '诗', 'shi', '', NULL, '中臺五題 樗里子墓 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1118a7b2-5de0-4e5d-afcc-c66dd0875ddd', '中臺五題 牡丹', '中台五題 牡丹', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["亂前看不足，亂後眼偏明。","却得蓬蒿力，遮藏見太平。"]', '["亂前看不足，亂後眼偏明。","却得蓬蒿力，遮藏见太平。"]', '诗', 'shi', '', NULL, '中臺五題 牡丹 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7abfc59-e9b1-4478-b5d0-759557ea0329', '中臺五題 玉蕊', '中台五題 玉蕊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["唐昌樹已荒，天意眷文昌。","曉入微風起，春時雪滿牆。"]', '["唐昌樹已荒，天意眷文昌。","晓入微风起，春时雪满牆。"]', '诗', 'shi', '', NULL, '中臺五題 玉蕊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06120cbe-6b9c-4ad5-ad4a-b2a6c2c44004', '中臺五題 石柱', '中台五題 石柱', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["暴亂免遺折，森羅賢達名。","末郎何所取，叨繼外門榮。"]', '["暴亂免遺折，森羅賢達名。","末郎何所取，叨繼外门榮。"]', '诗', 'shi', '', NULL, '中臺五題 石柱 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970f7083-a0a9-4d87-a8b0-af70f9c738c6', '別同志', '別同志', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["所立共寒苦，平生同與遊。","相看臨遠水，獨自上孤舟。","天澹滄浪晚，風悲蘭杜秋。","前程吟此景，爲子上高樓。"]', '["所立共寒苦，平生同與游。","相看臨远水，独自上孤舟。","天澹滄浪晚，风悲蘭杜秋。","前程吟此景，爲子上高楼。"]', '诗', 'shi', '', NULL, '別同志 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e73f53-22fe-4c27-9c27-acd8cbfb3eeb', '送進士盧棨東歸', '送進士盧棨东归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["灞岸草萋萋，離觴我獨攜。","流年俱老大，失意又東西。","曉楚山雲滿，春吳水樹低。","到家梅雨歇，猶有子規啼。"]', '["灞岸草萋萋，離觴我独携。","流年俱老大，失意又东西。","晓楚山云满，春吳水樹低。","到家梅雨歇，猶有子規啼。"]', '诗', 'shi', '', NULL, '送進士盧棨東歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5a2b004-a0cc-4884-b8ab-655f551d450b', '從叔郎中諴輟自秋曹分符安陸屬羣盜倡熾流毒江壖竟以援兵不來城池失守例削今任却敘省銜退居荆漢之間頗得琴尊之趣因有寄獻', '從叔郎中諴輟自秋曹分符安陸屬羣盜倡熾流毒江壖竟以援兵不来城池失守例削今任却敘省銜退居荆漢之间頗得琴尊之趣因有寄獻', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["華省稱前任，何慙削一麾。","滄洲失孤壘，白髮出重圍。","苦節翻多難，空山自喜歸。","悠悠清漢上，漁者日相依。"]', '["华省稱前任，何慙削一麾。","滄洲失孤壘，白髮出重圍。","苦節翻多难，空山自喜归。","悠悠清漢上，漁者日相依。"]', '诗', 'shi', '', NULL, '從叔郎中諴輟自秋曹分符安陸屬羣盜倡熾流毒江壖竟以援兵不來城池失守例削今任却敘省銜退居荆漢之間頗得琴尊之趣因有寄獻 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a4d09c8-2fcf-4ee3-b6ff-3c221b4ad57b', '送徐渙端公南歸', '送徐渙端公南归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["青衿離白社，朱綬始言歸。","此去應多羨，初心盡不違。","江帆和日落，越鳥近鄉飛。","一路春風裏，楊花雪滿衣。"]', '["青衿離白社，朱綬始言归。","此去應多羨，初心尽不違。","江帆和日落，越鸟近乡飞。","一路春风裏，楊花雪满衣。"]', '诗', 'shi', '', NULL, '送徐渙端公南歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb2d91c-5f92-47f0-8112-688bb12191f0', '送祠部曹郎中鄴出守洋州', '送祠部曹郎中鄴出守洋州', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["爲儒欣出守，上路亦戎裝。","舊製詩多諷，分憂俗必康。","開懷江稻熟，寄信露橙香。","郡閣清吟夜，寒星識望郎。"]', '["爲儒欣出守，上路亦戎裝。","旧製诗多諷，分憂俗必康。","开懷江稻熟，寄信露橙香。","郡閣清吟夜，寒星識望郎。"]', '诗', 'shi', '', NULL, '送祠部曹郎中鄴出守洋州 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbca58f1-5ee9-4d70-ac74-901305f22195', '送進士許彬', '送進士許彬', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["泗上未休兵，壺關事可驚。","流年催我老，遠道念君行。","殘雪臨晴水，寒梅發故城。","何當食新稻，歲稔又時平。"]', '["泗上未休兵，壺关事可驚。","流年催我老，远道念君行。","殘雪臨晴水，寒梅發故城。","何當食新稻，歲稔又时平。"]', '诗', 'shi', '', NULL, '送進士許彬 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97dd6f37-3469-4a2b-8e63-e7e188bb6743', '次韻和王駕校書結綬見寄之什', '次韻和王駕校书結綬见寄之什', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["直應歸諫署，方肯別山村。","勤苦常同業，孤單共感恩。","醉披仙鶴氅，吟扣野僧門。","夢見君高趣，天涼自灌園。"]', '["直應归諫署，方肯別山村。","勤苦常同業，孤單共感恩。","醉披仙鹤氅，吟扣野僧门。","梦见君高趣，天涼自灌园。"]', '诗', 'shi', '', NULL, '次韻和王駕校書結綬見寄之什 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0ebca0a-4fe8-47ec-bdf4-902134941923', '祕閣伴直', '祕閣伴直', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["祕閣鎖書深，牆南列晚岑。","吏人同野鹿，庭木似山林。","淺井寒蕪入，迴廊疊蘚侵。","閑看薛稷鶴，共起五湖心。"]', '["祕閣鎖书深，牆南列晚岑。","吏人同野鹿，庭木似山林。","淺井寒蕪入，迴廊叠蘚侵。","闲看薛稷鹤，共起五湖心。"]', '诗', 'shi', '', NULL, '祕閣伴直 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d25649e-7389-4de2-a723-c0512223cef9', '送太學顏明經及第東歸', '送太学顏明經及第东归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平楚干戈後，田園失耦耕。","艱難登一第，離亂省諸兄。","樹沒春江漲，人繁野渡晴。","閑來思學館，猶夢雪窗明。"]', '["平楚干戈後，田园失耦耕。","艱难登一第，離亂省諸兄。","樹沒春江漲，人繁野渡晴。","闲来思学館，猶梦雪窗明。"]', '诗', 'shi', '', NULL, '送太學顏明經及第東歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d353ba3-bf5c-4d53-97d8-7e7e00422034', '送進士趙能卿下第南歸', '送進士趙能卿下第南归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["不歸何慰親，歸去舊風塵。","灑淚慙關吏，無言對越人。","遠帆花月夜，微岸水天春。","莫便隨漁釣，平生已苦辛。"]', '["不归何慰親，归去旧风塵。","灑泪慙关吏，無言对越人。","远帆花月夜，微岸水天春。","莫便隨漁釣，平生已苦辛。"]', '诗', 'shi', '', NULL, '送進士趙能卿下第南歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b35ef2a4-078a-41b7-9541-6b305d444485', '送人遊邊', '送人游邊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["春亦怯邊遊，此行風正秋。","別離逢雨夜，道路向雲州。","磧樹藏城近，沙河漾日流。","將軍方破虜，莫惜獻良籌。"]', '["春亦怯邊游，此行风正秋。","別離逢雨夜，道路向云州。","磧樹藏城近，沙河漾日流。","將軍方破虜，莫惜獻良籌。"]', '诗', 'shi', '', NULL, '送人遊邊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f97979-33f0-4409-9bc5-f22033fb9c88', '送人之九江謁郡侯苗員外紳', '送人之九江謁郡侯苗員外紳', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["澤國尋知己，南浮不偶遊。","湓城分楚塞，廬岳對江州。","曉飯臨孤嶼，春帆入亂流。","雙旌相望處，月白庾公樓。"]', '["澤国尋知己，南浮不偶游。","湓城分楚塞，廬岳对江州。","晓飯臨孤嶼，春帆入亂流。","雙旌相望处，月白庾公楼。"]', '诗', 'shi', '', NULL, '送人之九江謁郡侯苗員外紳 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0809abcc-ebe3-4894-aa5a-7742d0a45497', '送許棠先輩之官涇縣', '送許棠先輩之官涇縣', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["白頭新作尉，縣在故山中。","高第能卑宦，前賢尚此風。","蕪湖春蕩漾，梅雨晝溟濛。","佐理人安後，篇章莫廢功。"]', '["白头新作尉，縣在故山中。","高第能卑宦，前賢尚此风。","蕪湖春蕩漾，梅雨晝溟濛。","佐理人安後，篇章莫廢功。"]', '诗', 'shi', '', NULL, '送許棠先輩之官涇縣 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66bce220-92a1-498d-87c1-2fb07cc6c46b', '送司封從叔員外徼赴華州裴尚書均辟', '送司封從叔員外徼赴华州裴尚书均辟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["如何拋錦帳，蓮府對蓮峰。","舊有雲霞約，暫留鵷鷺蹤。","敷溪秋雪岸，樹谷夕陽鐘。","盡入新吟境，歸朝興莫慵。"]', '["如何拋錦帳，蓮府对蓮峰。","旧有云霞約，暫留鵷鷺蹤。","敷溪秋雪岸，樹谷夕陽鐘。","尽入新吟境，归朝兴莫慵。"]', '诗', 'shi', '', NULL, '送司封從叔員外徼赴華州裴尚書均辟 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76dfced5-edc8-4e45-bc96-b016f2e80e55', '送京參翁先輩歸閩中', '送京參翁先輩归閩中', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["解印東歸去，人情此際多。","名高五七字，道勝兩重科。","宿館明寒燒，吟船兀夜波。","家山春更好，越鳥在庭柯。"]', '["解印东归去，人情此際多。","名高五七字，道勝兩重科。","宿館明寒燒，吟船兀夜波。","家山春更好，越鸟在庭柯。"]', '诗', 'shi', '', NULL, '送京參翁先輩歸閩中 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77644a16-9c16-4560-b8d5-7848efb235cb', '贈別', '贈別', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["南遊曾共遊，相別倍相留。","行色迴燈曉，離聲滿竹秋。","穩眠彭蠡浪，好醉岳陽樓。","明日逢佳景，爲君成白頭。"]', '["南游曾共游，相別倍相留。","行色迴灯晓，離声满竹秋。","穩眠彭蠡浪，好醉岳陽楼。","明日逢佳景，爲君成白头。"]', '诗', 'shi', '', NULL, '贈別 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1475ea34-3848-4378-8f8e-56aa9e3acd68', '南遊', '南游', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["淒涼懷古意，湘浦弔靈均。","故國經新歲，扁舟寄病身。","山城多曉瘴，澤國少晴春。","漸遠無相識，青梅獨向人。"]', '["淒涼懷古意，湘浦弔靈均。","故国經新歲，扁舟寄病身。","山城多晓瘴，澤国少晴春。","漸远無相識，青梅独向人。"]', '诗', 'shi', '', NULL, '南遊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78bcc825-2ec5-47da-9f31-20af2732e10d', '巴賨旅寓寄朝中從叔', '巴賨旅寓寄朝中從叔', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["驚秋思浩然，信美向巴天。","獨倚臨江樹，初聞落日蟬。","哀榮悲往事，漂泊念多年。","未便甘休去，吾宗盡見憐。"]', '["驚秋思浩然，信美向巴天。","独倚臨江樹，初闻落日蟬。","哀榮悲往事，漂泊念多年。","未便甘休去，吾宗尽见怜。"]', '诗', 'shi', '', NULL, '巴賨旅寓寄朝中從叔 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83f1b02-75d7-46ad-9c73-2bee7429bf0d', '寄司勳張員外學士', '寄司勳張員外学士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平昔偏知我，司勳張外郎。","昨來聞俶擾，憂甚欲顛狂。","煙暝搔愁鬢，春陰賴酒鄉。","江樓倚不得，橫笛數聲長。"]', '["平昔偏知我，司勳張外郎。","昨来闻俶擾，憂甚欲顛狂。","煙暝搔愁鬢，春陰賴酒乡。","江楼倚不得，橫笛數声长。"]', '诗', 'shi', '', NULL, '寄司勳張員外學士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fc6261b-efad-4f0f-8340-c558047e0f4f', '寄邊上從事', '寄邊上從事', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["男兒懷壯節，何不事嫖姚？","高疊觀諸寨，全師護大朝。","淺山寒放馬，亂火夜防苗。","下第春愁甚，勞君遠見招。"]', '["男兒懷壯節，何不事嫖姚？","高叠观諸寨，全師護大朝。","淺山寒放马，亂火夜防苗。","下第春愁甚，勞君远见招。"]', '诗', 'shi', '', NULL, '寄邊上從事 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a2a7d7-d0d9-4730-9ed4-0235f45e914e', '寄左省韋起居序', '寄左省韋起居序', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["風神何蘊藉，張緒正當年。","端簡爐香裏，濡毫洞案邊。","飾裝無雨備，著述減春眠。","旦夕應彌入，銀臺曉候宣。"]', '["风神何蘊藉，張緒正當年。","端簡爐香裏，濡毫洞案邊。","飾裝無雨備，著述減春眠。","旦夕應彌入，銀台晓候宣。"]', '诗', 'shi', '', NULL, '寄左省韋起居序 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e4f7010-1066-4c6a-91e7-00b1eb09cbab', '寄贈藍田韋少府先輩', '寄贈藍田韋少府先輩', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["王畿第一縣，縣尉是詞人。","館殿非初意，圖書是舊貧。","斫冰泉竇響，賽雪廟松春。","自此昇通籍，清華日近身。"]', '["王畿第一縣，縣尉是词人。","館殿非初意，圖书是旧貧。","斫冰泉竇响，賽雪廟松春。","自此昇通籍，清华日近身。"]', '诗', 'shi', '', NULL, '寄贈藍田韋少府先輩 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa22927a-e512-48ce-b7c5-326418a3b2a3', '寄懷元秀上人', '寄懷元秀上人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["悠悠干祿利，草草廢漁樵。","身世堪惆悵，風騷頗寂寥。","高秋期野步，積雨放趨朝。","得句如相憶，莎齋且見招。"]', '["悠悠干祿利，草草廢漁樵。","身世堪惆悵，风騷頗寂寥。","高秋期野步，積雨放趨朝。","得句如相憶，莎斋且见招。"]', '诗', 'shi', '', NULL, '寄懷元秀上人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844d089f-dcdc-4686-85b0-9a39f894cac8', '贈圓昉公', '贈圓昉公', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["天階讓紫衣，冷格鶴猶卑。","道勝嫌名出，身閑覺老遲。","晚香延宿火，寒磬度高枝。","長說長松寺，他年與我期。"]', '["天階讓紫衣，冷格鹤猶卑。","道勝嫌名出，身闲覺老遲。","晚香延宿火，寒磬度高枝。","长说长松寺，他年與我期。"]', '诗', 'shi', '', NULL, '贈圓昉公 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dfcb210-81f9-4bfa-91cb-07760c83cb9c', '寄題方干處士', '寄題方干处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["山雪照湖水，漾舟湖畔歸。","松篁調遠籟，臺榭發清輝。","野岫分閑徑，漁家並掩扉。","暮年詩力在，新句更幽微。"]', '["山雪照湖水，漾舟湖畔归。","松篁調远籟，台榭發清輝。","野岫分闲徑，漁家並掩扉。","暮年诗力在，新句更幽微。"]', '诗', 'shi', '', NULL, '寄題方干處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d83f0120-fe2f-403e-9c3f-a48b97e02596', '寄獻湖州從叔員外', '寄獻湖州從叔員外', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["顧渚山邊郡，溪將罨畫通。","遠看城郭裏，全在水雲中。","西閣歸何晚，東吳興未窮。","茶香紫筍露，洲迥白蘋風。","歌緩眉低翠，杯明蠟翦紅。","政成尋往事，輟棹問漁翁。"]', '["顧渚山邊郡，溪將罨畫通。","远看城郭裏，全在水云中。","西閣归何晚，东吳兴未窮。","茶香紫筍露，洲迥白蘋风。","歌緩眉低翠，杯明蠟翦紅。","政成尋往事，輟棹问漁翁。"]', '诗', 'shi', '', NULL, '寄獻湖州從叔員外 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('392575e8-2a26-48a0-b16a-0af2e0c1213d', '訪姨兄王斌渭口別墅', '訪姨兄王斌渭口別墅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["枯桑河上村，寥落舊田園。","少小曾來此，悲涼不可言。","訪鄰多指塚，問路半移原。","久歉家僮散，初晴野薺繁。","客帆懸極浦，漁網曬危軒。","苦澀詩盈篋，荒唐酒滿尊。","高枝霜果在，幽渚暝禽喧。","遠靄籠樵響，微煙起燒痕。","哀榮孤族分，感激外兄恩。","三宿忘歸去，圭峰恰對門。"]', '["枯桑河上村，寥落旧田园。","少小曾来此，悲涼不可言。","訪鄰多指塚，问路半移原。","久歉家僮散，初晴野薺繁。","客帆懸極浦，漁網曬危軒。","苦澀诗盈篋，荒唐酒满尊。","高枝霜果在，幽渚暝禽喧。","远靄籠樵响，微煙起燒痕。","哀榮孤族分，感激外兄恩。","三宿忘归去，圭峰恰对门。"]', '诗', 'shi', '', NULL, '訪姨兄王斌渭口別墅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1232b7c5-52d7-4dd2-a1e1-9f546c5f54bd', '放朝偶作', '放朝偶作', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寒極放朝天，欣聞半夜宣。","時安逢密雪，日晏得高眠。","擁褐同休假，吟詩賀有年。","坐來幽興在，松亞小窗前。"]', '["寒極放朝天，欣闻半夜宣。","时安逢密雪，日晏得高眠。","擁褐同休假，吟诗賀有年。","坐来幽兴在，松亞小窗前。"]', '诗', 'shi', '', NULL, '放朝偶作 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d226c9ea-34d0-4f8b-bdce-c176c10a2e70', '順動後藍田偶作', '順动後藍田偶作', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["小諫昇中諫，三年侍玉除。","且言無所補，浩歎欲何如。","宮闕飛灰燼，嬪嬙落里閭。","藍峰秋更碧，霑灑望鑾輿。"]', '["小諫昇中諫，三年侍玉除。","且言無所補，浩歎欲何如。","宮闕飞灰燼，嬪嬙落里閭。","藍峰秋更碧，霑灑望鑾輿。"]', '诗', 'shi', '', NULL, '順動後藍田偶作 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be9014a-b079-4eaf-85e1-bcf389c4ca59', '府中寓止寄趙大諫', '府中寓止寄趙大諫', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["老作含香客，貧無僦舍錢。","神州容寄跡，大尹是同年。","密邇都忘倦，乖慵益見憐。","雪風花月好，中夜便招延。"]', '["老作含香客，貧無僦舍錢。","神州容寄跡，大尹是同年。","密邇都忘倦，乖慵益见怜。","雪风花月好，中夜便招延。"]', '诗', 'shi', '', NULL, '府中寓止寄趙大諫 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1598d864-b035-4b18-95f6-a596474a7307', '峽中寓止二首 一', '峽中寓止二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["荆州未解圍，小縣結茅茨。","強對官人笑，甘爲野鶴欺。","江春鋪網闊，市晚鬻蔬遲。","子美猶如此，翻然不敢悲。"]', '["荆州未解圍，小縣結茅茨。","強对官人笑，甘爲野鹤欺。","江春鋪網闊，市晚鬻蔬遲。","子美猶如此，翻然不敢悲。"]', '诗', 'shi', '', NULL, '峽中寓止二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a3f6dd-62d4-4905-bd7a-ea183dc4fecd', '峽中寓止二首 二', '峽中寓止二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["傳聞殊不定，鑾輅幾時還。","俗易無常性，江清見老顏。","夜船歸草市，春步上茶山。","寨將來相問，兒童競啓關。"]', '["傳闻殊不定，鑾輅幾时還。","俗易無常性，江清见老顏。","夜船归草市，春步上茶山。","寨將来相问，兒童競啓关。"]', '诗', 'shi', '', NULL, '峽中寓止二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79719c6a-fc74-4955-9a91-13e8c49beec1', '顏惠詹事即孤姪舅氏謫官黔巫舟中相遇愴然有寄', '顏惠詹事即孤姪舅氏謫官黔巫舟中相遇愴然有寄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["猶子在天末，念渠懷渭陽。","巴山偶會遇，江浦共悲涼。","謫宦君何遠，窮遊我自強。","瘴村三月暮，雨熟野梅黃。"]', '["猶子在天末，念渠懷渭陽。","巴山偶會遇，江浦共悲涼。","謫宦君何远，窮游我自強。","瘴村三月暮，雨熟野梅黄。"]', '诗', 'shi', '', NULL, '顏惠詹事即孤姪舅氏謫官黔巫舟中相遇愴然有寄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3204c7-b72f-4f0e-ae4c-4fb61849cdcc', '訪題進士孫秦延福南街居', '訪題進士孫秦延福南街居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["多病久離索，相尋聊解顏。","短牆通御水，疎樹出南山。","歲月何難老，園林未得還。","無門共榮達，孤坐却如閑。"]', '["多病久離索，相尋聊解顏。","短牆通御水，疎樹出南山。","歲月何难老，园林未得還。","無门共榮達，孤坐却如闲。"]', '诗', 'shi', '', NULL, '訪題進士孫秦延福南街居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60161877-54b7-421d-92ba-51c0fa9a2ae0', '訪題進士張喬延興門外所居', '訪題進士張喬延兴门外所居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平生苦節同，旦夕會原東。","掩卷斜陽裏，看山落木中。","星霜今欲老，江海業全空。","近日文場內，因君起古風。"]', '["平生苦節同，旦夕會原东。","掩卷斜陽裏，看山落木中。","星霜今欲老，江海業全空。","近日文場內，因君起古风。"]', '诗', 'shi', '', NULL, '訪題進士張喬延興門外所居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b7115fc-e5f8-4def-89a6-56f0559014df', '寄南浦謫官', '寄南浦謫官', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["多才翻得罪，天末抱窮憂。","白首爲遷客，青山繞萬州。","醉敧梅障曉，歌厭竹枝秋。","望闕懷鄉淚，荆江水共流。"]', '["多才翻得罪，天末抱窮憂。","白首爲遷客，青山繞万州。","醉敧梅障晓，歌厭竹枝秋。","望闕懷乡泪，荆江水共流。"]', '诗', 'shi', '', NULL, '寄南浦謫官 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be57868c-6584-4ee1-87ac-b5e59ef81968', '李夷遇侍御久滯水鄉因抒寄懷', '李夷遇侍御久滯水乡因抒寄懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["簪豸年何久，懸帆興甚長。","江流愛吳越，詩格愈齊梁。","竹寺晴吟遠，蘭洲晚泊香。","高閑徒自任，華省待爲郎。"]', '["簪豸年何久，懸帆兴甚长。","江流愛吳越，诗格愈齊梁。","竹寺晴吟远，蘭洲晚泊香。","高闲徒自任，华省待爲郎。"]', '诗', 'shi', '', NULL, '李夷遇侍御久滯水鄉因抒寄懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6faa3d59-1de6-4284-83d1-39c6c5e7dcef', '寄膳部李郎中昌符', '寄膳部李郎中昌符', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["鄠郊陪野步，早歲偶因詩。","自後吟新句，長愁減舊知。","靜燈微落燼，寒硯旋生澌。","夜夜冥搜苦，那能鬢不衰。"]', '["鄠郊陪野步，早歲偶因诗。","自後吟新句，长愁減旧知。","静灯微落燼，寒硯旋生澌。","夜夜冥搜苦，那能鬢不衰。"]', '诗', 'shi', '', NULL, '寄膳部李郎中昌符 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ee2a56-ac50-41c1-b9c3-2c5e8872193f', '寄前水部賈員外嵩', '寄前水部賈員外嵩', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["謝病別文昌，仙舟向越鄉。","貴爲金馬客，雅稱水曹郎。","白鷺同孤潔，清波共渺茫。","相如詞賦外，騷雅趣何長。"]', '["謝病別文昌，仙舟向越乡。","貴爲金马客，雅稱水曹郎。","白鷺同孤潔，清波共渺茫。","相如词賦外，騷雅趣何长。"]', '诗', 'shi', '', NULL, '寄前水部賈員外嵩 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe74ba79-c322-43f5-9390-43ee36154ea5', '寄棊客', '寄棊客', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["松窗楸局穩，相顧思皆凝。","幾局賭山果，一先饒海僧。","覆圖聞夜雨，下子對秋燈。","何日無羈束，期君向杜陵。"]', '["松窗楸局穩，相顧思皆凝。","幾局賭山果，一先饒海僧。","覆圖闻夜雨，下子对秋灯。","何日無羈束，期君向杜陵。"]', '诗', 'shi', '', NULL, '寄棊客 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('222bcf1a-a0e6-41e8-91b9-1ae34ba60e95', '聞進士許彬罷舉歸睦州悵然懷寄', '闻進士許彬罷舉归睦州悵然懷寄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["桐廬歸舊廬，垂老復樵漁。","吾子雖言命，鄉人嬾讀書。","煙舟撐晚浦，雨屐翦春蔬。","異代名方振，哀吟莫廢初。"]', '["桐廬归旧廬，垂老复樵漁。","吾子雖言命，乡人嬾读书。","煙舟撐晚浦，雨屐翦春蔬。","異代名方振，哀吟莫廢初。"]', '诗', 'shi', '', NULL, '聞進士許彬罷舉歸睦州悵然懷寄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0f1ef55-b1a4-458b-8314-50efa095932a', '長安夜坐寄懷湖外嵇處士', '长安夜坐寄懷湖外嵇处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["萬里念江海，浩然天地秋。","風高羣木落，夜久數星流。","鐘絕分宮漏，螢微隔御溝。","遙思洞庭上，葦露滴漁舟。"]', '["万里念江海，浩然天地秋。","风高羣木落，夜久數星流。","鐘絕分宮漏，螢微隔御溝。","遙思洞庭上，葦露滴漁舟。"]', '诗', 'shi', '', NULL, '長安夜坐寄懷湖外嵇處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da6f210d-321b-4692-9a87-42b5e444c76f', '贈文士王雄', '贈文士王雄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["知己竟何人，哀君尚苦辛。","圖書長在手，文學老於身。","公道天難廢，貞姿世任嗔。","小齋松菊靜，願卜子爲鄰。"]', '["知己竟何人，哀君尚苦辛。","圖书长在手，文学老於身。","公道天难廢，貞姿世任嗔。","小斋松菊静，願卜子爲鄰。"]', '诗', 'shi', '', NULL, '贈文士王雄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0c1dbf-78fc-45a8-b856-4652cc197744', '贈富平李宰', '贈富平李宰', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["夫君清且貧，琴鶴最相親。","簡肅諸曹事，安閑一境人。","陵山雲裏拜，渠路雨中巡。","易得連宵醉，千缸石凍春。"]', '["夫君清且貧，琴鹤最相親。","簡肅諸曹事，安闲一境人。","陵山云裏拜，渠路雨中巡。","易得連宵醉，千缸石凍春。"]', '诗', 'shi', '', NULL, '贈富平李宰 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1c80038-e979-4381-92ea-5e6d0a23e4bf', '贈尚顏上人', '贈尚顏上人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["相尋喜可知，放錫便論詩。","酷愛山兼水，唯應我與師。","風雷吟不覺，猨鶴老爲期。","近輩推棲白，其如趣向卑。"]', '["相尋喜可知，放錫便論诗。","酷愛山兼水，唯應我與師。","风雷吟不覺，猨鹤老爲期。","近輩推棲白，其如趣向卑。"]', '诗', 'shi', '', NULL, '贈尚顏上人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26f3d1d1-5f6b-4b50-9134-3b82443697f2', '贈泗口苗居士', '贈泗口苗居士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["歲[晏]樂園林，維摩契道心。","江雲寒不散，庭雪夜方深。","酒勸漁人飲，詩憐稚子吟。","四郊多壘日，勉我捨朝簪。"]', '["歲[晏]乐园林，維摩契道心。","江云寒不散，庭雪夜方深。","酒勸漁人饮，诗怜稚子吟。","四郊多壘日，勉我捨朝簪。"]', '诗', 'shi', '', NULL, '贈泗口苗居士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff7c426-c46e-4f4e-8575-50c02997d2ad', '梁燭處士辭金陵相國杜公歸舊山因以寄贈', '梁燭处士辞金陵相国杜公归旧山因以寄贈', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["相庭留不得，江野有苔磯。","兩浙尋山徧，孤舟載鶴歸。","世間書讀盡，雲外客來稀。","諫署搜賢急，應難惜布衣。"]', '["相庭留不得，江野有苔磯。","兩浙尋山徧，孤舟載鹤归。","世间书读尽，云外客来稀。","諫署搜賢急，應难惜布衣。"]', '诗', 'shi', '', NULL, '梁燭處士辭金陵相國杜公歸舊山因以寄贈 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b10f825-4867-4311-8c18-81ec35423a9a', '哭建州李員外頻', '哭建州李員外頻', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["令終歸故里，末歲道如初。","舊友誰爲誌，清風豈易書。","雨墳生野蕨，鄉奠釣江魚。","獨夜吟還泣，前年伴直廬。"]', '["令終归故里，末歲道如初。","旧友誰爲誌，清风豈易书。","雨墳生野蕨，乡奠釣江鱼。","独夜吟還泣，前年伴直廬。"]', '诗', 'shi', '', NULL, '哭建州李員外頻 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300b6db6-c240-4aaa-91ad-1f0403e8cc36', '哭進士李洞二首 一', '哭進士李洞二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["所惜絕吟聲，不悲君不榮。","李端終薄宦，賈島得高名。","旅葬新墳小，遺孤遠俗輕。","猶疑隨計晚，昨夜草蟲鳴。"]', '["所惜絕吟声，不悲君不榮。","李端終薄宦，賈島得高名。","旅葬新墳小，遺孤远俗轻。","猶疑隨計晚，昨夜草蟲鳴。"]', '诗', 'shi', '', NULL, '哭進士李洞二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3acfa17-77e7-4676-8acb-6dd2fad0ad26', '哭進士李洞二首 二', '哭進士李洞二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["自聞東蜀病，唯我獨關情。","若近長江死，想君勝在生。","瘴蒸丹旐溼，燈隔素帷清。","塚樹僧栽後，新蟬一兩聲。"]', '["自闻东蜀病，唯我独关情。","若近长江死，想君勝在生。","瘴蒸丹旐溼，灯隔素帷清。","塚樹僧栽後，新蟬一兩声。"]', '诗', 'shi', '', NULL, '哭進士李洞二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb9dcfa1-25b5-4611-be0a-350da38999e7', '南康郡牧陸肱郎中辟許棠先輩爲郡從事因有寄贈', '南康郡牧陸肱郎中辟許棠先輩爲郡從事因有寄贈', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["末路思前侶，猶爲戀故巢。","江山多勝境，賓主是貧交。","飲舫閑依葦，琴堂雅結茅。","夜清僧伴宿，水月在松梢。"]', '["末路思前侶，猶爲戀故巢。","江山多勝境，賓主是貧交。","饮舫闲依葦，琴堂雅結茅。","夜清僧伴宿，水月在松梢。"]', '诗', 'shi', '', NULL, '南康郡牧陸肱郎中辟許棠先輩爲郡從事因有寄贈 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26dfc08-eb62-48de-b735-19f83e4d8ea4', '久不得張喬消息', '久不得張喬消息', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["天末去程孤，沿淮復向吳。","亂離何處甚，安穩到家無。","樹盡雲垂野，檣稀月滿湖。","傷心繞村落，應少舊耕夫。"]', '["天末去程孤，沿淮复向吳。","亂離何处甚，安穩到家無。","樹尽云垂野，檣稀月满湖。","傷心繞村落，應少旧耕夫。"]', '诗', 'shi', '', NULL, '久不得張喬消息 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed2de63-331e-434f-891c-d862e2cfd997', '題嵩高隱者居', '題嵩高隐者居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["豈易訪仙蹤，雲蘿千萬重。","他年來卜隱，此景願相容。","亂水林中路，深山雪裏鐘。","見君琴酒樂，迴首興何慵。"]', '["豈易訪仙蹤，云蘿千万重。","他年来卜隐，此景願相容。","亂水林中路，深山雪裏鐘。","见君琴酒乐，迴首兴何慵。"]', '诗', 'shi', '', NULL, '題嵩高隱者居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9bf9abc-a7ff-41c0-8a45-8dff7736d001', '趙璘郎中席上賦蝴蝶', '趙璘郎中席上賦蝴蝶', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["尋豔復尋香，似閑還似忙。","暖煙沈蕙徑，微雨宿花房。","書幌輕隨夢，歌樓誤採粧。","王孫深屬意，繡入舞衣裳。"]', '["尋豔复尋香，似闲還似忙。","暖煙沈蕙徑，微雨宿花房。","书幌轻隨梦，歌楼誤採粧。","王孫深屬意，繡入舞衣裳。"]', '诗', 'shi', '', NULL, '趙璘郎中席上賦蝴蝶 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb096f6d-1d57-430f-a0ad-9f218b3c1bfb', '賀進士駱用錫登第', '賀進士駱用錫登第', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["苦辛垂二紀，擢第却霑裳。","春榜到春晚，一家榮一鄉。","題名登塔喜，醵宴爲花忙。","好是東歸日，高槐蕊半黃。"]', '["苦辛垂二紀，擢第却霑裳。","春榜到春晚，一家榮一乡。","題名登塔喜，醵宴爲花忙。","好是东归日，高槐蕊半黄。"]', '诗', 'shi', '', NULL, '賀進士駱用錫登第 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f58c478-8cb8-4fdb-94e3-db1ab8b63c46', '興州東池', '兴州东池', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["南連乳郡流，闊碧侵晴樓。","徹底千峰影，無風一片秋。","垂楊拂蓮葉，返照媚漁舟。","鑑貌還惆悵，難遮兩鬢羞。"]', '["南連乳郡流，闊碧侵晴楼。","徹底千峰影，無风一片秋。","垂楊拂蓮葉，返照媚漁舟。","鑑貌還惆悵，难遮兩鬢羞。"]', '诗', 'shi', '', NULL, '興州東池 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e1c59a6-0edc-4d3f-8a87-686b6694372a', '渠江旅思', '渠江旅思', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["流落復蹉跎，交親半逝波。","謀生非不切，言命欲如何。","故楚春田廢，窮巴瘴雨多。","引人鄉淚盡，夜夜竹枝歌。"]', '["流落复蹉跎，交親半逝波。","謀生非不切，言命欲如何。","故楚春田廢，窮巴瘴雨多。","引人乡泪尽，夜夜竹枝歌。"]', '诗', 'shi', '', NULL, '渠江旅思 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd70a78d-99a0-4416-ba4a-1c9df7369ba9', '登杭州城', '登杭州城', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["漠漠江天外，登臨返照間。","潮來無別浦，木落見他山。","沙鳥晴飛遠，漁人夜唱閑。","歲窮歸未得，心逐片帆還。"]', '["漠漠江天外，登臨返照间。","潮来無別浦，木落见他山。","沙鸟晴飞远，漁人夜唱闲。","歲窮归未得，心逐片帆還。"]', '诗', 'shi', '', NULL, '登杭州城 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee54b661-5efa-4e46-9de6-4c0cd5d97170', '曲江', '曲江', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["細草岸西東，酒旗遙水風。","樓臺在煙杪，鷗鷺下沙中。","翠幄晴相接，芳洲夜暫空。","何人賞秋景，興與此時同。"]', '["細草岸西东，酒旗遙水风。","楼台在煙杪，鷗鷺下沙中。","翠幄晴相接，芳洲夜暫空。","何人賞秋景，兴與此时同。"]', '诗', 'shi', '', NULL, '曲江 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00a5d87-052e-455a-b7a2-ea2334595f4e', '沙苑', '沙苑', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["茫茫信馬行，不似近都城。","苑吏猶迷路，江人莫問程。","聚來千嶂出，落去一川平。","日暮客心速，愁聞鴈數聲。"]', '["茫茫信马行，不似近都城。","苑吏猶迷路，江人莫问程。","聚来千嶂出，落去一川平。","日暮客心速，愁闻鴈數声。"]', '诗', 'shi', '', NULL, '沙苑 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b65ae50c-c9f7-4a49-96c3-9be6fc7ef668', '通川客舍', '通川客舍', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["奔走失前計，淹留非本心。","已難消永夜，況復聽秋霖。","漸解巴兒語，誰憐越客吟。","黃花徒滿手，白髮不勝簪。"]', '["奔走失前計，淹留非本心。","已难消永夜，況复听秋霖。","漸解巴兒語，誰怜越客吟。","黄花徒满手，白髮不勝簪。"]', '诗', 'shi', '', NULL, '通川客舍 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c52178e-dab1-4503-b237-ae684be73d5a', '潼關道中', '潼关道中', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["白道曉霜迷，離燈照馬嘶。","秋風滿關樹，殘月隔河雞。","來往非無倦，窮通豈易齊。","何年歸故社，披雨翦春畦。"]', '["白道晓霜迷，離灯照马嘶。","秋风满关樹，殘月隔河雞。","来往非無倦，窮通豈易齊。","何年归故社，披雨翦春畦。"]', '诗', 'shi', '', NULL, '潼關道中 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('372f68ec-80f0-4cde-96d7-838a6b685707', '終南白鶴觀', '終南白鹤观', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["步步景通真，門前衆水分。","檉蘿諸洞合，鐘磬上清聞。","古木千尋雪，寒山萬丈雲。","終期掃壇級，來事紫陽君。"]', '["步步景通真，门前衆水分。","檉蘿諸洞合，鐘磬上清闻。","古木千尋雪，寒山万丈云。","終期掃壇級，来事紫陽君。"]', '诗', 'shi', '', NULL, '終南白鶴觀 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1429477e-9ddb-4161-8db9-6b1080e65750', '題興善寺寂上人院', '題兴善寺寂上人院', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["客來風雨後，院靜似荒涼。","罷講蛩離砌，思山葉滿廊。","臘高興故疾，爐暖發餘香。","自說匡廬側，杉陰半石牀。"]', '["客来风雨後，院静似荒涼。","罷講蛩離砌，思山葉满廊。","臘高兴故疾，爐暖發餘香。","自说匡廬側，杉陰半石牀。"]', '诗', 'shi', '', NULL, '題興善寺寂上人院 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90006838-c447-4e1c-8c03-c83facd4bd62', '題水部李羽員外招國里居', '題水部李羽員外招国里居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["野色入前軒，翛然琴與尊。","畫僧依寺壁，栽葦學江村。","自醞花前酒，誰敲雪裏門。","不辭朝謁遠，唯要近慈恩。"]', '["野色入前軒，翛然琴與尊。","畫僧依寺壁，栽葦学江村。","自醞花前酒，誰敲雪裏门。","不辞朝謁远，唯要近慈恩。"]', '诗', 'shi', '', NULL, '題水部李羽員外招國里居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58f9d42-feb5-4a5a-ab8c-ec9fdb4cb71a', '信美寺岑上人', '信美寺岑上人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["巡禮諸方徧，湘南頗有緣。","焚香老山寺，乞食向江船。","紗碧籠名畫，燈寒照淨禪。","我來能永日，蓮漏滴堦前。"]', '["巡禮諸方徧，湘南頗有緣。","焚香老山寺，乞食向江船。","紗碧籠名畫，灯寒照淨禪。","我来能永日，蓮漏滴堦前。"]', '诗', 'shi', '', NULL, '信美寺岑上人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f41f7ef-b692-415d-98ae-2427a2aa8658', '池上', '池上', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["池榭愜幽獨，狂吟學解嘲。","露荷香自在，風竹冷相敲。","喪志嫌孤宦，忘機愛澹交。","仙山如有分，必擬訪三茅。"]', '["池榭愜幽独，狂吟学解嘲。","露荷香自在，风竹冷相敲。","喪志嫌孤宦，忘機愛澹交。","仙山如有分，必擬訪三茅。"]', '诗', 'shi', '', NULL, '池上 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b97a119-8ca5-4b5a-b32f-405a81b10393', '遊貴侯城南林墅', '游貴侯城南林墅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["韋杜八九月，亭臺高下風。","獨來新霽後，閑步澹煙中。","荷密連池綠，柿繁和葉紅。","主人貪貴達，清境屬鄰翁。"]', '["韋杜八九月，亭台高下风。","独来新霽後，闲步澹煙中。","荷密連池綠，柿繁和葉紅。","主人貪貴達，清境屬鄰翁。"]', '诗', 'shi', '', NULL, '遊貴侯城南林墅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a966d644-6313-473f-af5c-94823af3b15c', '江行', '江行', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["漂泊病難任，逢人淚滿襟。","關東多事日，天末未歸心。","夜雨荆江漲，春雲郢樹深。","殷勤聽漁唱，漸次入吳音。"]', '["漂泊病难任，逢人泪满襟。","关东多事日，天末未归心。","夜雨荆江漲，春云郢樹深。","殷勤听漁唱，漸次入吳音。"]', '诗', 'shi', '', NULL, '江行 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca55870b-64f4-428a-bd39-8a2d080cd873', '舟次通泉精舍', '舟次通泉精舍', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江清如洛汭，寺好似香山。","勞倦孤舟裏，登臨半日間。","樹涼巢鶴健，巖響語僧閑。","更共幽雲約，秋隨絳帳還。"]', '["江清如洛汭，寺好似香山。","勞倦孤舟裏，登臨半日间。","樹涼巢鹤健，巖响語僧闲。","更共幽云約，秋隨絳帳還。"]', '诗', 'shi', '', NULL, '舟次通泉精舍 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2156336-cca1-461c-96b4-1f5dcf5f3cf2', '水軒', '水軒', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["日日狎沙禽，偷安且放吟。","讀書老不入，愛酒病還深。","歉後爲羈客，兵餘問故林。","楊花滿牀席，搔首度春陰。"]', '["日日狎沙禽，偷安且放吟。","读书老不入，愛酒病還深。","歉後爲羈客，兵餘问故林。","楊花满牀席，搔首度春陰。"]', '诗', 'shi', '', NULL, '水軒 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('951ba8b3-9879-43fa-b7ae-304b21ffbd7e', '潯陽姚宰廳作', '潯陽姚宰廳作', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["縣幽公事稀，庭草是山薇。","足得招棊侶，何妨著道衣。","野泉當案落，汀鷺入衙飛。","寺去東林近，多應隔宿歸。"]', '["縣幽公事稀，庭草是山薇。","足得招棊侶，何妨著道衣。","野泉當案落，汀鷺入衙飞。","寺去东林近，多應隔宿归。"]', '诗', 'shi', '', NULL, '潯陽姚宰廳作 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ad1b60-0ce3-4f80-98bf-dff98c2b3979', '梓潼歲暮', '梓潼歲暮', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江城無宿雪，風物易爲春。","酒美消磨日，梅香著莫人。","老吟窮景象，多難損精神。","漸有還京望，綿州減戰塵。"]', '["江城無宿雪，风物易爲春。","酒美消磨日，梅香著莫人。","老吟窮景象，多难損精神。","漸有還京望，綿州減戰塵。"]', '诗', 'shi', '', NULL, '梓潼歲暮 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f2144f-e5d8-4ef7-97a8-22957d42a811', '咸陽', '咸陽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["咸陽城下宿，往事可悲思。","未有謀身計，頻遷反正期。","凍河孤棹澀，老樹疊巢危。","莫問今行止，漂漂不自知。"]', '["咸陽城下宿，往事可悲思。","未有謀身計，頻遷反正期。","凍河孤棹澀，老樹叠巢危。","莫问今行止，漂漂不自知。"]', '诗', 'shi', '', NULL, '咸陽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4e98b2-d058-4981-b696-200351020e9c', '長安感興', '长安感兴', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["徒勞悲喪亂，自古戒繁華。","落日狐兔徑，近年公相家。","可悲聞玉笛，不見走香車。","寂寞牆匡裏，春陰挫杏花。"]', '["徒勞悲喪亂，自古戒繁华。","落日狐兔徑，近年公相家。","可悲闻玉笛，不见走香车。","寂寞牆匡裏，春陰挫杏花。"]', '诗', 'shi', '', NULL, '長安感興 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faace781-a5e0-4839-b36f-8c2f30f1923c', '聞所知遊樊川有寄', '闻所知游樊川有寄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["誰無泉石趣，朝下少同過。","貪勝覺程近，愛閑經宿多。","片沙留白鳥，高木引青蘿。","醉把漁竿去，殷勤藉岸莎。"]', '["誰無泉石趣，朝下少同過。","貪勝覺程近，愛闲經宿多。","片沙留白鸟，高木引青蘿。","醉把漁竿去，殷勤藉岸莎。"]', '诗', 'shi', '', NULL, '聞所知遊樊川有寄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8afe0123-e8cd-4859-8f7a-e67b98bcdb1d', '張谷田舍', '張谷田舍', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["縣官清且儉，深谷有人家。","一徑入寒竹，小橋穿野花。","碓喧春澗滿，梯倚綠桑斜。","自說年來稔，前村酒可賒。"]', '["縣官清且儉，深谷有人家。","一徑入寒竹，小橋穿野花。","碓喧春澗满，梯倚綠桑斜。","自说年来稔，前村酒可賒。"]', '诗', 'shi', '', NULL, '張谷田舍 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9345c5d2-2a0e-4c42-902f-e66cf08395fa', '深居', '深居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["吾道有誰同，深居自固窮。","殷勤謝綠樹，朝夕惠清風。","書滿閑窗下，琴橫野艇中。","年來頭更白，雅稱釣魚翁。"]', '["吾道有誰同，深居自固窮。","殷勤謝綠樹，朝夕惠清风。","书满闲窗下，琴橫野艇中。","年来头更白，雅稱釣鱼翁。"]', '诗', 'shi', '', NULL, '深居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('901e1011-4076-46b6-ae0c-06611a7868d1', '端居', '端居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["葉葉下高梧，端居失所圖。","亂離時輩少，風月夜吟孤。","舊疾衰還有，窮愁醉暫無。","秋光如水國，不語理霜鬚。"]', '["葉葉下高梧，端居失所圖。","亂離时輩少，风月夜吟孤。","旧疾衰還有，窮愁醉暫無。","秋光如水国，不語理霜鬚。"]', '诗', 'shi', '', NULL, '端居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6527f09-3b56-4dc4-8b31-31dd6daba4d6', '郊園', '郊园', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["相近復相尋，山僧與水禽。","煙蓑春釣靜，雪屋夜棊深。","雅道誰開口，時風未醒心。","溪光何以報，秪有醉和吟。"]', '["相近复相尋，山僧與水禽。","煙蓑春釣静，雪屋夜棊深。","雅道誰开口，时风未醒心。","溪光何以報，秪有醉和吟。"]', '诗', 'shi', '', NULL, '郊園 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdaf8a32-59c0-4a7f-bc59-5ac03039d462', '郊野', '郊野', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["蓼水菊籬邊，新晴有亂蟬。","秋光終寂寞，晚醉自留連。","野溼禾中露，村閑社後天。","題詩滿紅葉，何必浣花牋。"]', '["蓼水菊籬邊，新晴有亂蟬。","秋光終寂寞，晚醉自留連。","野溼禾中露，村闲社後天。","題诗满紅葉，何必浣花牋。"]', '诗', 'shi', '', NULL, '郊野 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c961f5-8b17-490e-85ae-d5683209cdf9', '旅寓洛南村舍', '旅寓洛南村舍', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["村落清明近，鞦韆稚女誇。","春陰妨柳絮，月黑見棃花。","白鳥窺魚網，青帘認酒家。","幽棲雖自適，交友在京華。"]', '["村落清明近，鞦韆稚女誇。","春陰妨柳絮，月黑见棃花。","白鸟窺鱼網，青帘認酒家。","幽棲雖自適，交友在京华。"]', '诗', 'shi', '', NULL, '旅寓洛南村舍 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edc670e-fba6-4ea4-a065-392c9c44d072', '杏花', '杏花', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["不學梅欺雪，輕紅照碧池。","小桃新謝後，雙燕却來時。","香屬燈龍客，煙籠宿蝶枝。","臨軒須貌取，風雨易離披。"]', '["不学梅欺雪，轻紅照碧池。","小桃新謝後，雙燕却来时。","香屬灯龙客，煙籠宿蝶枝。","臨軒須貌取，风雨易離披。"]', '诗', 'shi', '', NULL, '杏花 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb3bfb5-5650-4e39-af14-db6e633330c0', '水林檎花', '水林檎花', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["一露一朝新，簾櫳曉景分。","豔和蜂蝶動，香帶管弦聞。","笑擬春無力，粧濃酒漸醺。","直疑風起夜，飛去替行雲。"]', '["一露一朝新，簾櫳晓景分。","豔和蜂蝶动，香带管弦闻。","笑擬春無力，粧濃酒漸醺。","直疑风起夜，飞去替行云。"]', '诗', 'shi', '', NULL, '水林檎花 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b50631-cdd2-48d5-b829-1d3e179049da', '蓼花', '蓼花', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["蔟蔟復悠悠，年年拂漫流。","差池伴黃菊，冷澹過清秋。","晚帶鳴蟲急，寒藏宿鷺愁。","故溪歸不得，憑仗繫漁舟。"]', '["蔟蔟复悠悠，年年拂漫流。","差池伴黄菊，冷澹過清秋。","晚带鳴蟲急，寒藏宿鷺愁。","故溪归不得，憑仗繫漁舟。"]', '诗', 'shi', '', NULL, '蓼花 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5e53b8-bbd0-445b-a602-02bdabf5d47d', '江梅', '江梅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江梅且緩飛，前輩有歌詞。","莫惜黃金縷，難忘白雪枝。","吟看歸不得，醉嗅立如癡。","和雨和煙折，含情寄所思。"]', '["江梅且緩飞，前輩有歌词。","莫惜黄金縷，难忘白雪枝。","吟看归不得，醉嗅立如癡。","和雨和煙折，含情寄所思。"]', '诗', 'shi', '', NULL, '江梅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4025c151-c833-40b1-b6a9-0342bc6b816d', '茘枝', '茘枝', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平昔誰相愛，驪山遇貴妃。","枉教生處遠，愁見摘來稀。","晚奪紅霞色，晴欺瘴日威。","南荒何所戀，爲爾即忘歸。"]', '["平昔誰相愛，驪山遇貴妃。","枉教生处远，愁见摘来稀。","晚奪紅霞色，晴欺瘴日威。","南荒何所戀，爲爾即忘归。"]', '诗', 'shi', '', NULL, '茘枝 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e12a588-8609-4627-a26d-db2e732a9927', '駐蹕華下同年司封員外從翁許共遊西溪久違前契戲成寄贈', '駐蹕华下同年司封員外從翁許共游西溪久違前契戲成寄贈', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["北渚牽吟興，西溪爽共遊。","指期乘禁馬，無暇狎沙鷗。","縱目懷青島，澄心想碧流。","明公非不愛，應待泛龍舟。"]', '["北渚牽吟兴，西溪爽共游。","指期乘禁马，無暇狎沙鷗。","縱目懷青島，澄心想碧流。","明公非不愛，應待泛龙舟。"]', '诗', 'shi', '', NULL, '駐蹕華下同年司封員外從翁許共遊西溪久違前契戲成寄贈 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639b6207-dfa0-4ec5-a043-32e1ae007fe1', '谷自亂離之後在西蜀半紀之餘多寓止精舍與圓昉上人爲淨侶昉公於長松山舊齋嘗約他日訪會勞生多故遊宦數年曩契未諧忽聞謝世愴吟四韻以弔之', '谷自亂離之後在西蜀半紀之餘多寓止精舍與圓昉上人爲淨侶昉公於长松山旧斋嘗約他日訪會勞生多故游宦數年曩契未諧忽闻謝世愴吟四韻以弔之', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["每思聞淨話，雨夜對禪牀。","未得重相見，秋燈照影堂。","孤雲終負約，薄宦轉堪傷。","夢繞長松塔，遙焚一炷香。"]', '["每思闻淨話，雨夜对禪牀。","未得重相见，秋灯照影堂。","孤云終負約，薄宦轉堪傷。","梦繞长松塔，遙焚一炷香。"]', '诗', 'shi', '', NULL, '谷自亂離之後在西蜀半紀之餘多寓止精舍與圓昉上人爲淨侶昉公於長松山舊齋嘗約他日訪會勞生多故遊宦數年曩契未諧忽聞謝世愴吟四韻以弔之 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5dcd5e2-6b25-495b-8daf-8743c3782e75', '投時相十韻', '投时相十韻', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["何以保孤危，操修自不知。","衆中常杜口，夢裏亦吟詩。","失計辭山早，非才得仕遲。","薄冰安可履，暗室豈能欺。","勤苦流螢信，吁嗟宿燕知。","殘鐘殘漏曉，落葉落花時。","故舊寒門少，文章外族衰。","此生多轗軻，半世足漂離。","省署隨清品，漁舟爽素期。","戀恩休未遂，雙鬢漸成絲。"]', '["何以保孤危，操修自不知。","衆中常杜口，梦裏亦吟诗。","失計辞山早，非才得仕遲。","薄冰安可履，暗室豈能欺。","勤苦流螢信，吁嗟宿燕知。","殘鐘殘漏晓，落葉落花时。","故旧寒门少，文章外族衰。","此生多轗軻，半世足漂離。","省署隨清品，漁舟爽素期。","戀恩休未遂，雙鬢漸成絲。"]', '诗', 'shi', '', NULL, '投時相十韻 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8e1cb8a-01e7-4fbf-b7d1-e3c3f4cc876b', '喜秀上人相訪', '喜秀上人相訪', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["雪初開一徑，師忽扣雙扉。","老大情相近，林泉約共歸。","憂榮棲省署，孤僻謝朝衣。","他夜松堂宿，論詩更入微。"]', '["雪初开一徑，師忽扣雙扉。","老大情相近，林泉約共归。","憂榮棲省署，孤僻謝朝衣。","他夜松堂宿，論诗更入微。"]', '诗', 'shi', '', NULL, '喜秀上人相訪 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2629a7-6b44-45ea-8104-4f05fdfd9871', '夕陽', '夕陽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["夕陽秋更好，斂斂蕙蘭中。","極浦明殘雨，長天急遠鴻。","僧窗留半榻，漁舸透疎篷。","莫恨清光盡，寒蟾即照空。"]', '["夕陽秋更好，斂斂蕙蘭中。","極浦明殘雨，长天急远鴻。","僧窗留半榻，漁舸透疎篷。","莫恨清光尽，寒蟾即照空。"]', '诗', 'shi', '', NULL, '夕陽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c15ef36-3a47-4d75-853d-dbdd53fcc25b', '搖落', '搖落', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["夜來搖落悲，桑棗半空枝。","故國無消息，流年有亂離。","霜秦聞雁早，煙渭認帆遲。","日暮寒鼙急，邊軍在雍岐。"]', '["夜来搖落悲，桑棗半空枝。","故国無消息，流年有亂離。","霜秦闻雁早，煙渭認帆遲。","日暮寒鼙急，邊軍在雍岐。"]', '诗', 'shi', '', NULL, '搖落 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c435ade-6a08-4d6e-9b1b-5f3d47225358', '西蜀淨衆寺松溪八韻兼寄小筆崔處士', '西蜀淨衆寺松溪八韻兼寄小笔崔处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["松因溪得名，溪吹荅松聲。","繚繞能穿寺，幽奇不在城。","寒煙齋後散，春雨夜中平。","染岸蒼苔古，翹沙白鳥明。","澄分僧影瘦，光徹客心清。","帶梵侵雲響，和鐘擊石鳴。","澹烹新茗爽，暖泛落花輕。","此景吟難盡，憑君畫入京。"]', '["松因溪得名，溪吹荅松声。","繚繞能穿寺，幽奇不在城。","寒煙斋後散，春雨夜中平。","染岸蒼苔古，翹沙白鸟明。","澄分僧影瘦，光徹客心清。","带梵侵云响，和鐘擊石鳴。","澹烹新茗爽，暖泛落花轻。","此景吟难尽，憑君畫入京。"]', '诗', 'shi', '', NULL, '西蜀淨衆寺松溪八韻兼寄小筆崔處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b10c1e3d-fbbc-4f9a-864a-16e76002ae92', '遷客', '遷客', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["離夜聞橫笛，可堪吹鷓鴣。","雪冤知早晚，雨泣渡江湖。","秋樹吹黃葉，臘煙垂綠蕪。","虞飜歸有日，莫便哭窮途。"]', '["離夜闻橫笛，可堪吹鷓鴣。","雪冤知早晚，雨泣渡江湖。","秋樹吹黄葉，臘煙垂綠蕪。","虞飜归有日，莫便哭窮途。"]', '诗', 'shi', '', NULL, '遷客 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42001782-6af8-43f1-bb05-30413abae062', '蔡處士', '蔡处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["無著復無求，平生不解愁。","鬻蔬貧潔淨，中酒病風流。","旨趣陶山相，詩篇沈隱侯。","小齋江色裏，籬柱繫漁舟。"]', '["無著复無求，平生不解愁。","鬻蔬貧潔淨，中酒病风流。","旨趣陶山相，诗篇沈隐侯。","小斋江色裏，籬柱繫漁舟。"]', '诗', 'shi', '', NULL, '蔡處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b137e4-35f7-4f28-9e97-89d4cb79c778', '予嘗有雪景一絕爲人所諷吟段贊善小筆精微忽爲圖畫以詩謝之', '予嘗有雪景一絕爲人所諷吟段贊善小笔精微忽爲圖畫以诗謝之', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["贊善賢相後，家藏名畫多。","留心於繪素，得事在煙波。","屬興同吟詠，成功更琢磨。","愛予風雪句，幽絕寫漁蓑。"]', '["贊善賢相後，家藏名畫多。","留心於繪素，得事在煙波。","屬兴同吟詠，成功更琢磨。","愛予风雪句，幽絕寫漁蓑。"]', '诗', 'shi', '', NULL, '予嘗有雪景一絕爲人所諷吟段贊善小筆精微忽爲圖畫以詩謝之 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029035db-1d9b-47e1-98cb-d814c582100e', '京兆府試殘月如新月', '京兆府試殘月如新月', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["榮落何相似，初終却一般。","猶疑和夕照，誰信墮朝寒。","水木輝華別，詩家比象難。","佳人應誤拜，棲鳥反求安。","屈指期輪滿，何心謂影殘。","庾樓清賞處，吟徹曙鐘看。"]', '["榮落何相似，初終却一般。","猶疑和夕照，誰信墮朝寒。","水木輝华別，诗家比象难。","佳人應誤拜，棲鸟反求安。","屈指期輪满，何心謂影殘。","庾楼清賞处，吟徹曙鐘看。"]', '诗', 'shi', '', NULL, '京兆府試殘月如新月 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26d054c-8c60-463f-8f57-9a6ef196d548', '咸通十四年府試木向榮', '咸通十四年府試木向榮', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["園林青氣動，衆木散寒聲。","敗葉牆陰在，滋條雪後榮。","欣欣春令早，藹藹日華輕。","庾嶺梅先覺，隋堤柳暗驚。","山川應物候，臯壤起農情。","秪待花開日，連棲出谷鶯。"]', '["园林青氣动，衆木散寒声。","敗葉牆陰在，滋條雪後榮。","欣欣春令早，藹藹日华轻。","庾嶺梅先覺，隋堤柳暗驚。","山川應物候，臯壤起農情。","秪待花开日，連棲出谷鶯。"]', '诗', 'shi', '', NULL, '咸通十四年府試木向榮 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7390a1-9db7-4b50-8fb9-870a02eeaaf8', '丞相孟夏祗薦南郊紀獻十韻', '丞相孟夏祗薦南郊紀獻十韻', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["節應清和候，郊宮事潔羞。","至誠聞上帝，明德祀圓丘。","雅用陶匏器，馨非黍稷流。","就陽陳盛禮，匡國禱鴻休。","漸曉蘭迎露，微涼麥弄秋。","壽山橫紫閣，瑞靄抱皇州。","外肅通班序，中嚴錫慶優。","奏歌三酒備，表敬百神柔。","池碧將還鳳，原清再問牛。","萬方瞻輔翼，共賀贊皇猷。"]', '["節應清和候，郊宮事潔羞。","至誠闻上帝，明德祀圓丘。","雅用陶匏器，馨非黍稷流。","就陽陳盛禮，匡国禱鴻休。","漸晓蘭迎露，微涼麦弄秋。","壽山橫紫閣，瑞靄抱皇州。","外肅通班序，中嚴錫慶優。","奏歌三酒備，表敬百神柔。","池碧將還鳳，原清再问牛。","万方瞻輔翼，共賀贊皇猷。"]', '诗', 'shi', '', NULL, '丞相孟夏祗薦南郊紀獻十韻 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('596fc3d9-7ede-4f15-9b92-843081cb8f82', '敘事感恩上狄右丞', '敘事感恩上狄右丞', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["昔歲曾投贄，關河在左馮。","庾公垂顧遇，王粲許從容。","首薦叨殊禮，全家寓近封。","白樓陪寫望，青眼感遭逢。","顧念梁間燕，深憐澗底松。","嵐光蓮嶽逼，酒味菊花濃。","寇難旋移國，漂離幾聽蛩。","半生悲逆旅，二紀間門墉。","蜀雪隨僧蹋，荆煙逐雁衝。","凋零歸兩鬢，舉止失前蹤。","得事雖甘晚，陳詩未肯慵。","邇來趨九仞，又伴賞三峯。","棲託情何限，吹噓意數重。","自茲儔侶內，無復歎龍鍾。"]', '["昔歲曾投贄，关河在左馮。","庾公垂顧遇，王粲許從容。","首薦叨殊禮，全家寓近封。","白楼陪寫望，青眼感遭逢。","顧念梁间燕，深怜澗底松。","嵐光蓮嶽逼，酒味菊花濃。","寇难旋移国，漂離幾听蛩。","半生悲逆旅，二紀间门墉。","蜀雪隨僧蹋，荆煙逐雁衝。","凋零归兩鬢，舉止失前蹤。","得事雖甘晚，陳诗未肯慵。","邇来趨九仞，又伴賞三峯。","棲託情何限，吹噓意數重。","自茲儔侶內，無复歎龙鍾。"]', '诗', 'shi', '', NULL, '敘事感恩上狄右丞 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6e25ab-fa24-45d4-aceb-873ef5ce1bc6', '詠懷', '詠懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["迂疎雖可欺，心路甚男兒。","薄宦渾無味，平生粗有詩。","澹交終不破，孤達晚相宜。","直夜花前喚，朝寒雪裏追。","竹聲輸我聽，茶格共僧知。","景物還多感，情懷偶不卑。","溪鶯喧午寢，山蕨止春飢。","險事銷腸酒，清歡敵手棋。","香鋤拋藥圃，煙艇憶莎陂。","自許亨途在，儒綱復振時。"]', '["迂疎雖可欺，心路甚男兒。","薄宦渾無味，平生粗有诗。","澹交終不破，孤達晚相宜。","直夜花前喚，朝寒雪裏追。","竹声輸我听，茶格共僧知。","景物還多感，情懷偶不卑。","溪鶯喧午寢，山蕨止春飢。","險事銷腸酒，清歡敵手棋。","香鋤拋藥圃，煙艇憶莎陂。","自許亨途在，儒綱复振时。"]', '诗', 'shi', '', NULL, '詠懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e65aa2-c466-461d-a8aa-b23ab172c0e1', '乾符丙申歲奉試春漲曲江池', '乾符丙申歲奉試春漲曲江池', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["王澤尚通津，恩波此日新。","深疑一夜雨，宛似五湖春。","泛灩翹振鷺，澄清躍紫鱗。","翠低孤嶼柳，香失半汀蘋。","鳳輦尋佳境，龍舟命近臣。","桂花如入手，願作從遊人。"]', '["王澤尚通津，恩波此日新。","深疑一夜雨，宛似五湖春。","泛灩翹振鷺，澄清躍紫鱗。","翠低孤嶼柳，香失半汀蘋。","鳳輦尋佳境，龙舟命近臣。","桂花如入手，願作從游人。"]', '诗', 'shi', '', NULL, '乾符丙申歲奉試春漲曲江池 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee0595b-7702-42a8-86e6-d5457feb6625', '華山', '华山', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["峭仞聳巍巍，晴嵐染近畿。","孤高不可狀，圖寫盡應非。","絕頂神仙會，半空鸞鶴歸。","雲臺分遠靄，樹谷隱斜暉。","墜石連村響，狂雷發廟威。","氣中寒渭闊，影外白樓微。","雲對蓮花落，泉橫露掌飛。","乳懸危磴滑，樵徹上方稀。","澹泊生真趣，逍遙息世機。","野花明澗路，春蘚澀松圍。","遠洞時聞磬，羣僧晝掩扉。","他年洗塵骨，香火願相依。"]', '["峭仞聳巍巍，晴嵐染近畿。","孤高不可狀，圖寫尽應非。","絕頂神仙會，半空鸾鹤归。","云台分远靄，樹谷隐斜暉。","墜石連村响，狂雷發廟威。","氣中寒渭闊，影外白楼微。","云对蓮花落，泉橫露掌飞。","乳懸危磴滑，樵徹上方稀。","澹泊生真趣，逍遙息世機。","野花明澗路，春蘚澀松圍。","远洞时闻磬，羣僧晝掩扉。","他年洗塵骨，香火願相依。"]', '诗', 'shi', '', NULL, '華山 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('872f4732-1448-44f6-9e66-853f19501dfb', '入閣', '入閣', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["祕殿臨軒日，和鑾返正年。","兩班文武盛，百辟羽儀全。","霜漏清中禁，風旗拂曙天。","門嚴新勘契，仗入乍承宣。","玉几當紅旭，金鑪縱碧煙。","對揚稱法吏，贊引出宮鈿。","言動揮毫疾，雍容執簿專。","壽山晴靉靆，顥氣暖連延。","禮有鴛鸞集，恩無雨露偏。","小臣叨備位，歌詠泰階前。"]', '["祕殿臨軒日，和鑾返正年。","兩班文武盛，百辟羽儀全。","霜漏清中禁，风旗拂曙天。","门嚴新勘契，仗入乍承宣。","玉几當紅旭，金鑪縱碧煙。","对揚稱法吏，贊引出宮鈿。","言动揮毫疾，雍容執簿專。","壽山晴靉靆，顥氣暖連延。","禮有鴛鸾集，恩無雨露偏。","小臣叨備位，歌詠泰階前。"]', '诗', 'shi', '', NULL, '入閣 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ccb5e28-07e5-4b46-9673-a9624c8abd7d', '故少師從翁隱巖別墅亂後榛蕪感舊愴懷遂有追紀', '故少師從翁隐巖別墅亂後榛蕪感旧愴懷遂有追紀', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["風騷爲主人，凡俗仰清塵。","密行稱閨閫，明誠動搢紳。","周旋居顯重，內外掌絲綸。","妙主蓬壺籍，忠爲社稷臣。","大儀牆仞峻，東轄紀綱新。","聞善常開口，推公豈爲身。","立朝鳴珮重，歸宅典衣貧。","半醉看花晚，中餐煮菜春。","晴臺隨鹿上，幽墅結僧鄰。","理論知清越，生徒得李頻。","藥香沾筆硯，竹色染衣巾。","寄鶴眠雲叟，騎驢入室賓。","近將姚監比，僻與段卿親。","葉積池邊路，茶遲雪後薪。","所難留著述，誰不秉陶鈞。","喪亂時多變，追思事已陳。","浮華重發作，雅正甚湮淪。","宗從今何在，依棲素有因。","七松無影響，雙淚益悲辛。","猶喜于門秀，年來屈復伸。"]', '["风騷爲主人，凡俗仰清塵。","密行稱閨閫，明誠动搢紳。","周旋居显重，內外掌絲綸。","妙主蓬壺籍，忠爲社稷臣。","大儀牆仞峻，东轄紀綱新。","闻善常开口，推公豈爲身。","立朝鳴珮重，归宅典衣貧。","半醉看花晚，中餐煮菜春。","晴台隨鹿上，幽墅結僧鄰。","理論知清越，生徒得李頻。","藥香沾笔硯，竹色染衣巾。","寄鹤眠云叟，騎驢入室賓。","近將姚監比，僻與段卿親。","葉積池邊路，茶遲雪後薪。","所难留著述，誰不秉陶鈞。","喪亂时多变，追思事已陳。","浮华重發作，雅正甚湮淪。","宗從今何在，依棲素有因。","七松無影响，雙泪益悲辛。","猶喜于门秀，年来屈复伸。"]', '诗', 'shi', '', NULL, '故少師從翁隱巖別墅亂後榛蕪感舊愴懷遂有追紀 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d69efa5c-b12b-49b8-8c2e-e894c6174482', '送吏部曹郎中免官南歸', '送吏部曹郎中免官南归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["高名向已求，古韻古無儔。","風月拋蘭省，江山復桂州。","賢人知止足，中歲便歸休。","雲鶴深相待，公卿不易留。","滿朝張祖席，半路上仙舟。","篋重藏吳畫，茶新換越甌。","郡迎紅燭宴，寺宿翠嵐樓。","觸目成幽興，全家是勝遊。","篷聲漁叟雨，葦色鷺鷥秋。","久別郊園改，將歸里巷修。","桑麻勝祿食，節序免鄉愁。","陽朔花迎櫂，崇賢葉滿溝。","席春歡促膝，簷日暖梳頭。","道暢應爲蝶，時來必問牛。","終須康庶品，未爽漱寒流。","議在歸羣望，情難戀自由。","小生誠淺拙，早歲便依投。","夏課每垂獎，雪天常見憂。","遠招陪宿直，首薦向公侯。","攀送偏揮灑，龍鍾志未酬。"]', '["高名向已求，古韻古無儔。","风月拋蘭省，江山复桂州。","賢人知止足，中歲便归休。","云鹤深相待，公卿不易留。","满朝張祖席，半路上仙舟。","篋重藏吳畫，茶新換越甌。","郡迎紅燭宴，寺宿翠嵐楼。","觸目成幽兴，全家是勝游。","篷声漁叟雨，葦色鷺鷥秋。","久別郊园改，將归里巷修。","桑麻勝祿食，節序免乡愁。","陽朔花迎櫂，崇賢葉满溝。","席春歡促膝，簷日暖梳头。","道暢應爲蝶，时来必问牛。","終須康庶品，未爽漱寒流。","議在归羣望，情难戀自由。","小生誠淺拙，早歲便依投。","夏課每垂獎，雪天常见憂。","远招陪宿直，首薦向公侯。","攀送偏揮灑，龙鍾志未酬。"]', '诗', 'shi', '', NULL, '送吏部曹郎中免官南歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0fd54c-8222-449b-a52b-0b1c2df9d7cf', '迴鑾', '迴鑾', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["妖星沈雨露，和氣滿京關。","上將忠勳立，明君法駕還。","順風調雅樂，夾道序羣班。","香泛傳宣裏，塵清指顧間。","樓臺新紫氣，雲物舊黃山。","曉渭行朝肅，秋郊曠望閑。","廟靈安國步，日角動天顏。","浩浩昇平曲，流歌徹百蠻。"]', '["妖星沈雨露，和氣满京关。","上將忠勳立，明君法駕還。","順风調雅乐，夾道序羣班。","香泛傳宣裏，塵清指顧间。","楼台新紫氣，云物旧黄山。","晓渭行朝肅，秋郊曠望闲。","廟靈安国步，日角动天顏。","浩浩昇平曲，流歌徹百蠻。"]', '诗', 'shi', '', NULL, '迴鑾 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccdd14b6-eaf7-4474-aa8e-71ad4b68776f', '峽中', '峽中', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["萬重煙靄裏，隱隱見夔州。","夜靜明月峽，春寒堆雪樓。","獨吟誰會解，多病自淹留。","往事如今日，聊同子美愁。"]', '["万重煙靄裏，隐隐见夔州。","夜静明月峽，春寒堆雪楼。","独吟誰會解，多病自淹留。","往事如今日，聊同子美愁。"]', '诗', 'shi', '', NULL, '峽中 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b59d47a-330e-49f5-a010-715480442350', '蜀中寓止夏日自貽', '蜀中寓止夏日自貽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["展轉攲孤枕，風幃信寂寥。","漲江垂螮蝀，驟雨鬧芭蕉。","道阻歸期晚，年加記性銷。","故人衰颯盡，相望在行朝。"]', '["展轉攲孤枕，风幃信寂寥。","漲江垂螮蝀，驟雨鬧芭蕉。","道阻归期晚，年加記性銷。","故人衰颯尽，相望在行朝。"]', '诗', 'shi', '', NULL, '蜀中寓止夏日自貽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76f3fc48-4f68-4508-8df5-18bc0446820f', '試筆偶書', '試笔偶书', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["沙鳥與山麋，由來性不羈。","可憑唯在道，難解莫過詩。","任笑孤吟僻，終嫌巧宦卑。","秉慵恩地恕，冷澹好僧知。","華省慙公器，滄江負釣師。","露花春直夜，煙鼓早朝時。","世路多艱梗，家風免墜遺。","殷勤一蓑雨，秪得夢中披。"]', '["沙鸟與山麋，由来性不羈。","可憑唯在道，难解莫過诗。","任笑孤吟僻，終嫌巧宦卑。","秉慵恩地恕，冷澹好僧知。","华省慙公器，滄江負釣師。","露花春直夜，煙鼓早朝时。","世路多艱梗，家风免墜遺。","殷勤一蓑雨，秪得梦中披。"]', '诗', 'shi', '', NULL, '試筆偶書 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c392f97-7bd3-4852-bf19-dff9a57959e1', '奔避', '奔避', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["奔避投人遠，漂離易感恩。","愁髯霜颯颯，病眼淚昏昏。","孤館秋聲樹，寒江落照村。","更聞歸路絕，新寨截荆門。"]', '["奔避投人远，漂離易感恩。","愁髯霜颯颯，病眼泪昏昏。","孤館秋声樹，寒江落照村。","更闻归路絕，新寨截荆门。"]', '诗', 'shi', '', NULL, '奔避 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb593305-d63e-4a25-8837-a9c5602c51c7', '弔水部賈員外嵩', '弔水部賈員外嵩', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["八韻與五字，俱爲時所先。","幽魂應自慰，李白墓相連。"]', '["八韻與五字，俱爲时所先。","幽魂應自慰，李白墓相連。"]', '诗', 'shi', '', NULL, '弔水部賈員外嵩 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43451543-6873-4b74-8ae6-443d6650bacb', '貧女吟', '貧女吟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["塵壓鴛鴦廢錦機，滿頭空插麗春枝。","東鄰舞妓多金翠，笑翦燈花學畫眉。"]', '["塵壓鴛鴦廢錦機，满头空插丽春枝。","东鄰舞妓多金翠，笑翦灯花学畫眉。"]', '诗', 'shi', '', NULL, '貧女吟 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b73ec545-cb4d-43a9-b424-80c4346161b9', '席上貽歌者', '席上貽歌者', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["花月樓臺近九衢，清歌一曲倒金壺。","座中亦有江南客，莫向春風唱鷓鴣。"]', '["花月楼台近九衢，清歌一曲倒金壺。","座中亦有江南客，莫向春风唱鷓鴣。"]', '诗', 'shi', '', NULL, '席上貽歌者 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3badcd-8fe5-4b33-9579-8fbf0d8bd832', '菊', '菊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["王孫莫把比荆蒿，九日枝枝近鬢毛。","露溼秋香滿池岸，由來不羨瓦松高。"]', '["王孫莫把比荆蒿，九日枝枝近鬢毛。","露溼秋香满池岸，由来不羨瓦松高。"]', '诗', 'shi', '', NULL, '菊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80f30bc0-5dff-4590-be24-2d05f01e2efa', '下峽', '下峽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["憶子啼猨繞樹哀，雨隨孤櫂過陽臺。","波頭未白人頭白，瞥見春風灩澦堆。"]', '["憶子啼猨繞樹哀，雨隨孤櫂過陽台。","波头未白人头白，瞥见春风灩澦堆。"]', '诗', 'shi', '', NULL, '下峽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('654b40e4-60ad-40b9-93d9-0029f1d5c3d8', '文昌寓直', '文昌寓直', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["何遜空堦夜雨平，朝來交直雨新晴。","落花亂上花塼上，不忍和苔蹋紫英。"]', '["何遜空堦夜雨平，朝来交直雨新晴。","落花亂上花塼上，不忍和苔蹋紫英。"]', '诗', 'shi', '', NULL, '文昌寓直 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d442dd-3225-447a-831f-10a42c3d64e8', '街西晚歸', '街西晚归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["御溝春水繞閑坊，信馬歸來傍短牆。","幽榭名園臨紫陌，晚風時帶牡丹香。"]', '["御溝春水繞闲坊，信马归来傍短牆。","幽榭名园臨紫陌，晚风时带牡丹香。"]', '诗', 'shi', '', NULL, '街西晚歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bac783-8f0c-4fa5-a73f-d5121fc7069e', '十日菊', '十日菊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["節去蜂愁蝶不知，曉庭還繞折殘枝。","自緣今日人心別，未必秋香一夜衰。"]', '["節去蜂愁蝶不知，晓庭還繞折殘枝。","自緣今日人心別，未必秋香一夜衰。"]', '诗', 'shi', '', NULL, '十日菊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83232d74-f6ea-430d-b560-e0a8449d1fe7', '鷺鷥', '鷺鷥', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["閑立春塘煙澹澹，靜眠寒葦雨颼颼。","漁翁歸後汀沙晚，飛下灘頭更自由。"]', '["闲立春塘煙澹澹，静眠寒葦雨颼颼。","漁翁归後汀沙晚，飞下灘头更自由。"]', '诗', 'shi', '', NULL, '鷺鷥 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4818958-00ac-44d6-878a-14532d2326cd', '柳', '柳', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["半煙半雨江橋畔，暎杏映桃山路中。","會得離人無限意，千絲萬絮惹春風。"]', '["半煙半雨江橋畔，暎杏映桃山路中。","會得離人無限意，千絲万絮惹春风。"]', '诗', 'shi', '', NULL, '柳 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8d15f4-2f71-4af4-82e9-a3a6113f2d6e', '下第退居二首 一', '下第退居二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["年來還未上丹梯，且著漁蓑謝故溪。","落盡梨花春又了，破籬殘雨晚鶯啼。"]', '["年来還未上丹梯，且著漁蓑謝故溪。","落尽梨花春又了，破籬殘雨晚鶯啼。"]', '诗', 'shi', '', NULL, '下第退居二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd5e440-ae9b-4f25-8798-0db66d2ba9db', '下第退居二首 二', '下第退居二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["未嘗青杏出長安，豪士應疑怕牡丹。","秪有退耕耕不得，茫然村落水吹殘。"]', '["未嘗青杏出长安，豪士應疑怕牡丹。","秪有退耕耕不得，茫然村落水吹殘。"]', '诗', 'shi', '', NULL, '下第退居二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70337729-d66c-4603-a0f9-22f4cbe23cd3', '江宿聞蘆管', '江宿闻蘆管', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["塞曲淒清楚水濱，聲聲吹出落梅春。","須知風月千檣下，亦有葫蘆河畔人。"]', '["塞曲淒清楚水濱，声声吹出落梅春。","須知风月千檣下，亦有葫蘆河畔人。"]', '诗', 'shi', '', NULL, '江宿聞蘆管 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5fb4a81-0ceb-473e-a230-d5513ed508d0', '閑題', '闲題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["舉世何人肯自知，須逢精鑑定妍媸。","若教嫫母臨明鏡，也道不勞紅粉施。"]', '["舉世何人肯自知，須逢精鑑定妍媸。","若教嫫母臨明镜，也道不勞紅粉施。"]', '诗', 'shi', '', NULL, '閑題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bc26393-fdcf-4663-b5a7-57a514734715', '曲江春草', '曲江春草', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["花落江堤蔟暖煙，雨餘草色遠相連。","香輪莫輾青青破，留與愁人一醉眠。"]', '["花落江堤蔟暖煙，雨餘草色远相連。","香輪莫輾青青破，留與愁人一醉眠。"]', '诗', 'shi', '', NULL, '曲江春草 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aba7b7c1-6c1a-423a-ba7b-9b715724f4ce', '雪中偶題', '雪中偶題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["亂飄僧舍茶煙溼，密灑歌樓酒力微。","江上晚來堪畫處，漁人披得一蓑歸。"]', '["亂飄僧舍茶煙溼，密灑歌楼酒力微。","江上晚来堪畫处，漁人披得一蓑归。"]', '诗', 'shi', '', NULL, '雪中偶題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906dc08c-4a95-4db4-b759-10ec0ded5ef2', '題慈恩寺默公院', '題慈恩寺默公院', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["雖近曲江居古寺，舊山終憶九華峯。","春來老病厭迎送，翦却牡丹栽野松。"]', '["雖近曲江居古寺，旧山終憶九华峯。","春来老病厭迎送，翦却牡丹栽野松。"]', '诗', 'shi', '', NULL, '題慈恩寺默公院 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb8e3b3-f040-4a79-931f-882f7a17e06e', '江上阻風', '江上阻风', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["水天春暗暮寒濃，船閉篷窗細雨中。","閑道漁家酒初熟，夜來翻喜打頭風。"]', '["水天春暗暮寒濃，船閉篷窗細雨中。","闲道漁家酒初熟，夜来翻喜打头风。"]', '诗', 'shi', '', NULL, '江上阻風 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f2de7e3-e2c9-404f-91e1-8cc2cc96ccd1', '淮上與友人別', '淮上與友人別', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["揚子江頭楊柳春，楊花愁殺渡江人。","數聲風笛離亭晚，君向瀟湘我向秦。"]', '["揚子江头楊柳春，楊花愁殺渡江人。","數声风笛離亭晚，君向瀟湘我向秦。"]', '诗', 'shi', '', NULL, '淮上與友人別 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe2eb19-2420-474b-9140-39ca371e2542', '忍公小軒二首 一', '忍公小軒二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["松溪水色綠於松，每到松溪到暮鐘。","閑得心源秪如此，問禪何必向雙峯。"]', '["松溪水色綠於松，每到松溪到暮鐘。","闲得心源秪如此，问禪何必向雙峯。"]', '诗', 'shi', '', NULL, '忍公小軒二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d160c2-7419-454f-b3c5-de3edc200ab1', '忍公小軒二首 二', '忍公小軒二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["舊遊前事半埃塵，多向林中結淨因。","一念一爐香火裏，後身唯願似師身。"]', '["旧游前事半埃塵，多向林中結淨因。","一念一爐香火裏，後身唯願似師身。"]', '诗', 'shi', '', NULL, '忍公小軒二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d33ec077-5373-4bc0-a83e-70c76bc8cd6b', '淮上漁者', '淮上漁者', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["白頭波上白頭翁，家逐船移浦浦風。","一尺鱸魚新釣得，兒孫吹火荻花中。"]', '["白头波上白头翁，家逐船移浦浦风。","一尺鱸鱼新釣得，兒孫吹火荻花中。"]', '诗', 'shi', '', NULL, '淮上漁者 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178daca9-21e7-4a30-83bc-3f331f43af7e', '興州江館', '兴州江館', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["向蜀還秦計未成，寒蛩一夜繞牀鳴。","愁眠不穩孤燈盡，坐聽嘉陵江水聲。"]', '["向蜀還秦計未成，寒蛩一夜繞牀鳴。","愁眠不穩孤灯尽，坐听嘉陵江水声。"]', '诗', 'shi', '', NULL, '興州江館 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be99aff-72d8-45a2-a6bd-deccd1d5e4bf', '題無本上人小齋', '題無本上人小斋', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寒寺唯應我訪師，人稀境靜雪銷遲。","竹西落照侵窗好，堪惜歸時落照時。"]', '["寒寺唯應我訪師，人稀境静雪銷遲。","竹西落照侵窗好，堪惜归时落照时。"]', '诗', 'shi', '', NULL, '題無本上人小齋 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6e702e7-8152-4e00-b61f-b3208ecfe3d9', '七祖院小山', '七祖院小山', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["小巧功成雨蘚斑，軒車日日扣松關。","峨嵋咫尺無人去，却向僧窗看假山。"]', '["小巧功成雨蘚斑，軒车日日扣松关。","峨嵋咫尺無人去，却向僧窗看假山。"]', '诗', 'shi', '', NULL, '七祖院小山 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbed17cc-1187-499c-8ebe-885e5352e708', '定水寺行香', '定水寺行香', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["聽經看畫繞虛廊，風拂金鑪待賜香。","丞相未來春雪密，暫偷閑臥老僧牀。"]', '["听經看畫繞虛廊，风拂金鑪待賜香。","丞相未来春雪密，暫偷闲臥老僧牀。"]', '诗', 'shi', '', NULL, '定水寺行香 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618dc75f-4bc9-4f52-b1aa-ef8efdea4d8c', '浯溪', '浯溪', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["湛湛清江疊疊山，白雲白鳥在其間。","漁翁醉睡又醒睡，誰道皇天最惜閑。"]', '["湛湛清江叠叠山，白云白鸟在其间。","漁翁醉睡又醒睡，誰道皇天最惜闲。"]', '诗', 'shi', '', NULL, '浯溪 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46a7691d-245f-4041-ac5d-90e93e70ec08', '悶題', '悶題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["莫厭九衢塵土間，秋晴滿眼是南山。","僧家未必全無事，道著訪僧心且閑。"]', '["莫厭九衢塵土间，秋晴满眼是南山。","僧家未必全無事，道著訪僧心且闲。"]', '诗', 'shi', '', NULL, '悶題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6722aeca-5845-49a6-9d57-3c463edf71cf', '重訪黃神谷策禪者', '重訪黄神谷策禪者', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["初塵芸閣辭禪閣，却訪支郎是老郎。","我趣轉卑師趣靜，數峯秋雪一鑪香。"]', '["初塵芸閣辞禪閣，却訪支郎是老郎。","我趣轉卑師趣静，數峯秋雪一鑪香。"]', '诗', 'shi', '', NULL, '重訪黃神谷策禪者 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a14f0606-1082-429c-9740-88ef29b9a4eb', '別修覺寺無本上人', '別修覺寺無本上人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["松上閑雲石上苔，自嫌歸去夕陽催。","山門握手無他語，秪約今冬看雪來。"]', '["松上闲云石上苔，自嫌归去夕陽催。","山门握手無他語，秪約今冬看雪来。"]', '诗', 'shi', '', NULL, '別修覺寺無本上人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f5608f-bbb5-4e8d-b5d4-6d1854073449', '贈日東鑒禪師', '贈日东鑒禪師', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["故國無心渡海潮，老禪方丈倚中條。","夜深雨絕松堂靜，一點山螢照寂寥。"]', '["故国無心渡海潮，老禪方丈倚中條。","夜深雨絕松堂静，一点山螢照寂寥。"]', '诗', 'shi', '', NULL, '贈日東鑒禪師 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3963c22c-9593-403c-a916-43c48fb3a28c', '傳經院壁畫松', '傳經院壁畫松', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["危根瘦盡聳孤峯，珍重江僧好筆蹤。","得向遊人多處畫，却勝澗底作真松。"]', '["危根瘦尽聳孤峯，珍重江僧好笔蹤。","得向游人多处畫，却勝澗底作真松。"]', '诗', 'shi', '', NULL, '傳經院壁畫松 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30e21513-3d67-47cb-ac04-437f0eef98b7', '高蟾先輩以詩筆相示抒成寄酬', '高蟾先輩以诗笔相示抒成寄酬', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["張生故國三千里，知者唯應杜紫微。","君有君恩秋後葉，可能更羨謝玄暉。"]', '["張生故国三千里，知者唯應杜紫微。","君有君恩秋後葉，可能更羨謝玄暉。"]', '诗', 'shi', '', NULL, '高蟾先輩以詩筆相示抒成寄酬 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('680cc1ce-564a-4277-8995-8179a194bd68', '爲人題', '爲人題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["淚溼孤鸞曉鏡昏，近來方解惜青春。","杏花楊柳年年好，不忍迴看舊寫真。"]', '["泪溼孤鸾晓镜昏，近来方解惜青春。","杏花楊柳年年好，不忍迴看旧寫真。"]', '诗', 'shi', '', NULL, '爲人題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9231dc68-8a85-4b71-b4cd-446b4348c5df', '越鳥', '越鸟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["背霜南雁不到處，倚櫂北人初聽時。","梅雨滿江春草歇，一聲聲在荔枝枝。"]', '["背霜南雁不到处，倚櫂北人初听时。","梅雨满江春草歇，一声声在荔枝枝。"]', '诗', 'shi', '', NULL, '越鳥 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a59242e-34dc-4bcf-a9af-eb6587c834c5', '黃鶯', '黄鶯', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["春雲薄薄日輝輝，宮樹煙深隔水飛。","應爲能歌繫仙籍，麻姑乞與女真衣。"]', '["春云薄薄日輝輝，宮樹煙深隔水飞。","應爲能歌繫仙籍，麻姑乞與女真衣。"]', '诗', 'shi', '', NULL, '黃鶯 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e6d179-bdbf-4954-ad84-f036c6983adb', '失鷺鷥', '失鷺鷥', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["野格由來倦小池，驚飛却下碧江涯。","月昏風急何處宿，秋岸蕭蕭黃葦枝。"]', '["野格由来倦小池，驚飞却下碧江涯。","月昏风急何处宿，秋岸蕭蕭黄葦枝。"]', '诗', 'shi', '', NULL, '失鷺鷥 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c1af3d-96a8-4ebd-946c-ee5059f3e4b2', '苔錢', '苔錢', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["春紅秋紫繞池臺，箇箇圓如濟世財。","雨後無端滿窮巷，買花不得買愁來。"]', '["春紅秋紫繞池台，箇箇圓如濟世財。","雨後無端满窮巷，買花不得買愁来。"]', '诗', 'shi', '', NULL, '苔錢 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba17fece-e517-4da1-8ff2-f42bf2bacb18', '蓮葉', '蓮葉', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["移舟水濺差差綠，倚檻風搖柄柄香。","多謝浣溪人不折，雨中留得蓋鴛鴦。"]', '["移舟水濺差差綠，倚檻风搖柄柄香。","多謝浣溪人不折，雨中留得蓋鴛鴦。"]', '诗', 'shi', '', NULL, '蓮葉 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a19b3ff0-acdd-4269-8be8-66dc3179e8a9', '蜀中賞海棠', '蜀中賞海棠', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["濃澹芳春滿蜀鄉，半隨風雨斷鶯腸。","浣花溪上堪惆悵，子美無心爲發揚。"]', '["濃澹芳春满蜀乡，半隨风雨斷鶯腸。","浣花溪上堪惆悵，子美無心爲發揚。"]', '诗', 'shi', '', NULL, '蜀中賞海棠 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e32336-f9e0-4bea-8fc6-f9ff2e856a1c', '投所知', '投所知', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["砌下芝蘭新滿徑，門前桃李舊垂陰。","却應迴念江邊草，放出春煙一寸心。"]', '["砌下芝蘭新满徑，门前桃李旧垂陰。","却應迴念江邊草，放出春煙一寸心。"]', '诗', 'shi', '', NULL, '投所知 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10eb92e3-e58f-48c5-8714-76e36a68264e', '早入諫院二首 一', '早入諫院二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["玉階春冷未催班，暫拂塵衣就笏眠。","孤立小心還自笑，夢魂潛繞御鑪煙。"]', '["玉階春冷未催班，暫拂塵衣就笏眠。","孤立小心還自笑，梦魂潛繞御鑪煙。"]', '诗', 'shi', '', NULL, '早入諫院二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b42c40-525e-4e4e-8948-67c6c71004d7', '早入諫院二首 二', '早入諫院二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["紫雲重疊抱春城，廊下人稀唱漏聲。","偷得微吟斜倚柱，滿衣花露聽宮鶯。"]', '["紫云重叠抱春城，廊下人稀唱漏声。","偷得微吟斜倚柱，满衣花露听宮鶯。"]', '诗', 'shi', '', NULL, '早入諫院二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59e6d11-1802-4b45-9683-9a1285a4a006', '忝官諫垣明日轉對', '忝官諫垣明日轉对', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["吾君英睿相君賢，其那寰區未晏然。","明日翠華春殿下，不知何語可聞天。"]', '["吾君英睿相君賢，其那寰區未晏然。","明日翠华春殿下，不知何語可闻天。"]', '诗', 'shi', '', NULL, '忝官諫垣明日轉對 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89508bad-34bd-4808-b008-325bc6500bf7', '再經南陽', '再經南陽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平蕪漠漠失樓臺，昔日遊人亂後來。","寥落牆匡春欲暮，燒殘宮樹有花開。"]', '["平蕪漠漠失楼台，昔日游人亂後来。","寥落牆匡春欲暮，燒殘宮樹有花开。"]', '诗', 'shi', '', NULL, '再經南陽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d3eb9e-0e90-4d0a-8403-a61037d9df12', '贈下第舉公', '贈下第舉公', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["見君失意我惆悵，記得當年落第情。","出去無憀歸又悶，花南慢打講鐘聲。"]', '["见君失意我惆悵，記得當年落第情。","出去無憀归又悶，花南慢打講鐘声。"]', '诗', 'shi', '', NULL, '贈下第舉公 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb3c6cc-f23e-4cfe-8fd6-eebb20dcfbdd', '春陰', '春陰', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["推琴當酒度春陰，不解謀生秪解吟。","舞蝶歌鶯莫相試，老郎心是老僧心。"]', '["推琴當酒度春陰，不解謀生秪解吟。","舞蝶歌鶯莫相試，老郎心是老僧心。"]', '诗', 'shi', '', NULL, '春陰 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960a2d2e-08fe-4838-8dbe-26f949c7ada2', '送張逸人', '送張逸人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["人間疎散更無人，浪兀孤舟酒兀身。","蘆筍鱸魚拋不得，五陵珍重五湖春。"]', '["人间疎散更無人，浪兀孤舟酒兀身。","蘆筍鱸鱼拋不得，五陵珍重五湖春。"]', '诗', 'shi', '', NULL, '送張逸人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997f0b53-31ef-4385-9c98-67f1b9188096', '初還京師寓止府署偶題屋壁', '初還京師寓止府署偶題屋壁', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["秋光不見舊亭臺，四顧荒涼瓦礫堆。","火力不能銷地力，亂前黃菊眼前開。"]', '["秋光不见旧亭台，四顧荒涼瓦礫堆。","火力不能銷地力，亂前黄菊眼前开。"]', '诗', 'shi', '', NULL, '初還京師寓止府署偶題屋壁 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dda4211f-aac5-4da6-9704-9ab6340f92ee', '擢第後入蜀經羅村路見海棠盛開偶有題詠', '擢第後入蜀經羅村路见海棠盛开偶有題詠', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["上國休誇紅杏𦫢，深溪自照綠苔磯。","一枝低帶流鶯睡，數片狂和舞蝶飛。","堪恨路長移不得，可無人與畫將歸。","手中已有新春桂，多謝煙香更入衣。"]', '["上国休誇紅杏𦫢，深溪自照綠苔磯。","一枝低带流鶯睡，數片狂和舞蝶飞。","堪恨路长移不得，可無人與畫將归。","手中已有新春桂，多謝煙香更入衣。"]', '诗', 'shi', '', NULL, '擢第後入蜀經羅村路見海棠盛開偶有題詠 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c9ac1f-494c-4e82-b850-b386b2b5867a', '次韻和禮部盧侍郎江上秋夕寓懷', '次韻和禮部盧侍郎江上秋夕寓懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["盧郎到處覺風生，蜀郡留連亞相情。","亂後江山悲庾信，夜來煙月屬袁宏。","夢歸蘭省寒星動，吟向莎洲宿鷺驚。","未脫白衣頭半白，叨陪屬和倍爲榮。"]', '["盧郎到处覺风生，蜀郡留連亞相情。","亂後江山悲庾信，夜来煙月屬袁宏。","梦归蘭省寒星动，吟向莎洲宿鷺驚。","未脫白衣头半白，叨陪屬和倍爲榮。"]', '诗', 'shi', '', NULL, '次韻和禮部盧侍郎江上秋夕寓懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fb2999d-7cbb-4de7-a718-9b66379f14a0', '宜春再訪芳公言公幽齋寫懷敘事因賦長言', '宜春再訪芳公言公幽斋寫懷敘事因賦长言', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["入門長恐先師在，香印紗燈似昔年。","澗路縈迴齋處遠，松堂虛豁講聲圓。","頃爲弟子曾同社，今忝星郎更契緣。","顧渚一甌春有味，中林話舊亦潸然。"]', '["入门长恐先師在，香印紗灯似昔年。","澗路縈迴斋处远，松堂虛豁講声圓。","頃爲弟子曾同社，今忝星郎更契緣。","顧渚一甌春有味，中林話旧亦潸然。"]', '诗', 'shi', '', NULL, '宜春再訪芳公言公幽齋寫懷敘事因賦長言 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6db9053-985d-4c42-9495-503d4c02a0a7', '讀李白集', '读李白集', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["何事文星與酒星，一時鍾在李先生。","高吟大醉三千首，留著人間伴月明。"]', '["何事文星與酒星，一时鍾在李先生。","高吟大醉三千首，留著人间伴月明。"]', '诗', 'shi', '', NULL, '讀李白集 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a5687d6-9094-4476-9f8e-ba5efb353d17', '卷末偶題三首 一', '卷末偶題三首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["一卷疎蕪一百篇，名成未敢暫忘筌。","何如海日生殘夜，一句能令萬古傳。"]', '["一卷疎蕪一百篇，名成未敢暫忘筌。","何如海日生殘夜，一句能令万古傳。"]', '诗', 'shi', '', NULL, '卷末偶題三首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71380661-618b-42f9-881a-8c1225a52ffa', '卷末偶題三首 二', '卷末偶題三首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["七歲侍行湖外去，岳陽樓上敢題詩。","如今寒晚無功業，何以勝任國士知。"]', '["七歲侍行湖外去，岳陽楼上敢題诗。","如今寒晚無功業，何以勝任国士知。"]', '诗', 'shi', '', NULL, '卷末偶題三首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6ee8f2-ee30-435d-8ba1-3732b3f59a6c', '卷末偶題三首 三', '卷末偶題三首 三', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["一第由來是出身，垂名俱爲國風陳。","此生若不知騷雅，孤宦如何作近臣。"]', '["一第由来是出身，垂名俱爲国风陳。","此生若不知騷雅，孤宦如何作近臣。"]', '诗', 'shi', '', NULL, '卷末偶題三首 三 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cb4e2d0-4f57-48a0-9fca-27d276df44b8', '讀前集二首 一', '读前集二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["殷璠裁鑒英靈集，頗覺同才得旨深。","何事後來高仲武，品題間氣未公心。"]', '["殷璠裁鑒英靈集，頗覺同才得旨深。","何事後来高仲武，品題间氣未公心。"]', '诗', 'shi', '', NULL, '讀前集二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc972335-a8b6-4116-8eb7-2ffbfca6686c', '讀前集二首 二', '读前集二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["風騷如線不勝悲，國步多艱即此時。","愛日滿堦看古集，秪應陶集是吾師。"]', '["风騷如線不勝悲，国步多艱即此时。","愛日满堦看古集，秪應陶集是吾師。"]', '诗', 'shi', '', NULL, '讀前集二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f928d8-6043-4bf1-b75c-6a32ba98462c', '渚宮亂後作', '渚宮亂後作', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["鄉人來話亂離情，淚滴殘陽問紫荆。","白社已應無故老，清江依舊繞空城。","高秋軍旅齊山樹，昔日漁家是野營。","牢落故居灰燼後，黃花紫蔓上牆生。"]', '["乡人来話亂離情，泪滴殘陽问紫荆。","白社已應無故老，清江依旧繞空城。","高秋軍旅齊山樹，昔日漁家是野營。","牢落故居灰燼後，黄花紫蔓上牆生。"]', '诗', 'shi', '', NULL, '渚宮亂後作 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f46c29-328d-4b1a-9460-1df01a53e2c2', '鷓鴣', '鷓鴣', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["暖戲煙蕪錦翼齊，品流應得近山雞。","雨昏青草湖邊過，花落黃陵廟裏啼。","遊子乍聞征袖溼，佳人纔唱翠眉低。","相呼相應湘江闊，苦竹叢深春日西。"]', '["暖戲煙蕪錦翼齊，品流應得近山雞。","雨昏青草湖邊過，花落黄陵廟裏啼。","游子乍闻征袖溼，佳人纔唱翠眉低。","相呼相應湘江闊，苦竹叢深春日西。"]', '诗', 'shi', '', NULL, '鷓鴣 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('123f7d37-7157-47b9-baec-64361e5463ae', '燕', '燕', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["年去年來來去忙，春寒煙暝渡瀟湘。","低飛綠岸和梅雨，亂入紅樓揀杏梁。","閑几硯中窺水淺，落花徑裏得泥香。","千言萬語無人會，又逐流鶯過短牆。"]', '["年去年来来去忙，春寒煙暝渡瀟湘。","低飞綠岸和梅雨，亂入紅楼揀杏梁。","闲几硯中窺水淺，落花徑裏得泥香。","千言万語無人會，又逐流鶯過短牆。"]', '诗', 'shi', '', NULL, '燕 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab113383-0a36-4e52-8247-e451d4529fdb', '侯家鷓鴣', '侯家鷓鴣', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江天梅雨溼江蘺，到處煙香是此時。","苦竹嶺無歸去日，海棠花落舊棲枝。","春宵思極蘭燈暗，曉月啼多錦幕垂。","唯有佳人憶南國，殷勤爲爾唱愁詞。"]', '["江天梅雨溼江蘺，到处煙香是此时。","苦竹嶺無归去日，海棠花落旧棲枝。","春宵思極蘭灯暗，晓月啼多錦幕垂。","唯有佳人憶南国，殷勤爲爾唱愁词。"]', '诗', 'shi', '', NULL, '侯家鷓鴣 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f42e02b4-b83d-4ef8-9fd6-6de2233e3e32', '雁', '雁', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["八月悲風九月霜，蓼花紅澹葦條黃。","石頭城下波搖影，星子灣西雲間行。","驚散漁家吹短笛，失羣征戍鎖殘陽。","故鄉聞爾亦惆悵，何況扁舟非故鄉。"]', '["八月悲风九月霜，蓼花紅澹葦條黄。","石头城下波搖影，星子灣西云间行。","驚散漁家吹短笛，失羣征戍鎖殘陽。","故乡闻爾亦惆悵，何況扁舟非故乡。"]', '诗', 'shi', '', NULL, '雁 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f47f668-da67-4794-97a7-acc4ef897a34', '水', '水', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["竹院松廊分數派，不空清泚亦逶迤。","落花相逐去何處，幽鷺獨來無限時。","洗鉢老僧臨岸久，釣魚閑客捲綸遲。","晚晴一片連莎綠，悔與滄浪有舊期。"]', '["竹院松廊分數派，不空清泚亦逶迤。","落花相逐去何处，幽鷺独来無限时。","洗鉢老僧臨岸久，釣鱼闲客捲綸遲。","晚晴一片連莎綠，悔與滄浪有旧期。"]', '诗', 'shi', '', NULL, '水 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cddf83d8-c0f1-4836-8a02-dff4586528c2', '海棠', '海棠', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["春風用意勻顏色，銷得攜觴與賦詩。","穠麗最宜新著雨，嬌饒全在欲開時。","莫愁粉黛臨窗嬾，梁廣丹青點筆遲。","朝醉暮吟看不足，羨他蝴蝶宿深枝。"]', '["春风用意勻顏色，銷得携觴與賦诗。","穠丽最宜新著雨，嬌饒全在欲开时。","莫愁粉黛臨窗嬾，梁廣丹青点笔遲。","朝醉暮吟看不足，羨他蝴蝶宿深枝。"]', '诗', 'shi', '', NULL, '海棠 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a5278c3-4ed9-4b53-a816-143b0f84e1ce', '竹', '竹', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["宜煙宜雨又宜風，拂水藏村復間松。","移得蕭騷從遠寺，洗來疎淨見前峯。","侵堦蘚拆春芽迸，繞徑莎微夏蔭濃。","無賴杏花多意緒，數枝穿翠好相容。"]', '["宜煙宜雨又宜风，拂水藏村复间松。","移得蕭騷從远寺，洗来疎淨见前峯。","侵堦蘚拆春芽迸，繞徑莎微夏蔭濃。","無賴杏花多意緒，數枝穿翠好相容。"]', '诗', 'shi', '', NULL, '竹 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d4a2546-2823-49c6-94e2-345a96eee0ce', '荔枝樹', '荔枝樹', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["二京曾見畫圖中，數本芳菲色不同。","孤櫂今來巴徼外，一枝煙雨思無窮。","夜郎城近含香瘴，杜宇巢低起暝風。","腸斷渝瀘霜霰薄，不教葉似灞陵紅。"]', '["二京曾见畫圖中，數本芳菲色不同。","孤櫂今来巴徼外，一枝煙雨思無窮。","夜郎城近含香瘴，杜宇巢低起暝风。","腸斷渝瀘霜霰薄，不教葉似灞陵紅。"]', '诗', 'shi', '', NULL, '荔枝樹 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87d992e1-a7ac-451b-be3b-0cfb5be6ad21', '錦二首 一', '錦二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["布素豪家定不看，若無文彩入時難。","紅迷天子帆邊日，紫奪星郎帳外蘭。","春水濯來雲雁活，夜機挑處雨燈寒。","舞衣轉轉求新樣，不問流離桑柘殘。"]', '["布素豪家定不看，若無文彩入时难。","紅迷天子帆邊日，紫奪星郎帳外蘭。","春水濯来云雁活，夜機挑处雨灯寒。","舞衣轉轉求新樣，不问流離桑柘殘。"]', '诗', 'shi', '', NULL, '錦二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c31378-aeef-4759-8c53-e8a6bb5d7490', '錦二首 二', '錦二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["文君手裏曙霞生，美號仍聞借蜀城。","奪得始知袍更貴，著歸方覺晝偏榮。","宮花顏色開時麗，池雁毛衣浴後明。","禮部郎官人所重，省中別占好窠名。"]', '["文君手裏曙霞生，美號仍闻借蜀城。","奪得始知袍更貴，著归方覺晝偏榮。","宮花顏色开时丽，池雁毛衣浴後明。","禮部郎官人所重，省中別占好窠名。"]', '诗', 'shi', '', NULL, '錦二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f78060-c251-4dcd-a434-1c0d0e31565f', '蠟燭', '蠟燭', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["仙漏遲遲出建章，宮簾不動透清光。","金闈露白新裁詔，畫閤春紅正試妝。","淚滴杯盤何所恨，燼飄蘭麝暗和香。","多情更有分明處，照得歌塵下燕梁。"]', '["仙漏遲遲出建章，宮簾不动透清光。","金闈露白新裁詔，畫閤春紅正試妝。","泪滴杯盤何所恨，燼飄蘭麝暗和香。","多情更有分明处，照得歌塵下燕梁。"]', '诗', 'shi', '', NULL, '蠟燭 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('439e2810-3d95-4b55-8888-d1db2708d928', '燈', '灯', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["雨向莎堦滴未休，冷光孤恨雨悠悠。","船中聞雁洞庭宿，牀下有蛩長信秋。","背照翠簾新灑別，不挑紅燼正含愁。","蕭騷寒竹南窗靜，一局閑棋爲爾留。"]', '["雨向莎堦滴未休，冷光孤恨雨悠悠。","船中闻雁洞庭宿，牀下有蛩长信秋。","背照翠簾新灑別，不挑紅燼正含愁。","蕭騷寒竹南窗静，一局闲棋爲爾留。"]', '诗', 'shi', '', NULL, '燈 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c675418e-2cf8-4fbd-8420-0964cff66cd5', '宗人作尉唐昌官署幽勝而又博學精富得以言談將欲他之留書屋壁', '宗人作尉唐昌官署幽勝而又博学精富得以言談將欲他之留书屋壁', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["公堂瀟灑有林泉，秪隔苔牆是渚田。","宗黨相親離亂世，春秋閑論戰爭年。","遠江驚鷺來池口，絕頂歸雲過竹邊。","風雨夜長同一宿，舊遊多共憶樊川。"]', '["公堂瀟灑有林泉，秪隔苔牆是渚田。","宗黨相親離亂世，春秋闲論戰爭年。","远江驚鷺来池口，絕頂归云過竹邊。","风雨夜长同一宿，旧游多共憶樊川。"]', '诗', 'shi', '', NULL, '宗人作尉唐昌官署幽勝而又博學精富得以言談將欲他之留書屋壁 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6db2ef27-f424-470f-b568-8620f21d0669', '爲戶部李郎中與令季端公寓止渠州江寺偶作寄獻', '爲戶部李郎中與令季端公寓止渠州江寺偶作寄獻', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["退居瀟灑寄禪關，高挂朝簪淨室間。","孤島雖留雙鶴歇，五雲爭放二龍閑。","輕舟共泛花邊水，野屐同登竹外山。","仙署金閨虛位久，夜清應夢近天顏。"]', '["退居瀟灑寄禪关，高挂朝簪淨室间。","孤島雖留雙鹤歇，五云爭放二龙闲。","轻舟共泛花邊水，野屐同登竹外山。","仙署金閨虛位久，夜清應梦近天顏。"]', '诗', 'shi', '', NULL, '爲戶部李郎中與令季端公寓止渠州江寺偶作寄獻 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b03490-6f89-42ca-bb6c-ca8262dbc07f', '重陽日訪元秀上人', '重陽日訪元秀上人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["紅葉黃花秋景寬，醉吟朝夕在樊川。","却嫌今日登山俗，且共高僧對榻眠。","別畫長懷吳寺壁，宜茶偏賞霅溪泉。","歸來童稚爭相笑，何事無人與酒船。"]', '["紅葉黄花秋景寬，醉吟朝夕在樊川。","却嫌今日登山俗，且共高僧对榻眠。","別畫长懷吳寺壁，宜茶偏賞霅溪泉。","归来童稚爭相笑，何事無人與酒船。"]', '诗', 'shi', '', NULL, '重陽日訪元秀上人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de88885-523f-4834-b590-1c17593b8127', '闕下春日', '闕下春日', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["建章宮殿紫雲飄，春漏遲遲下絳霄。","綺陌暖風嘶去馬，粉廊初日照趨朝。","花經宿雨香難拾，鶯在豪家語更嬌。","秦楚年年有離別，揚鞭揮袖灞陵橋。"]', '["建章宮殿紫云飄，春漏遲遲下絳霄。","綺陌暖风嘶去马，粉廊初日照趨朝。","花經宿雨香难拾，鶯在豪家語更嬌。","秦楚年年有離別，揚鞭揮袖灞陵橋。"]', '诗', 'shi', '', NULL, '闕下春日 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab94e50-b52c-456f-9ee9-7fce234c4813', '贈劉神童', '贈劉神童', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["習讀在前生，僧談足可明。","還家雖解喜，登第未知榮。","時果曾霑賜，春闈不挂情。","燈前猶惡睡，寤語讀書聲。"]', '["習读在前生，僧談足可明。","還家雖解喜，登第未知榮。","时果曾霑賜，春闈不挂情。","灯前猶惡睡，寤語读书声。"]', '诗', 'shi', '', NULL, '贈劉神童 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d7e71b-77fc-40a0-b9e5-426da2d9649e', '遠遊', '远游', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江湖猶足事，食宿戍鼙喧。","久客秋風起，孤舟夜浪翻。","鄉音離楚水，廟貌入湘源。","岸闊鳧鷖小，林垂橘柚繁。","津官來有意，漁者笑無言。","早晚酬僧約，中條有藥園。"]', '["江湖猶足事，食宿戍鼙喧。","久客秋风起，孤舟夜浪翻。","乡音離楚水，廟貌入湘源。","岸闊鳧鷖小，林垂橘柚繁。","津官来有意，漁者笑無言。","早晚酬僧約，中條有藥园。"]', '诗', 'shi', '', NULL, '遠遊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af1dd067-780d-4a7c-bfce-fbd8f96362fe', '光化戊午年舉公見示省試春草碧色詩偶賦是題', '光化戊午年舉公见示省試春草碧色诗偶賦是題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["萇弘血染新，含露滿江濱。","想得尋花徑，應迷拾翠人。","窗紗迎擁砌，簪玉妬成茵。","天借新晴色，雲饒落日春。","嵐光垂處合，眉黛看時嚬。","願與仙桃比，無令惹路塵。"]', '["萇弘血染新，含露满江濱。","想得尋花徑，應迷拾翠人。","窗紗迎擁砌，簪玉妬成茵。","天借新晴色，云饒落日春。","嵐光垂处合，眉黛看时嚬。","願與仙桃比，無令惹路塵。"]', '诗', 'shi', '', NULL, '光化戊午年舉公見示省試春草碧色詩偶賦是題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aa521e8-e014-483d-bd5c-167b3ce9c9d4', '江際', '江際', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["杳杳漁舟破暝煙，疎疎蘆葦舊江天。","那堪流落逢搖落，可得潸然是偶然。","萬頃白波迷宿鷺，一林黃葉送殘蟬。","兵車未息年華促，早晚閑吟向滻川。"]', '["杳杳漁舟破暝煙，疎疎蘆葦旧江天。","那堪流落逢搖落，可得潸然是偶然。","万頃白波迷宿鷺，一林黄葉送殘蟬。","兵车未息年华促，早晚闲吟向滻川。"]', '诗', 'shi', '', NULL, '江際 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e3867bd-fb40-4b66-8840-0ba69bf27c17', '將之瀘郡旅次遂州遇裴晤員外謫居於此話舊淒涼因寄二首 一', '將之瀘郡旅次遂州遇裴晤員外謫居於此話旧淒涼因寄二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["誰解登高問上玄，謫仙何事謫詩仙。","雲遮列宿離華省，樹蔭澄江入野船。","黃鳥晚啼愁瘴雨，青梅早落中蠻煙。","不知幾首南行曲，留與巴兒萬古傳。"]', '["誰解登高问上玄，謫仙何事謫诗仙。","云遮列宿離华省，樹蔭澄江入野船。","黄鸟晚啼愁瘴雨，青梅早落中蠻煙。","不知幾首南行曲，留與巴兒万古傳。"]', '诗', 'shi', '', NULL, '將之瀘郡旅次遂州遇裴晤員外謫居於此話舊淒涼因寄二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edeba321-b6dc-4573-b3d9-6e5d1ac95d0c', '將之瀘郡旅次遂州遇裴晤員外謫居於此話舊淒涼因寄二首 二', '將之瀘郡旅次遂州遇裴晤員外謫居於此話旧淒涼因寄二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["昔年共照松溪影，松折溪荒僧已無。","今日重思錦城事，雪銷花謝夢何殊。","亂離未定身俱老，騷雅全休道甚孤。","我拜師門更南去，荔枝春熟向渝瀘。"]', '["昔年共照松溪影，松折溪荒僧已無。","今日重思錦城事，雪銷花謝梦何殊。","亂離未定身俱老，騷雅全休道甚孤。","我拜師门更南去，荔枝春熟向渝瀘。"]', '诗', 'shi', '', NULL, '將之瀘郡旅次遂州遇裴晤員外謫居於此話舊淒涼因寄二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e94f9669-79f3-4c18-bb79-1fa528b8828a', '次韻和秀上人長安寺居言懷寄渚宮禪者', '次韻和秀上人长安寺居言懷寄渚宮禪者', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["舊齋松老別多年，香社人稀喪亂間。","出寺秪知趨內殿，閉門長似在深山。","臥聽秦樹秋鐘斷，吟想荆江夕鳥還。","唯恐興來飛錫去，老郎無路更追攀。"]', '["旧斋松老別多年，香社人稀喪亂间。","出寺秪知趨內殿，閉门长似在深山。","臥听秦樹秋鐘斷，吟想荆江夕鸟還。","唯恐兴来飞錫去，老郎無路更追攀。"]', '诗', 'shi', '', NULL, '次韻和秀上人長安寺居言懷寄渚宮禪者 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efed73c3-0be3-4bcf-8f9e-8ad44b32a9c1', '蜀中春日', '蜀中春日', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["海棠風外獨霑巾，襟袖無端惹蜀塵。","和暖又逢挑菜日，寂寥未是探花人。","不嫌蟻酒衝愁肺，却憶漁蓑覆病身。","何事晚來微雨後，錦江春學曲江春。"]', '["海棠风外独霑巾，襟袖無端惹蜀塵。","和暖又逢挑菜日，寂寥未是探花人。","不嫌蟻酒衝愁肺，却憶漁蓑覆病身。","何事晚来微雨後，錦江春学曲江春。"]', '诗', 'shi', '', NULL, '蜀中春日 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d41964b-3112-43d1-b55e-f7f353be959a', '遊蜀', '游蜀', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["所向明知是暗投，兩行清淚語前流。","雲橫新塞遮秦甸，花落空山入閬州。","不忿黃鸝驚曉夢，唯應杜宇信春愁。","梅黃麥綠無歸處，可得漂漂愛浪遊。"]', '["所向明知是暗投，兩行清泪語前流。","云橫新塞遮秦甸，花落空山入閬州。","不忿黄鸝驚晓梦，唯應杜宇信春愁。","梅黄麦綠無归处，可得漂漂愛浪游。"]', '诗', 'shi', '', NULL, '遊蜀 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92d4263e-d23c-4a98-83d5-895297c6df61', '峽中嘗茶', '峽中嘗茶', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["蔟蔟新英摘露光，小江園裏火煎嘗。","吳僧漫說鴉山好，蜀叟休誇鳥觜香。","合座半甌輕泛綠，開緘數片淺含黃。","鹿門病客不歸去，酒渴更知春味長。"]', '["蔟蔟新英摘露光，小江园裏火煎嘗。","吳僧漫说鴉山好，蜀叟休誇鸟觜香。","合座半甌轻泛綠，开緘數片淺含黄。","鹿门病客不归去，酒渴更知春味长。"]', '诗', 'shi', '', NULL, '峽中嘗茶 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('264760ef-3058-4f27-968d-abdada173df4', '輦下冬暮詠懷', '輦下冬暮詠懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["永巷閑吟一徑蒿，輕肥大笑事風騷。","煙含紫禁花期近，雪滿長安酒價高。","失路漸驚前計錯，逢僧更念此生勞。","十年春淚催衰颯，羞向清流照鬢毛。"]', '["永巷闲吟一徑蒿，轻肥大笑事风騷。","煙含紫禁花期近，雪满长安酒價高。","失路漸驚前計錯，逢僧更念此生勞。","十年春泪催衰颯，羞向清流照鬢毛。"]', '诗', 'shi', '', NULL, '輦下冬暮詠懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc7aa481-e827-4831-8f4d-f4cd6b11fe83', '石城', '石城', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["石城昔爲莫愁鄉，莫愁魂散石城荒。","江人依舊棹舴艋，江岸還飛雙鴛鴦。","帆去帆來風浩渺，花開花落春悲涼。","煙濃草遠望不盡，千古漢陽閑夕陽。"]', '["石城昔爲莫愁乡，莫愁魂散石城荒。","江人依旧棹舴艋，江岸還飞雙鴛鴦。","帆去帆来风浩渺，花开花落春悲涼。","煙濃草远望不尽，千古漢陽闲夕陽。"]', '诗', 'shi', '', NULL, '石城 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ddbbbc-1826-446c-8477-c1031ff5e631', '蜀中三首 一', '蜀中三首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["馬頭春向鹿頭關。","遠樹平蕪一望閑，雪下文君沾酒市。","雲藏李白讀書山，江樓客恨黃梅後。","村落人歌紫芋間，堤月橋燈好時景。","漢庭無事不征蠻。"]', '["马头春向鹿头关。","远樹平蕪一望闲，雪下文君沾酒市。","云藏李白读书山，江楼客恨黄梅後。","村落人歌紫芋间，堤月橋灯好时景。","漢庭無事不征蠻。"]', '诗', 'shi', '', NULL, '蜀中三首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af33b432-6122-443b-8700-8d9ca48214f0', '蜀中三首 二', '蜀中三首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["夜無多雨曉生塵，草色嵐光日日新。","蒙頂茶畦千點露，浣花牋紙一溪春。","揚雄宅在唯喬木，杜甫臺荒絕舊鄰。","却共海棠花有約，數年留滯不歸人。"]', '["夜無多雨晓生塵，草色嵐光日日新。","蒙頂茶畦千点露，浣花牋紙一溪春。","揚雄宅在唯喬木，杜甫台荒絕旧鄰。","却共海棠花有約，數年留滯不归人。"]', '诗', 'shi', '', NULL, '蜀中三首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb3c1c90-88d1-439b-9d8c-4ead0605da9c', '蜀中三首 三', '蜀中三首 三', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["渚遠江清碧簟紋，小桃花繞薛濤墳。","朱橋直指金門路，粉堞高連玉壘雲。","窗下[斵]琴翹鳳足，波中濯錦散鷗羣。","子規夜夜啼巴樹，不並吳鄉楚國聞。"]', '["渚远江清碧簟紋，小桃花繞薛濤墳。","朱橋直指金门路，粉堞高連玉壘云。","窗下[斵]琴翹鳳足，波中濯錦散鷗羣。","子規夜夜啼巴樹，不並吳乡楚国闻。"]', '诗', 'shi', '', NULL, '蜀中三首 三 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ea3b1f-21e8-495c-8d80-bd9cc7d93e27', '少華甘露寺', '少华甘露寺', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["石門蘿徑與天鄰，雨檜風篁遠近聞。","飲澗鹿喧雙派水，上樓僧蹋一梯雲。","孤煙薄暮關城沒，遠色初晴渭曲分。","長欲然香來此宿，北林猨鶴舊同羣。"]', '["石门蘿徑與天鄰，雨檜风篁远近闻。","饮澗鹿喧雙派水，上楼僧蹋一梯云。","孤煙薄暮关城沒，远色初晴渭曲分。","长欲然香来此宿，北林猨鹤旧同羣。"]', '诗', 'shi', '', NULL, '少華甘露寺 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ff5290-2c49-4c04-a577-787ceae67aa5', '慈恩寺偶題', '慈恩寺偶題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["往事悠悠添浩歎，勞生擾擾竟何能。","故山歲晚不歸去，高塔晴來獨自登。","林下聽經秋苑鹿，江邊掃葉夕陽僧。","吟餘却起雙峰念，曾看菴西瀑布冰。"]', '["往事悠悠添浩歎，勞生擾擾竟何能。","故山歲晚不归去，高塔晴来独自登。","林下听經秋苑鹿，江邊掃葉夕陽僧。","吟餘却起雙峰念，曾看菴西瀑布冰。"]', '诗', 'shi', '', NULL, '慈恩寺偶題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d863837d-3b16-497f-82ec-b7361e7151f7', '石門山泉', '石门山泉', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["一脈清泠何所之，縈莎漱蘚入僧池。","雲邊野客窮來處，石上寒猨見落時。","聚沫繞崖殘雪在，迸流穿樹墮花隨。","煙春雨晚閑吟去，不復遠尋皇子陂。"]', '["一脈清泠何所之，縈莎漱蘚入僧池。","云邊野客窮来处，石上寒猨见落时。","聚沫繞崖殘雪在，迸流穿樹墮花隨。","煙春雨晚闲吟去，不复远尋皇子陂。"]', '诗', 'shi', '', NULL, '石門山泉 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e9496b-e2da-4a0f-a36f-5c0009c2ad62', '渭陽樓閑望', '渭陽楼闲望', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["千重二華見皇州，望盡凝嵐即此樓。","細雨不藏秦樹色，夕陽空照渭河流。","後車寧見前車覆，今日難忘昨日憂。","擾擾塵中猶未已，可能疏傅獨能休。"]', '["千重二华见皇州，望尽凝嵐即此楼。","細雨不藏秦樹色，夕陽空照渭河流。","後车寧见前车覆，今日难忘昨日憂。","擾擾塵中猶未已，可能疏傅独能休。"]', '诗', 'shi', '', NULL, '渭陽樓閑望 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b36e8bbe-26ac-47c1-8c0b-6632fd504a76', '送田光', '送田光', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["九陌低迷誰問我，五湖流浪可悲君。","著書笑破蘇司業，賦詠思齊鄭廣文。","理棹好攜三百首，阻風須飲幾千分。","耒陽江口春山綠，慟哭應尋杜甫墳。"]', '["九陌低迷誰问我，五湖流浪可悲君。","著书笑破蘇司業，賦詠思齊鄭廣文。","理棹好携三百首，阻风須饮幾千分。","耒陽江口春山綠，慟哭應尋杜甫墳。"]', '诗', 'shi', '', NULL, '送田光 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d10d11d-47d1-49f4-ad23-2233cbaddefc', '送進士吳延保及第後南遊', '送進士吳延保及第後南游', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["得意却思尋舊跡，新銜未切向蘭臺。","吟看秋草出關去，逢見故人隨計來。","勝地昔年詩板在，清歌幾處郡筵開。","江湖易有淹留興，莫待春風落庾梅。"]', '["得意却思尋旧跡，新銜未切向蘭台。","吟看秋草出关去，逢见故人隨計来。","勝地昔年诗板在，清歌幾处郡筵开。","江湖易有淹留兴，莫待春风落庾梅。"]', '诗', 'shi', '', NULL, '送進士吳延保及第後南遊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0803f90-4c6f-4346-a48a-392ed2af79c6', '送進士王駕下第歸蒲中', '送進士王駕下第归蒲中', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["失意離愁春不知，到家時是落花時。","孤單取事休言命，早晚逢人苦愛詩。","度塞風沙歸路遠，傍河桑柘舊居移。","應嗟我又巴江去，遊子悠悠聽子規。"]', '["失意離愁春不知，到家时是落花时。","孤單取事休言命，早晚逢人苦愛诗。","度塞风沙归路远，傍河桑柘旧居移。","應嗟我又巴江去，游子悠悠听子規。"]', '诗', 'shi', '', NULL, '送進士王駕下第歸蒲中 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09e8f01e-e241-4137-9036-903552c1e4fb', '作尉鄠郊送進士潘爲下第南歸', '作尉鄠郊送進士潘爲下第南归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["歸去宜春春水深，麥秋梅雨過湘陰。","鄉園幾度經狂寇，桑柘誰家有舊林。","結綬位卑甘晚達，登龍心在且高吟。","灞陵橋上楊花裏，酒滿芳樽淚滿襟。"]', '["归去宜春春水深，麦秋梅雨過湘陰。","乡园幾度經狂寇，桑柘誰家有旧林。","結綬位卑甘晚達，登龙心在且高吟。","灞陵橋上楊花裏，酒满芳樽泪满襟。"]', '诗', 'shi', '', NULL, '作尉鄠郊送進士潘爲下第南歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('131ec489-2ed0-4bab-a069-f515e3e5d997', '送進士韋序赴舉', '送進士韋序赴舉', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["丹霞照上三清路，瑞錦裁成五色毫。","波浪不能隨世態，鸞凰應得入吾曹。","秋山晚水吟情遠，雪竹風松醉格高。","預想明年騰躍處，龍津春碧浸仙桃。"]', '["丹霞照上三清路，瑞錦裁成五色毫。","波浪不能隨世態，鸾凰應得入吾曹。","秋山晚水吟情远，雪竹风松醉格高。","預想明年腾躍处，龙津春碧浸仙桃。"]', '诗', 'shi', '', NULL, '送進士韋序赴舉 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5bb1c33-e068-4bce-b8fd-c24fcd9a3f35', '寄獻狄右丞', '寄獻狄右丞', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["逐勝偷閑向杜陵，愛僧不愛紫衣僧。","身爲醉客思吟客，官自中丞拜右丞。","殘月露垂朝闕蓋，落花風動宿齋燈。","孤單小諫漁舟在，心戀清潭去未能。"]', '["逐勝偷闲向杜陵，愛僧不愛紫衣僧。","身爲醉客思吟客，官自中丞拜右丞。","殘月露垂朝闕蓋，落花风动宿斋灯。","孤單小諫漁舟在，心戀清潭去未能。"]', '诗', 'shi', '', NULL, '寄獻狄右丞 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628006de-0888-47d0-b153-354c9c49d58d', '轉正郎後寄獻集賢相公', '轉正郎後寄獻集賢相公', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["予名初在德門前，屈指年來三十年。","自賀孤危終際會，別將流涕感階緣。","止陪鴛鴦居清秩，濫應星辰浼上玄。","平昔苦心何所恨，受恩多是舊詩篇。"]', '["予名初在德门前，屈指年来三十年。","自賀孤危終際會，別將流涕感階緣。","止陪鴛鴦居清秩，濫應星辰浼上玄。","平昔苦心何所恨，受恩多是旧诗篇。"]', '诗', 'shi', '', NULL, '轉正郎後寄獻集賢相公 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b45ab2-c4aa-43d4-bc9a-a022baef95bc', '所知從事近藩偶有懷寄', '所知從事近藩偶有懷寄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["官舍種莎僧對榻，生涯如在舊山貧。","酒醒草檄聞殘漏，花落移廚送晚春。","水墨畫松清睡眼，雲霞仙氅挂吟身。","霜臺伏首思歸切，莫把漁竿逐逸人。"]', '["官舍種莎僧对榻，生涯如在旧山貧。","酒醒草檄闻殘漏，花落移廚送晚春。","水墨畫松清睡眼，云霞仙氅挂吟身。","霜台伏首思归切，莫把漁竿逐逸人。"]', '诗', 'shi', '', NULL, '所知從事近藩偶有懷寄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf58beb9-f98e-4cd0-a2fa-40817cac3d58', '獻大京兆薛常侍能', '獻大京兆薛常侍能', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["耻將官業競前途，自愛篇章古不如。","一炷香新開道院，數坊人聚避朝車。","縱遊藉草花垂酒，閑臥臨窗燕拂書。","唯有明公賞新句，秋風不敢憶鱸魚。"]', '["耻將官業競前途，自愛篇章古不如。","一炷香新开道院，數坊人聚避朝车。","縱游藉草花垂酒，闲臥臨窗燕拂书。","唯有明公賞新句，秋风不敢憶鱸鱼。"]', '诗', 'shi', '', NULL, '獻大京兆薛常侍能 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d6bdc5-5089-4ce8-8d17-c977eb5cf093', '寄贈孫路處士', '寄贈孫路处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["平生詩譽更誰過，歸老東吳命若何。","知己凋零垂白髮，故園寥落近滄波。","酒醒蘚砌花陰轉，病起漁舟鷺跡多。","深入富春人不見，閑門空掩半庭莎。"]', '["平生诗譽更誰過，归老东吳命若何。","知己凋零垂白髮，故园寥落近滄波。","酒醒蘚砌花陰轉，病起漁舟鷺跡多。","深入富春人不见，闲门空掩半庭莎。"]', '诗', 'shi', '', NULL, '寄贈孫路處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc324730-dd47-499f-882d-9b62ea1b3f86', '獻制誥楊舍人', '獻制誥楊舍人', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["爲郡東吳秪飲冰，瑣闈頻降鳳書徵。","隨行已有朱衣吏，伴直多招紫閣僧。","窗下調琴鳴遠水，簾前睡鶴背秋燈。","葦陂竹塢情無限，閑話毘陵問杜陵。"]', '["爲郡东吳秪饮冰，瑣闈頻降鳳书徵。","隨行已有朱衣吏，伴直多招紫閣僧。","窗下調琴鳴远水，簾前睡鹤背秋灯。","葦陂竹塢情無限，闲話毘陵问杜陵。"]', '诗', 'shi', '', NULL, '獻制誥楊舍人 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eed5d45-fb2e-4d65-95d8-0139ddd1c565', '次韻酬張補闕因寒食見寄之什', '次韻酬張補闕因寒食见寄之什', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["柳近清明翠縷長，多情右衮不相忘。","開緘雖覩新篇麗，破鼻須聞冷酒香。","時態嬾隨人上下，花心甘被蝶分張。","朝稀且莫輕春賞，勝事由來在帝鄉。"]', '["柳近清明翠縷长，多情右衮不相忘。","开緘雖覩新篇丽，破鼻須闻冷酒香。","时態嬾隨人上下，花心甘被蝶分張。","朝稀且莫轻春賞，勝事由来在帝乡。"]', '诗', 'shi', '', NULL, '次韻酬張補闕因寒食見寄之什 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48039e2-5566-4502-935a-b8e38c25ea0c', '贈宗人前公安宰君', '贈宗人前公安宰君', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["喧卑從宦出喧卑，別畫能琴又解棊。","海上春耕因亂廢，年來冬薦得官遲。","風中夜犬驚槐巷，月下寒驢嚙槿籬。","孤散恨無推唱路，耿懷吟得贈君詩。"]', '["喧卑從宦出喧卑，別畫能琴又解棊。","海上春耕因亂廢，年来冬薦得官遲。","风中夜犬驚槐巷，月下寒驢嚙槿籬。","孤散恨無推唱路，耿懷吟得贈君诗。"]', '诗', 'shi', '', NULL, '贈宗人前公安宰君 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b6bb491-5023-49f6-99fa-8e8a78fd1076', '寄贈楊夔處士', '寄贈楊夔处士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["結茅秪約釣魚臺，濺水鸕鷀去又迴。","春臥甕邊聽酒熟，露吟庭際待花開。","三江勝景遨遊徧，百氏羣書講貫來。","國步未安風雅薄，可能高尚掞天才。"]', '["結茅秪約釣鱼台，濺水鸕鷀去又迴。","春臥甕邊听酒熟，露吟庭際待花开。","三江勝景遨游徧，百氏羣书講貫来。","国步未安风雅薄，可能高尚掞天才。"]', '诗', 'shi', '', NULL, '寄贈楊夔處士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('681c4483-8436-49d1-a24d-ec1a75926d13', '寄同年禮部趙郎中', '寄同年禮部趙郎中', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["仙步徐徐整羽衣，小儀澄澹轉中儀。","樺飄紅燼趨朝路，蘭縱清香宿省時。","彩筆煙霞供不足，綸闈鸞鳳訝來遲。","自憐孤宦誰相念，禱祝空吟一首詩。"]', '["仙步徐徐整羽衣，小儀澄澹轉中儀。","樺飄紅燼趨朝路，蘭縱清香宿省时。","彩笔煙霞供不足，綸闈鸾鳳訝来遲。","自怜孤宦誰相念，禱祝空吟一首诗。"]', '诗', 'shi', '', NULL, '寄同年禮部趙郎中 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7294fe27-0cd0-4ce0-b949-409801d2a6de', '春暮詠懷寄集賢韋起居衮', '春暮詠懷寄集賢韋起居衮', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寂寂風簾信自垂，楊花筍籜正離披。","長安一夜殘春雨，右省三年老拾遺。","坐看羣賢爭得路，退量孤分且吟詩。","五湖煙網非無意，未去難忘國士知。"]', '["寂寂风簾信自垂，楊花筍籜正離披。","长安一夜殘春雨，右省三年老拾遺。","坐看羣賢爭得路，退量孤分且吟诗。","五湖煙網非無意，未去难忘国士知。"]', '诗', 'shi', '', NULL, '春暮詠懷寄集賢韋起居衮 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27ea5340-00b6-4ecf-b16b-6854d65f4c3c', '多情', '多情', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["賦分多情却自嗟，蕭衰未必爲年華。","睡輕可忍風敲竹，飲散那堪月在花。","薄宦因循拋峴首，故人流落向天涯。","鶯春鴈夜長如此，賴是幽居近酒家。"]', '["賦分多情却自嗟，蕭衰未必爲年华。","睡轻可忍风敲竹，饮散那堪月在花。","薄宦因循拋峴首，故人流落向天涯。","鶯春鴈夜长如此，賴是幽居近酒家。"]', '诗', 'shi', '', NULL, '多情 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e5665d5-a59e-4c56-a548-3899149341c2', '感懷投時相', '感懷投时相', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["非才偶忝直文昌，兩鬢年深一鏡霜。","待漏敢辭稱小吏，立班猶未出中行。","孤吟馬跡拋槐陌，遠夢漁竿擲葦鄉。"]', '["非才偶忝直文昌，兩鬢年深一镜霜。","待漏敢辞稱小吏，立班猶未出中行。","孤吟马跡拋槐陌，远梦漁竿擲葦乡。"]', '诗', 'shi', '', NULL, '感懷投時相 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffad1c02-1268-4dd2-828a-113e1556d056', '自貽', '自貽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["飲筵博席與心違，野眺春吟更是誰。","琴有澗風聲轉澹，詩無僧字格還卑。","恨拋水國荷蓑雨，貧過長安櫻筍時。","頭角俊髦應指笑，權門蹤跡獨差池。"]', '["饮筵博席與心違，野眺春吟更是誰。","琴有澗风声轉澹，诗無僧字格還卑。","恨拋水国荷蓑雨，貧過长安櫻筍时。","头角俊髦應指笑，權门蹤跡独差池。"]', '诗', 'shi', '', NULL, '自貽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ade1117-285b-46e4-b1e5-54c50af3e4c3', '自遣', '自遣', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["強健宦途何足謂，入微章句更難論。","誰知野性真天性，不扣權門扣道門。","窺硯晚鶯臨砌樹，迸堦春筍隔籬根。","朝迴何處消長日，紫閣峰南有舊村。"]', '["強健宦途何足謂，入微章句更难論。","誰知野性真天性，不扣權门扣道门。","窺硯晚鶯臨砌樹，迸堦春筍隔籬根。","朝迴何处消长日，紫閣峰南有旧村。"]', '诗', 'shi', '', NULL, '自遣 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca8d6f3d-e27c-40f1-a02d-9f659c2a9fdb', '中年', '中年', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["漠漠秦雲澹澹天，新年景象入中年。","情多最恨花無語，愁破方知酒有權。","苔色滿牆尋故第，雨聲一夜憶春田。","衰遲自喜添詩學，更把前題改數聯。"]', '["漠漠秦云澹澹天，新年景象入中年。","情多最恨花無語，愁破方知酒有權。","苔色满牆尋故第，雨声一夜憶春田。","衰遲自喜添诗学，更把前題改數聯。"]', '诗', 'shi', '', NULL, '中年 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4c5c926-d193-4e9b-8147-87648f65c39b', '自適', '自適', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["紫陌奔馳不暫停，送迎終日在郊坰。","年來鬢畔未垂白，雨後江頭且蹋青。","浮蟻滿盃難暫捨，貫珠一曲莫辭聽。","春風秪有九十日，可合花前半日醒。"]', '["紫陌奔驰不暫停，送迎終日在郊坰。","年来鬢畔未垂白，雨後江头且蹋青。","浮蟻满盃难暫捨，貫珠一曲莫辞听。","春风秪有九十日，可合花前半日醒。"]', '诗', 'shi', '', NULL, '自適 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b7022b8-88b5-4803-9230-8b77755f383c', '結綬鄠郊縻攝府署偶有自詠', '結綬鄠郊縻攝府署偶有自詠', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["鶯離寒谷士逢春，釋褐來年暫種芸。","自笑老爲梅少府，可堪貧攝鮑參軍。","酒醒往事多興念，吟苦鄰居必厭聞。","推却簿書搔短髮，落花飛絮正紛紛。"]', '["鶯離寒谷士逢春，釋褐来年暫種芸。","自笑老爲梅少府，可堪貧攝鲍參軍。","酒醒往事多兴念，吟苦鄰居必厭闻。","推却簿书搔短髮，落花飞絮正紛紛。"]', '诗', 'shi', '', NULL, '結綬鄠郊縻攝府署偶有自詠 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d929b40-3fd2-4b48-adf8-51cbbade0ee2', '漂泊', '漂泊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["槿墜蓬疎池館清，日光風緒澹無情。","鱸魚斫鱠輸張翰，橘樹呼奴羨李衡。","十口漂零猶寄食，兩川消息未休兵。"]', '["槿墜蓬疎池館清，日光风緒澹無情。","鱸鱼斫鱠輸張翰，橘樹呼奴羨李衡。","十口漂零猶寄食，兩川消息未休兵。"]', '诗', 'shi', '', NULL, '漂泊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde78274-74f8-4b40-954c-c51ccb0064d7', '弔故禮部韋員外序', '弔故禮部韋員外序', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["臘雪初晴共舉盃，便期攜手上春臺。","高情唯怕酒不滿，長逝可悲花正開。","曉奠鶯啼殘漏在，風幃燕覓舊巢來。","杜陵芳草年年綠，醉魄吟魂無復迴。"]', '["臘雪初晴共舉盃，便期携手上春台。","高情唯怕酒不满，长逝可悲花正开。","晓奠鶯啼殘漏在，风幃燕覓旧巢来。","杜陵芳草年年綠，醉魄吟魂無复迴。"]', '诗', 'shi', '', NULL, '弔故禮部韋員外序 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b08ffe-23ce-4afb-bb96-34cb59e81b29', '渼陂', '渼陂', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["昔事東流共不迴，春深獨向渼陂來。","亂前別業依稀在，雨裏繁花寂寞開。","却展漁絲無野艇，舊題詩句沒蒼苔。","潸然四顧難消遣，秪有佯狂泥酒盃。"]', '["昔事东流共不迴，春深独向渼陂来。","亂前別業依稀在，雨裏繁花寂寞开。","却展漁絲無野艇，旧題诗句沒蒼苔。","潸然四顧难消遣，秪有佯狂泥酒盃。"]', '诗', 'shi', '', NULL, '渼陂 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('673619df-a40a-4122-8c4a-013695fe64ac', '代秋扇詞', '代秋扇词', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["露入庭蕪恨已深，熱時天下是知音。","汗流浹背曾施力，氣爽中宵便負心。","一片山溪從蠹損，數行文字任塵侵。","綠槐陰合清和後，不會何顏又見尋。"]', '["露入庭蕪恨已深，熱时天下是知音。","汗流浹背曾施力，氣爽中宵便負心。","一片山溪從蠹損，數行文字任塵侵。","綠槐陰合清和後，不會何顏又见尋。"]', '诗', 'shi', '', NULL, '代秋扇詞 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('717ee290-1817-4910-a66a-edd46a2a4e21', '宣義里舍冬暮自貽', '宣義里舍冬暮自貽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["幽居不稱在長安，溝淺浮春岸雪殘。","板屋漸移方帶野，水車新入夜添寒。","名如有分終須立，道若離心豈易寬。","滿眼塵埃馳騖去，獨尋煙竹翦漁竿。"]', '["幽居不稱在长安，溝淺浮春岸雪殘。","板屋漸移方带野，水车新入夜添寒。","名如有分終須立，道若離心豈易寬。","满眼塵埃驰騖去，独尋煙竹翦漁竿。"]', '诗', 'shi', '', NULL, '宣義里舍冬暮自貽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a51eaddf-5c71-41de-bc7c-52946c90db29', '省中偶作', '省中偶作', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["三轉郎曹自勉旃，莎階吟步想前賢。","未如何遜無佳句，若比馮唐是壯年。","捧制名題黃紙尾，約僧心在白雪邊。","乳毛松雪春來好，直夜清閑且學禪。"]', '["三轉郎曹自勉旃，莎階吟步想前賢。","未如何遜無佳句，若比馮唐是壯年。","捧制名題黄紙尾，約僧心在白雪邊。","乳毛松雪春来好，直夜清闲且学禪。"]', '诗', 'shi', '', NULL, '省中偶作 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094ed953-b328-40c7-83e3-b61c6dd7ce33', '同志顧雲下第出京偶有寄勉', '同志顧云下第出京偶有寄勉', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["鳳策聯華是國華，春來偶未上仙槎。","鄉連南渡思菰米，淚滴東風避杏花。","吟聒暮鶯歸廟院，睡消遲日寄僧家。","一般情緒應相信，門靜莎深樹影斜。"]', '["鳳策聯华是国华，春来偶未上仙槎。","乡連南渡思菰米，泪滴东风避杏花。","吟聒暮鶯归廟院，睡消遲日寄僧家。","一般情緒應相信，门静莎深樹影斜。"]', '诗', 'shi', '', NULL, '同志顧雲下第出京偶有寄勉 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bacfaeb-9c19-4bcd-bbe1-25d24aa6bcd2', '敷溪高士', '敷溪高士', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["敷溪南岸掩柴荆，挂却朝衣愛淨名。","閑得林園栽樹法，喜聞兒姪讀書聲。","眠窗日暖添幽夢，步野風清散酒酲。","謫去徵還何擾擾，片雲相伴看衰榮。"]', '["敷溪南岸掩柴荆，挂却朝衣愛淨名。","闲得林园栽樹法，喜闻兒姪读书声。","眠窗日暖添幽梦，步野风清散酒酲。","謫去徵還何擾擾，片云相伴看衰榮。"]', '诗', 'shi', '', NULL, '敷溪高士 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d69d600-8915-4873-a905-4cabecc9288a', '九日偶懷寄左省張起居', '九日偶懷寄左省張起居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["令節爭歡我獨閑，荒臺盡日向晴山。","渾無酒泛金英菊，漫道官趨玉筍班。","深愧青莎迎野步，不堪紅葉照衰顏。","羨君官重多吟興，醉帶南陂落照還。"]', '["令節爭歡我独闲，荒台尽日向晴山。","渾無酒泛金英菊，漫道官趨玉筍班。","深愧青莎迎野步，不堪紅葉照衰顏。","羨君官重多吟兴，醉带南陂落照還。"]', '诗', 'shi', '', NULL, '九日偶懷寄左省張起居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3255a714-388e-4f98-bb9b-b4c66b846e83', '春夕伴同年禮部趙員外省直', '春夕伴同年禮部趙員外省直', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["錦帳名郎重錦科，清宵寓直縱吟哦。","冰含玉鏡春寒在，粉傅仙闈月色多。","視草即應歸屬望，握蘭知道暫經過。","流鶯百囀和殘漏，猶把芳樽藉露莎。"]', '["錦帳名郎重錦科，清宵寓直縱吟哦。","冰含玉镜春寒在，粉傅仙闈月色多。","視草即應归屬望，握蘭知道暫經過。","流鶯百囀和殘漏，猶把芳樽藉露莎。"]', '诗', 'shi', '', NULL, '春夕伴同年禮部趙員外省直 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7644b65d-804f-40e5-a536-1f8dfff0dec4', '倦客', '倦客', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["十年五年岐路中，千里萬里西復東。","匹馬愁衝晚村雪，孤舟悶阻春江風。","達士由來知道在，昔賢何必哭途窮。","閑烹蘆筍炊菰米，會向源鄉作醉翁。"]', '["十年五年岐路中，千里万里西复东。","匹马愁衝晚村雪，孤舟悶阻春江风。","達士由来知道在，昔賢何必哭途窮。","闲烹蘆筍炊菰米，會向源乡作醉翁。"]', '诗', 'shi', '', NULL, '倦客 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b208766-121b-4d0c-bb48-0daac768898d', '溫處士能畫鷺鶿以四韻換之', '溫处士能畫鷺鶿以四韻換之', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["昔年吟醉繞江蘺，愛把漁竿伴鷺鶿。","聞說小毫能縱逸，敢憑輕素寫幽奇。","涓涓浪濺殘菱蔓，戛戛風搜折葦枝。","得向曉窗閑挂翫，雪蓑煙艇恨無遺。"]', '["昔年吟醉繞江蘺，愛把漁竿伴鷺鶿。","闻说小毫能縱逸，敢憑轻素寫幽奇。","涓涓浪濺殘菱蔓，戛戛风搜折葦枝。","得向晓窗闲挂翫，雪蓑煙艇恨無遺。"]', '诗', 'shi', '', NULL, '溫處士能畫鷺鶿以四韻換之 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0353be-8b32-4bd4-a25e-6eb1cf8e35f1', '駕部鄭郎中三十八丈尹貳東周榮加金紫谷以末派之外恩舊事深因賀送', '駕部鄭郎中三十八丈尹貳东周榮加金紫谷以末派之外恩旧事深因賀送', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["香浮玉陛曉辭天，袍拂蒲茸稱少年。","郎署轉曹雖久次，京河亞尹是優賢。","縱遊雲水無公事，貴買琴書有俸錢。","今日龍門看松雪，探春明日向平泉。"]', '["香浮玉陛晓辞天，袍拂蒲茸稱少年。","郎署轉曹雖久次，京河亞尹是優賢。","縱游云水無公事，貴買琴书有俸錢。","今日龙门看松雪，探春明日向平泉。"]', '诗', 'shi', '', NULL, '駕部鄭郎中三十八丈尹貳東周榮加金紫谷以末派之外恩舊事深因賀送 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f46944d0-b26d-469e-bc37-a5d9cb9502fa', '欹枕', '欹枕', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["攲枕高眠日午春，酒酣睡足最閑身。","明朝會得窮通理，未必輸他馬上人。"]', '["攲枕高眠日午春，酒酣睡足最闲身。","明朝會得窮通理，未必輸他马上人。"]', '诗', 'shi', '', NULL, '欹枕 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d6d6a3-6e1a-40f0-9d4d-81a13979592d', '野步', '野步', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["翠嵐迎步興何長，笑領漁翁入醉鄉。","日暮渚田微雨後，鷺鶿閑暇稻花香。"]', '["翠嵐迎步兴何长，笑領漁翁入醉乡。","日暮渚田微雨後，鷺鶿闲暇稻花香。"]', '诗', 'shi', '', NULL, '野步 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809561f1-eecd-4001-9b88-152b1760a005', '偶書', '偶书', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["承時偷喜負明神，務實那能得庇身。","不會蒼蒼主何事，忍飢多是力耕人。"]', '["承时偷喜負明神，務實那能得庇身。","不會蒼蒼主何事，忍飢多是力耕人。"]', '诗', 'shi', '', NULL, '偶書 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df17548-30fe-4b41-9051-f352c6ac4bac', '靜吟', '静吟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["騷雅荒涼我未安，月和餘雪夜吟寒。","相門相客應相笑，得句勝於得好官。"]', '["騷雅荒涼我未安，月和餘雪夜吟寒。","相门相客應相笑，得句勝於得好官。"]', '诗', 'shi', '', NULL, '靜吟 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3454a4-50ac-4670-a0bd-bd91b1eef250', '和知己秋日傷懷', '和知己秋日傷懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["流水歌聲共不迴，去年天氣舊亭臺。","梁塵寂寞燕歸去，黃蜀葵花一朵開。"]', '["流水歌声共不迴，去年天氣旧亭台。","梁塵寂寞燕归去，黄蜀葵花一朵开。"]', '诗', 'shi', '', NULL, '和知己秋日傷懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b77890-1d04-41ae-9d54-39df1e65135c', '谷比歲受同年丈人故川守李侍郎教諭衰晏龍鍾益用感歎遂以章句自貽', '谷比歲受同年丈人故川守李侍郎教諭衰晏龙鍾益用感歎遂以章句自貽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["多感京河李丈人，童蒙受教便書紳。","文章至竟無功業，名宦由來致苦辛。","皎日還應知守道，平生自信解甘貧。","孤單所得皆逾分，歸種敷溪一畝春。"]', '["多感京河李丈人，童蒙受教便书紳。","文章至竟無功業，名宦由来致苦辛。","皎日還應知守道，平生自信解甘貧。","孤單所得皆逾分，归種敷溪一畝春。"]', '诗', 'shi', '', NULL, '谷比歲受同年丈人故川守李侍郎教諭衰晏龍鍾益用感歎遂以章句自貽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c793f7-b0cc-4524-b353-7378ff91642a', '郊墅', '郊墅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["韋曲樊川雨半晴，竹莊花院徧題名。","畫成煙景垂楊色，滴破春愁壓酒聲。","滿野紅塵誰得路，連天紫閣獨關情。","渼陂水色澄於鏡，何必滄浪始濯纓。"]', '["韋曲樊川雨半晴，竹莊花院徧題名。","畫成煙景垂楊色，滴破春愁壓酒声。","满野紅塵誰得路，連天紫閣独关情。","渼陂水色澄於镜，何必滄浪始濯纓。"]', '诗', 'shi', '', NULL, '郊墅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db741ec9-e7c7-4317-9394-f3c435e1b6c3', '舟行', '舟行', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["九派迢迢九月殘，舟人相語且相寬。","村逢好處嫌風便，酒到醒來覺夜寒。","蓼渚白波喧夏口，柿園紅葉憶長安。","季鷹可是思鱸鱠，引退知時自古難。"]', '["九派迢迢九月殘，舟人相語且相寬。","村逢好处嫌风便，酒到醒来覺夜寒。","蓼渚白波喧夏口，柿园紅葉憶长安。","季鷹可是思鱸鱠，引退知时自古难。"]', '诗', 'shi', '', NULL, '舟行 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('778eeb97-8550-4eb5-9c72-27b02af404af', '奔問三峰寓止近墅', '奔问三峰寓止近墅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["半年奔走頗驚魂，來謁行宮淚眼昏。","鴛鷺入朝同待漏，牛羊送日獨歸村。","灞陵散失詩千首，太華淒涼酒一樽。","兵革未休無異術，不知何以受君恩。"]', '["半年奔走頗驚魂，来謁行宮泪眼昏。","鴛鷺入朝同待漏，牛羊送日独归村。","灞陵散失诗千首，太华淒涼酒一樽。","兵革未休無異術，不知何以受君恩。"]', '诗', 'shi', '', NULL, '奔問三峰寓止近墅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac9cf3b-9a52-4672-aa7e-90e0e06ba2e0', '朝直', '朝直', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["朝直叨居省閣間，由來疎退校安閑。","落花夜靜宮中漏，微雨春寒廊下班。","自扣玄門齊寵辱，從他榮路用機關。","孤峰未得深歸去，名畫偏求水墨山。"]', '["朝直叨居省閣间，由来疎退校安闲。","落花夜静宮中漏，微雨春寒廊下班。","自扣玄门齊寵辱，從他榮路用機关。","孤峰未得深归去，名畫偏求水墨山。"]', '诗', 'shi', '', NULL, '朝直 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bfe41d3-cd24-4777-8bd1-0de8ddc58062', '巴江', '巴江', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["亂來奔走巴江濱，愁客多於江徼人。","朝醉暮醉雪開霽，一枝兩枝梅探春。","詔書罪己方哀痛，鄉縣徵兵尚苦辛。","鬢禿又驚逢獻歲，眼前渾不見交親。"]', '["亂来奔走巴江濱，愁客多於江徼人。","朝醉暮醉雪开霽，一枝兩枝梅探春。","詔书罪己方哀痛，乡縣徵兵尚苦辛。","鬢禿又驚逢獻歲，眼前渾不见交親。"]', '诗', 'shi', '', NULL, '巴江 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e5b8798-7216-4f25-bec1-ce7c61120135', '故許昌薛尚書能嘗爲都官郎中後數歲故建州李員外頻自憲府內彈拜都官員外八座外郎皆一時騷雅宗師則都官之曹振盛於此予早年請益實受深知今忝此官復是正秩豈唯俯慰孤宦何以仰繼前賢榮惕在衷遂賦自賀', '故許昌薛尚书能嘗爲都官郎中後數歲故建州李員外頻自憲府內彈拜都官員外八座外郎皆一时騷雅宗師則都官之曹振盛於此予早年請益實受深知今忝此官复是正秩豈唯俯慰孤宦何以仰繼前賢榮惕在衷遂賦自賀', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["都官雖未是名郎，踐歷曾聞薛許昌。","復有李公陪雅躅，豈宜鄭子忝餘光。","榮爲後進趨蘭署，喜拂前題在粉牆。","他日節旄如可繼，不嫌曹冷在中行。"]', '["都官雖未是名郎，踐歷曾闻薛許昌。","复有李公陪雅躅，豈宜鄭子忝餘光。","榮爲後進趨蘭署，喜拂前題在粉牆。","他日節旄如可繼，不嫌曹冷在中行。"]', '诗', 'shi', '', NULL, '故許昌薛尚書能嘗爲都官郎中後數歲故建州李員外頻自憲府內彈拜都官員外八座外郎皆一時騷雅宗師則都官之曹振盛於此予早年請益實受深知今忝此官復是正秩豈唯俯慰孤宦何以仰繼前賢榮惕在衷遂賦自賀 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b7f556-c3c4-4891-a0b7-58f4d4aa8148', '訪題表兄王藻渭上別業', '訪題表兄王藻渭上別業', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["桑林搖落渭川西，蓼水瀰瀰接稻泥。","幽檻靜來魚唱遠，暝天寒極鴈行低。","濁醪最稱看山醉，冷句偏宜選竹題。","中表人稀離亂後，花時莫惜重相攜。"]', '["桑林搖落渭川西，蓼水瀰瀰接稻泥。","幽檻静来鱼唱远，暝天寒極鴈行低。","濁醪最稱看山醉，冷句偏宜選竹題。","中表人稀離亂後，花时莫惜重相携。"]', '诗', 'shi', '', NULL, '訪題表兄王藻渭上別業 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('505d2009-c562-48bf-a6a0-45ff2b42201f', '題汝州從事廳', '題汝州從事廳', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["詩人公署如山舍，秪向堦前便採薇。","驚燕拂簾閑睡覺，落花沾硯會餐歸。","壁看舊記官多達，牓挂明文吏莫違。","自說小池栽葦後，雨涼頻見鷺鶿飛。"]', '["诗人公署如山舍，秪向堦前便採薇。","驚燕拂簾闲睡覺，落花沾硯會餐归。","壁看旧記官多達，牓挂明文吏莫違。","自说小池栽葦後，雨涼頻见鷺鶿飞。"]', '诗', 'shi', '', NULL, '題汝州從事廳 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06311a0c-4b1c-45ae-b0f4-c2484fb125b5', '谷初忝諫垣今憲長薛公方在西閣知獎隆異以四韻代述榮感', '谷初忝諫垣今憲长薛公方在西閣知獎隆異以四韻代述榮感', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["舊詩常得在高吟，不奈公心愛苦心。","道自瑣闈言下振，恩從仙殿對迴深。","流年漸覺霜欺鬢，至藥能教土化金。","自拂青萍知有地，齋誠旦夕望爲霖。"]', '["旧诗常得在高吟，不奈公心愛苦心。","道自瑣闈言下振，恩從仙殿对迴深。","流年漸覺霜欺鬢，至藥能教土化金。","自拂青萍知有地，斋誠旦夕望爲霖。"]', '诗', 'shi', '', NULL, '谷初忝諫垣今憲長薛公方在西閣知獎隆異以四韻代述榮感 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a744970a-8ffd-43b3-bac3-c71eb1ccdc68', '兵部盧郎中光濟借示詩集以四韻謝之', '兵部盧郎中光濟借示诗集以四韻謝之', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["七子風騷尋失主，五君歌誦久無聲。","調和雅樂歸時正，澄濾頹波到底清。","才大始知寰宇窄，吟高何止鬼神驚。","葉公好尚渾疎闊，忽見真龍幾喪明。"]', '["七子风騷尋失主，五君歌誦久無声。","調和雅乐归时正，澄濾頹波到底清。","才大始知寰宇窄，吟高何止鬼神驚。","葉公好尚渾疎闊，忽见真龙幾喪明。"]', '诗', 'shi', '', NULL, '兵部盧郎中光濟借示詩集以四韻謝之 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0260857c-c155-42f6-9ecd-0f2d434dfc48', '賀左省新除韋拾遺', '賀左省新除韋拾遺', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["初昇諫署是真仙，浪透桃花恰五年。","垂白郎官居座末，著緋人吏立階前。","百寮班列趨丹陛，兩掖風清上碧天。","從此追飛何處去，金鑾殿與玉堂連。"]', '["初昇諫署是真仙，浪透桃花恰五年。","垂白郎官居座末，著緋人吏立階前。","百寮班列趨丹陛，兩掖风清上碧天。","從此追飞何处去，金鑾殿與玉堂連。"]', '诗', 'shi', '', NULL, '賀左省新除韋拾遺 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4a02fe2-d08b-4cb1-b270-06469c614b68', '右省張補闕茂樞同在諫垣連居光德新春賦詠聊以寄懷', '右省張補闕茂樞同在諫垣連居光德新春賦詠聊以寄懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["小梅零落雪欺殘，浩蕩窮愁豈易寬。","唯有郎吟償晚景，且無濃醉厭春寒。","高齋每喜追攀近，麗句先憂屬和難。","十五年前諳苦節，知心不獨爲同官。"]', '["小梅零落雪欺殘，浩蕩窮愁豈易寬。","唯有郎吟償晚景，且無濃醉厭春寒。","高斋每喜追攀近，丽句先憂屬和难。","十五年前諳苦節，知心不独爲同官。"]', '诗', 'shi', '', NULL, '右省張補闕茂樞同在諫垣連居光德新春賦詠聊以寄懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('875b55e9-4c3c-418f-ae70-aeca936b66c8', '右省補闕張茂樞同在諫垣鄰居光德迭和篇什未嘗間時忽見貽謂谷將來履歷必在文昌當與何水部宋考功爲儔谷雖賦於風雅實用兢惶因抒酬寄', '右省補闕張茂樞同在諫垣鄰居光德迭和篇什未嘗间时忽见貽謂谷將来履歷必在文昌當與何水部宋考功爲儔谷雖賦於风雅實用兢惶因抒酬寄', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["何宋清名動粉闈，不才今日偶陳詩。","考功豈敢聞題品，水部猶須繫挈維。","積雪巷深酬唱夜，落花牆隔笑言時。","紫垣名士推揚切，爲話心孤倍感知。"]', '["何宋清名动粉闈，不才今日偶陳诗。","考功豈敢闻題品，水部猶須繫挈維。","積雪巷深酬唱夜，落花牆隔笑言时。","紫垣名士推揚切，爲話心孤倍感知。"]', '诗', 'shi', '', NULL, '右省補闕張茂樞同在諫垣鄰居光德迭和篇什未嘗間時忽見貽謂谷將來履歷必在文昌當與何水部宋考功爲儔谷雖賦於風雅實用兢惶因抒酬寄 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7a83fc-7c03-47ec-a121-516a517e1c87', '寄職方李員外', '寄職方李員外', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["曾袖篇章謁長卿，今來附鳳事何榮。","星臨南省陪仙步，春滿東朝接珮聲。","談笑不拘先後禮，歲寒仍契子孫情。","龍墀仗下天街暖，共看圭峰並馬行。"]', '["曾袖篇章謁长卿，今来附鳳事何榮。","星臨南省陪仙步，春满东朝接珮声。","談笑不拘先後禮，歲寒仍契子孫情。","龙墀仗下天街暖，共看圭峰並马行。"]', '诗', 'shi', '', NULL, '寄職方李員外 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb561d29-21f6-439c-b96b-b038f6032db7', '寄題詩僧秀公', '寄題诗僧秀公', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["靈一心傳清塞心，可公吟後楚公吟。","近來雅道相親少，唯仰吾師所得深。","好句未停無暇日，舊山歸老有東林。","冷曹孤宦甘寥落，多謝攜筇數訪尋。"]', '["靈一心傳清塞心，可公吟後楚公吟。","近来雅道相親少，唯仰吾師所得深。","好句未停無暇日，旧山归老有东林。","冷曹孤宦甘寥落，多謝携筇數訪尋。"]', '诗', 'shi', '', NULL, '寄題詩僧秀公 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd39f148-47df-4092-932b-9b80fd55e18c', '東蜀春晚', '东蜀春晚', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["如此浮生更別離，可堪長慟送春歸。","潼江水上楊花雪，剛逐孤舟繚繞飛。"]', '["如此浮生更別離，可堪长慟送春归。","潼江水上楊花雪，剛逐孤舟繚繞飞。"]', '诗', 'shi', '', NULL, '東蜀春晚 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49c24634-f9d1-4738-93b1-04c1f5778196', '永日有懷', '永日有懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["能消永日是摴蒱，坑塹由來似宦途。","兩擲未終楗橛內，座中何惜爲呼盧。"]', '["能消永日是摴蒱，坑塹由来似宦途。","兩擲未終楗橛內，座中何惜爲呼盧。"]', '诗', 'shi', '', NULL, '永日有懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e111b37-e887-40bf-b195-ebd224afbfaa', '槐花', '槐花', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["毿毿金蕊撲晴空，舉子魂驚落照中。","今日老郎猶有恨，昔年相虐十秋風。"]', '["毿毿金蕊撲晴空，舉子魂驚落照中。","今日老郎猶有恨，昔年相虐十秋风。"]', '诗', 'shi', '', NULL, '槐花 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b676bc-b146-4861-98eb-9cbc506de5d1', '小桃', '小桃', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["和煙和雨遮敷水，映竹映村連灞橋。","撩亂春風耐寒令，到頭贏得杏花嬌。"]', '["和煙和雨遮敷水，映竹映村連灞橋。","撩亂春风耐寒令，到头贏得杏花嬌。"]', '诗', 'shi', '', NULL, '小桃 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac882845-f9b6-4266-8c7d-178a64e66f1f', '長江縣經賈島墓', '长江縣經賈島墓', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["水繞荒墳縣路斜，耕人訝我久咨嗟。","重來兼恐無尋處，落日風吹鼓子花。"]', '["水繞荒墳縣路斜，耕人訝我久咨嗟。","重来兼恐無尋处，落日风吹鼓子花。"]', '诗', 'shi', '', NULL, '長江縣經賈島墓 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('503d1ba1-3f17-4b3f-be42-d18b4431cbfc', '嘉陵', '嘉陵', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["細雨溼萋萋，人稀江日西。","春愁腸已斷，不在子規啼。"]', '["細雨溼萋萋，人稀江日西。","春愁腸已斷，不在子規啼。"]', '诗', 'shi', '', NULL, '嘉陵 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17586e90-99a9-4e55-9c15-f64a831cc87a', '嘉陵', '嘉陵', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["細雨濕淒淒，人稀江日西。","春膓已愁斷，不待子規啼。"]', '["細雨濕淒淒，人稀江日西。","春膓已愁斷，不待子規啼。"]', '诗', 'shi', '', NULL, '嘉陵 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe65e78e-b989-4b45-a5ca-16c9208207f6', '中秋', '中秋', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["清香聞曉蓮，水國雨餘天。","天氣正得所，客心剛悄然。","亂兵何日息，故老幾人全。","此際難消遣，從來未學禪。"]', '["清香闻晓蓮，水国雨餘天。","天氣正得所，客心剛悄然。","亂兵何日息，故老幾人全。","此際难消遣，從来未学禪。"]', '诗', 'shi', '', NULL, '中秋 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55137af3-1bc8-4f99-a392-23c320c80bbc', '朝謁', '朝謁', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["捧日整朝簪，千官一片心。","班趨黃道急，殿接紫宸深。","威鳳迴香扆，新鶯囀上林。","小松含瑞露，春翠易成陰。"]', '["捧日整朝簪，千官一片心。","班趨黄道急，殿接紫宸深。","威鳳迴香扆，新鶯囀上林。","小松含瑞露，春翠易成陰。"]', '诗', 'shi', '', NULL, '朝謁 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fad07e14-4073-4c1f-8fb3-9367e82c2017', '錦浦', '錦浦', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["流落夜淒淒，春寒錦浦西。","不甘花逐水，可惜雪成泥。","病眼嫌燈近，離腸賴酒迷。","憑君囑鵯鵊，莫向五更啼。"]', '["流落夜淒淒，春寒錦浦西。","不甘花逐水，可惜雪成泥。","病眼嫌灯近，離腸賴酒迷。","憑君囑鵯鵊，莫向五更啼。"]', '诗', 'shi', '', NULL, '錦浦 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa0a081-1919-43b6-b8cd-178374477bf8', '峨嵋山', '峨嵋山', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["萬仞白雲端，經春雪未殘。","夏消江峽滿，晴照蜀樓寒。","造境知僧熟，歸林認鶴難。","會須朝闕去，秪有畫圖看。"]', '["万仞白云端，經春雪未殘。","夏消江峽满，晴照蜀楼寒。","造境知僧熟，归林認鹤难。","會須朝闕去，秪有畫圖看。"]', '诗', 'shi', '', NULL, '峨嵋山 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2040218-eba4-4bd4-87bf-3f366fdb29a2', '蜀江有弔', '蜀江有弔', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["孟子有良策，惜哉今已而。","徒將心體國，不識道消時。","折檻未爲切，沈湘何足悲。","蒼蒼無問處，煙雨徧江蘺。"]', '["孟子有良策，惜哉今已而。","徒將心體国，不識道消时。","折檻未爲切，沈湘何足悲。","蒼蒼無问处，煙雨徧江蘺。"]', '诗', 'shi', '', NULL, '蜀江有弔 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e112f756-5ffa-4e6e-ae76-f4fa8ebe863c', '書村叟壁', '书村叟壁', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["草肥朝牧牛，桑綠晚鳴鳩。","列岫簷前見，清泉碓下流。","春蔬和雨割，社酒向花篘。","引我南陂去，籬邊有小舟。"]', '["草肥朝牧牛，桑綠晚鳴鳩。","列岫簷前见，清泉碓下流。","春蔬和雨割，社酒向花篘。","引我南陂去，籬邊有小舟。"]', '诗', 'shi', '', NULL, '書村叟壁 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b7c197-b3d2-4c1b-a02c-d891b1597bcc', '題進士王駕郊居', '題進士王駕郊居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["前山微有雨，永巷淨無塵。","牛臥籬陰晚，鳩鳴村意春。","時浮應寡合，道在不嫌貧。","後徑臨陂水，菰蒲是切鄰。"]', '["前山微有雨，永巷淨無塵。","牛臥籬陰晚，鳩鳴村意春。","时浮應寡合，道在不嫌貧。","後徑臨陂水，菰蒲是切鄰。"]', '诗', 'shi', '', NULL, '題進士王駕郊居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8ac58d6-0251-4f6b-9ca9-67bed33dfc46', '題莊嚴寺休公院', '題莊嚴寺休公院', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["秋深庭色好，紅葉間青松。","病客殊無著，吾師甚見容。","疎鐘和細溜，高塔等遙峰。","未省求名侶，頻於此地逢。"]', '["秋深庭色好，紅葉间青松。","病客殊無著，吾師甚见容。","疎鐘和細溜，高塔等遙峰。","未省求名侶，頻於此地逢。"]', '诗', 'shi', '', NULL, '題莊嚴寺休公院 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5349d0c0-6584-4c57-a7d2-1d3f2863cdfa', '題興善寺', '題兴善寺', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寺在帝城陰，清虛勝二林。","蘚侵隋畫暗，茶助越甌深。","巢鶴和鐘唳，詩僧倚錫吟。","煙莎後池水，前跡杳難尋。"]', '["寺在帝城陰，清虛勝二林。","蘚侵隋畫暗，茶助越甌深。","巢鹤和鐘唳，诗僧倚錫吟。","煙莎後池水，前跡杳难尋。"]', '诗', 'shi', '', NULL, '題興善寺 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd9df830-cc32-4eeb-b0c5-3462d7ca011c', '宿澄泉蘭若', '宿澄泉蘭若', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["山半古招提，空林雪月迷。","亂流分石上，斜漢在松西。","雲集寒菴宿，猨先曉磬啼。","此心如了了，即此是曹溪。"]', '["山半古招提，空林雪月迷。","亂流分石上，斜漢在松西。","云集寒菴宿，猨先晓磬啼。","此心如了了，即此是曹溪。"]', '诗', 'shi', '', NULL, '宿澄泉蘭若 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bd06730-a44c-440e-9a17-93af58548d9a', '送舉子下第東歸', '送舉子下第东归', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["夫子道何孤，青雲未得途。","詩書難捨魯，山水暫遊吳。","野綠梅陰重，江春浪勢麤。","秣陵兵役後，舊業半成蕪。"]', '["夫子道何孤，青云未得途。","诗书难捨魯，山水暫游吳。","野綠梅陰重，江春浪勢麤。","秣陵兵役後，旧業半成蕪。"]', '诗', 'shi', '', NULL, '送舉子下第東歸 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d191b4-d134-4a8f-81f2-687f2a63b6a7', '寄察院李侍御文炬', '寄察院李侍御文炬', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["古柏間疎篁，清陰在印牀。","宿郊虔點饌，秋寺靜監香。","參集行多揖，風儀見即莊。","佇聞橫擘去，帷集諫書囊。"]', '["古柏间疎篁，清陰在印牀。","宿郊虔点饌，秋寺静監香。","參集行多揖，风儀见即莊。","佇闻橫擘去，帷集諫书囊。"]', '诗', 'shi', '', NULL, '寄察院李侍御文炬 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b663455e-25c3-400b-8a21-ca6bee9eddb7', '偶懷寄臺院孫端公棨', '偶懷寄台院孫端公棨', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["才拙道仍孤，無何捨釣徒。","班雖沾玉筍，香不近金爐。","雨露瞻雙闕，煙波隔五湖。","唯君應見念，曾共伏青蒲。"]', '["才拙道仍孤，無何捨釣徒。","班雖沾玉筍，香不近金爐。","雨露瞻雙闕，煙波隔五湖。","唯君應见念，曾共伏青蒲。"]', '诗', 'shi', '', NULL, '偶懷寄臺院孫端公棨 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0385c28-710b-4bdb-93d4-dcde5d609186', '次韻和秀上人遊南五臺', '次韻和秀上人游南五台', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["中峰曾到處，題記沒蒼苔。","振錫傳深谷，翻經想舊臺。","蒼松臨砌偃，驚鹿驀溪來。","內殿評詩切，身迴心未迴。"]', '["中峰曾到处，題記沒蒼苔。","振錫傳深谷，翻經想旧台。","蒼松臨砌偃，驚鹿驀溪来。","內殿評诗切，身迴心未迴。"]', '诗', 'shi', '', NULL, '次韻和秀上人遊南五臺 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a895719-7d0a-4aff-8c8b-1b1614402b17', '乖慵', '乖慵', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["乖慵居竹裏，涼冷臥池東。","一霎芰荷雨，幾迴簾幕風。","遠僧來扣寂，小吏笑書空。","衰鬢霜供白，愁顏酒借紅。","扇輕搖鷺羽，屏古畫漁翁。","自得無端趣，琴棊舫子中。"]', '["乖慵居竹裏，涼冷臥池东。","一霎芰荷雨，幾迴簾幕风。","远僧来扣寂，小吏笑书空。","衰鬢霜供白，愁顏酒借紅。","扇轻搖鷺羽，屏古畫漁翁。","自得無端趣，琴棊舫子中。"]', '诗', 'shi', '', NULL, '乖慵 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80c5944f-1c88-47cc-b3c2-b49e7937e182', '南宮寓直', '南宮寓直', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寓直事非輕，宦孤憂且榮。","制承黃紙重，詞見紫垣清。","曉霽庭松色，風和禁漏聲。","僧攜新茗伴，吏掃落花迎。","鎖印詩心動，垂簾睡思生。","粉廊曾試處，石柱昔賢名。","來誤宮窗燕，啼疑苑樹鶯。","殘陽應更好，歸促恨嚴城。"]', '["寓直事非轻，宦孤憂且榮。","制承黄紙重，词见紫垣清。","晓霽庭松色，风和禁漏声。","僧携新茗伴，吏掃落花迎。","鎖印诗心动，垂簾睡思生。","粉廊曾試处，石柱昔賢名。","来誤宮窗燕，啼疑苑樹鶯。","殘陽應更好，归促恨嚴城。"]', '诗', 'shi', '', NULL, '南宮寓直 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca814cd2-078a-435b-8ecb-3f0b7c8a1457', '恩門小諫雨中乞菊栽', '恩门小諫雨中乞菊栽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["握蘭將滿歲，栽菊伴吟詩。","老去慵趨世，朝迴獨繞籬。","遞香風細細，澆綠水瀰瀰。","秪共山僧賞，何當國士移。","孤根深有託，微雨正相宜。","更待金英發，憑君插一枝。"]', '["握蘭將满歲，栽菊伴吟诗。","老去慵趨世，朝迴独繞籬。","遞香风細細，澆綠水瀰瀰。","秪共山僧賞，何當国士移。","孤根深有託，微雨正相宜。","更待金英發，憑君插一枝。"]', '诗', 'shi', '', NULL, '恩門小諫雨中乞菊栽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf90bf5-b8c0-4951-88ea-f7d70d7c59ff', '荆渚八月十五夜值雨寄同年李嶼', '荆渚八月十五夜值雨寄同年李嶼', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["共待輝光夜，翻成黯澹秋。","正宜清路望，潛起滴堦愁。","棹倚袁宏渚，簾垂庾亮樓。","桂無香實落，蘭有露花休。","玉漏添蕭索，金尊阻獻酬。","明年佳景在，相約向神州。"]', '["共待輝光夜，翻成黯澹秋。","正宜清路望，潛起滴堦愁。","棹倚袁宏渚，簾垂庾亮楼。","桂無香實落，蘭有露花休。","玉漏添蕭索，金尊阻獻酬。","明年佳景在，相約向神州。"]', '诗', 'shi', '', NULL, '荆渚八月十五夜值雨寄同年李嶼 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6317eb7-2efa-4c57-8f2e-4fd35796acb3', '寄左省張起居', '寄左省張起居', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["含香復記言，清秩稱當年。","點筆非常筆，朝天最近天。","家聲三相後，公事一人前。","詩句江郎伏，書蹤甯氏傳。","風標欺鷺鶴，才力湧沙泉。","居僻貧無慮，名高退更堅。","漁舟思靜泛，僧榻寄閑眠。","消息當彌入，絲綸的粲然。","依棲常接跡，屬和舊盈編。","開口人皆信，淒涼是謝氈。"]', '["含香复記言，清秩稱當年。","点笔非常笔，朝天最近天。","家声三相後，公事一人前。","诗句江郎伏，书蹤甯氏傳。","风標欺鷺鹤，才力湧沙泉。","居僻貧無慮，名高退更堅。","漁舟思静泛，僧榻寄闲眠。","消息當彌入，絲綸的粲然。","依棲常接跡，屬和旧盈編。","开口人皆信，淒涼是謝氈。"]', '诗', 'shi', '', NULL, '寄左省張起居 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c8d65a0-6a55-47ba-9edd-7cfb3d1b0f39', '前寄左省張起居一百言尋蒙唱酬見譽過實却用舊韻重荅', '前寄左省張起居一百言尋蒙唱酬见譽過實却用旧韻重荅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["減瘦經多難，憂傷集晚年。","吟高風過樹，坐久夜涼天。","旅退慙隨衆，孤飛怯向前。","釣朋蓑叟在，藥術衲僧傳。","鬢禿趨榮路，腸焦鄙盜泉。","品徒誠有隔，推唱意何堅。","寒地殊知感，秋燈耿不眠。","從來甘默爾，自此倍怡然。","蘭爲官須握，蒲因學更編。","預愁搖落後，子美笑無氈。"]', '["減瘦經多难，憂傷集晚年。","吟高风過樹，坐久夜涼天。","旅退慙隨衆，孤飞怯向前。","釣朋蓑叟在，藥術衲僧傳。","鬢禿趨榮路，腸焦鄙盜泉。","品徒誠有隔，推唱意何堅。","寒地殊知感，秋灯耿不眠。","從来甘默爾，自此倍怡然。","蘭爲官須握，蒲因学更編。","預愁搖落後，子美笑無氈。"]', '诗', 'shi', '', NULL, '前寄左省張起居一百言尋蒙唱酬見譽過實却用舊韻重荅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d80a795-beea-4881-b268-de73dc423218', '讀故許昌薛尚書詩集', '读故許昌薛尚书诗集', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["篇篇高且真，真爲國風陳。","澹薄雖師古，縱橫得意新。","翦裁成幾篋，唱和是誰人。","華岳題無敵，黃河句絕倫。","吟殘荔枝雨，詠徹海棠春。","李白欺前輩，陶潛仰後塵。","難忘嵩室下，不負蜀江濱。","屬思看山眼，冥搜倚樹身。","楷模勞夢想，諷誦爽精神。","落筆空追愴，曾蒙借斧斤。"]', '["篇篇高且真，真爲国风陳。","澹薄雖師古，縱橫得意新。","翦裁成幾篋，唱和是誰人。","华岳題無敵，黄河句絕倫。","吟殘荔枝雨，詠徹海棠春。","李白欺前輩，陶潛仰後塵。","难忘嵩室下，不負蜀江濱。","屬思看山眼，冥搜倚樹身。","楷模勞梦想，諷誦爽精神。","落笔空追愴，曾蒙借斧斤。"]', '诗', 'shi', '', NULL, '讀故許昌薛尚書詩集 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ece91815-1c5b-40c2-96b8-b7e264448e4e', '送水部張郎中彥回宰洛陽', '送水部張郎中彥回宰洛陽', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["何遜蘭休握，陶潛柳正垂。","官清真塞詔，事簡好吟詩。","春漏懷丹闕，涼船泛碧伊。","已虛西閣位，朝夕鳳書追。"]', '["何遜蘭休握，陶潛柳正垂。","官清真塞詔，事簡好吟诗。","春漏懷丹闕，涼船泛碧伊。","已虛西閣位，朝夕鳳书追。"]', '诗', 'shi', '', NULL, '送水部張郎中彥回宰洛陽 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c3c0a2-a3c8-4512-9ee6-be78df9d48aa', '贈咸陽王主簿', '贈咸陽王主簿', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["可愛咸陽王主簿，窮經盡到昔賢心。","登科未足酬多學，執卷猶聞惜寸陰。","自與山妻舂斗粟，祗憑鄰叟典孤琴。","我來賒酒相留宿，聽我披衣看雪吟。"]', '["可愛咸陽王主簿，窮經尽到昔賢心。","登科未足酬多学，執卷猶闻惜寸陰。","自與山妻舂斗粟，祗憑鄰叟典孤琴。","我来賒酒相留宿，听我披衣看雪吟。"]', '诗', 'shi', '', NULL, '贈咸陽王主簿 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfbcffe9-27fe-4233-a4cb-90c3d9544530', '松', '松', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["下視垂楊拂路塵，雙峰石上覆苔文。","濃霜滿逕無紅葉，晚日高枝有白雲。","春砌花飄僧旋掃，寒溪子落鶴先聞。","那堪寂寞悲風起，千樹深藏李白墳。"]', '["下視垂楊拂路塵，雙峰石上覆苔文。","濃霜满逕無紅葉，晚日高枝有白云。","春砌花飄僧旋掃，寒溪子落鹤先闻。","那堪寂寞悲风起，千樹深藏李白墳。"]', '诗', 'shi', '', NULL, '松 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e16272d-d13b-41b8-bcbb-1cf54c6445c0', '梅', '梅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江國正寒春信穩，嶺頭枝上雪飄飄。","何言落處堪惆悵，直是開時也寂寥。","素豔照尊桃莫比，孤香黏袖李須饒。","離人南去腸應斷，片片隨鞭過楚橋。"]', '["江国正寒春信穩，嶺头枝上雪飄飄。","何言落处堪惆悵，直是开时也寂寥。","素豔照尊桃莫比，孤香黏袖李須饒。","離人南去腸應斷，片片隨鞭過楚橋。"]', '诗', 'shi', '', NULL, '梅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14335120-5191-430e-a341-1eb260d84874', '鶴', '鹤', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["一自王喬放自由，俗人行處嬾回頭。","睡輕旋覺松花墮，舞罷閑聽澗水流。","羽翼光明欺積雪，風神灑落占高秋。","應嫌白鷺無仙骨，長伴漁翁宿葦洲。"]', '["一自王喬放自由，俗人行处嬾回头。","睡轻旋覺松花墮，舞罷闲听澗水流。","羽翼光明欺積雪，风神灑落占高秋。","應嫌白鷺無仙骨，长伴漁翁宿葦洲。"]', '诗', 'shi', '', NULL, '鶴 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9f83c4-3e37-4c57-b65b-ad74f309f963', '重陽夜旅懷', '重陽夜旅懷', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["強插黃花三兩枝，還圖一醉浸愁眉。","半牀斜月醉醒後，惆悵多於未醉時。"]', '["強插黄花三兩枝，還圖一醉浸愁眉。","半牀斜月醉醒後，惆悵多於未醉时。"]', '诗', 'shi', '', NULL, '重陽夜旅懷 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cb3d360-e42a-49b4-b85d-f7e9624cdda7', '壬戌西幸後', '壬戌西幸後', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["武德門前顥氣新，雪融鴛瓦土膏春。","夜來夢到宣麻處，草沒龍墀不見人。"]', '["武德门前顥氣新，雪融鴛瓦土膏春。","夜来梦到宣麻处，草沒龙墀不见人。"]', '诗', 'shi', '', NULL, '壬戌西幸後 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d12331-1533-42d3-8c50-433e54aa54f5', '多虞', '多虞', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["多虞難住人稀處，近耗渾無戰罷碁。","向闕歸山俱未得，且沽春酒且吟詩。"]', '["多虞难住人稀处，近耗渾無戰罷碁。","向闕归山俱未得，且沽春酒且吟诗。"]', '诗', 'shi', '', NULL, '多虞 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b75fa89f-86b0-42ac-b765-a7b83f1cf895', '短褐', '短褐', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["閑披短褐杖山藤，頭不是僧心是僧。","坐睡覺來清夜半，芭蕉影動道場燈。"]', '["闲披短褐杖山藤，头不是僧心是僧。","坐睡覺来清夜半，芭蕉影动道場灯。"]', '诗', 'shi', '', NULL, '短褐 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016c91df-4b23-41e7-81bd-81e7dbf70da0', '曲江紅杏', '曲江紅杏', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["遮莫江頭柳色遮，日濃鶯睡一枝斜。","女郎折得殷勤看，道是春風及第花。"]', '["遮莫江头柳色遮，日濃鶯睡一枝斜。","女郎折得殷勤看，道是春风及第花。"]', '诗', 'shi', '', NULL, '曲江紅杏 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541dc566-b159-4a4f-bc87-408027ea2f5c', '折得梅', '折得梅', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["寒步江村折得梅，孤香不肯待春催。","滿枝盡是愁人淚，莫殢朝來露溼來。"]', '["寒步江村折得梅，孤香不肯待春催。","满枝尽是愁人泪，莫殢朝来露溼来。"]', '诗', 'shi', '', NULL, '折得梅 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c9456f-4357-4a76-b5cc-7841dcb0ebc7', '牡丹', '牡丹', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["畫堂簾卷張清宴，含香帶霧情無限。","春風愛惜未放開，柘枝鼓振紅英綻。"]', '["畫堂簾卷張清宴，含香带霧情無限。","春风愛惜未放开，柘枝鼓振紅英綻。"]', '诗', 'shi', '', NULL, '牡丹 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe40775f-6060-4e63-bac4-c6db46197066', '寂寞', '寂寞', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江郡人稀便是村，踏青天氣欲黃昏。","春愁不破還成醉，衣上淚痕和酒痕。"]', '["江郡人稀便是村，踏青天氣欲黄昏。","春愁不破還成醉，衣上泪痕和酒痕。"]', '诗', 'shi', '', NULL, '寂寞 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a078e612-cdf9-4c1f-ba7b-71f1ab8b342b', '亂後灞上', '亂後灞上', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["柳絲牽水杏房紅，煙岸人稀草色中。","日暮一行高鳥處，依稀合是望春宮。"]', '["柳絲牽水杏房紅，煙岸人稀草色中。","日暮一行高鸟处，依稀合是望春宮。"]', '诗', 'shi', '', NULL, '亂後灞上 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2c1b62-b426-4de1-9b18-8e741ebc0ed0', '長門怨二首 一', '长门怨二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["閑把羅衣泣鳳皇，先朝曾教舞霓裳。","春來却羨庭花落，得逐晴風出禁牆。"]', '["闲把羅衣泣鳳皇，先朝曾教舞霓裳。","春来却羨庭花落，得逐晴风出禁牆。"]', '诗', 'shi', '', NULL, '長門怨二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9624023a-f595-426b-aff8-349adc530d34', '長門怨二首 二', '长门怨二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["流水君恩共不回，杏花爭忍掃成堆。","殘春未必多煙雨，淚滴閑堦長綠苔。"]', '["流水君恩共不回，杏花爭忍掃成堆。","殘春未必多煙雨，泪滴闲堦长綠苔。"]', '诗', 'shi', '', NULL, '長門怨二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64abde06-fe63-4b9b-bc16-d097c8f2455f', '郊野戲題', '郊野戲題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["竹巷溪橋天氣涼，荷開稻熟村酒香。","唯憂野叟相迴避，莫道儂家是漢郎。"]', '["竹巷溪橋天氣涼，荷开稻熟村酒香。","唯憂野叟相迴避，莫道儂家是漢郎。"]', '诗', 'shi', '', NULL, '郊野戲題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('801d77ad-17c3-4d0d-9a22-54fabfe25366', '宗人惠四藥', '宗人惠四藥', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["宗人忽惠西山藥，四味清新香助茶。","爽得心神便騎鶴，何須燒得白朱砂。"]', '["宗人忽惠西山藥，四味清新香助茶。","爽得心神便騎鹤，何須燒得白朱砂。"]', '诗', 'shi', '', NULL, '宗人惠四藥 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd40b3cb-acc1-487b-8cca-2f813ac2aa85', '題張衡廟', '題張衡廟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["遠俗只憑淫祀切，多年平子固悠悠。","江煙日午無簫鼓，直到如今詠四愁。"]', '["远俗只憑淫祀切，多年平子固悠悠。","江煙日午無簫鼓，直到如今詠四愁。"]', '诗', 'shi', '', NULL, '題張衡廟 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c3b7a4-1f41-4f2f-9a7d-717a16d58a71', '山鳥', '山鸟', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["驚飛失勢粉牆高，好箇聲音好羽毛。","小婢不須催柘彈，且從枝上喫櫻桃。"]', '["驚飞失勢粉牆高，好箇声音好羽毛。","小婢不須催柘彈，且從枝上喫櫻桃。"]', '诗', 'shi', '', NULL, '山鳥 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af1c349-24d3-44e9-a75d-9ab67d5833b8', '黯然', '黯然', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["搢紳奔避復淪亡，消息春來到水鄉。","屈指故人能幾許，月明花好更悲涼。"]', '["搢紳奔避复淪亡，消息春来到水乡。","屈指故人能幾許，月明花好更悲涼。"]', '诗', 'shi', '', NULL, '黯然 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35462bad-977e-411e-917a-890cb32b285e', '借薛尚書集', '借薛尚书集', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["江天冬暖似花時，上國音塵杳未知。","正被蟲聲喧老耳，今君又借薛能詩。"]', '["江天冬暖似花时，上国音塵杳未知。","正被蟲声喧老耳，今君又借薛能诗。"]', '诗', 'shi', '', NULL, '借薛尚書集 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f7ede4b-21fd-4503-b739-22529390b6c5', '小北廰閑題', '小北廰闲題', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["冷曹孤宦本相宜，山在牆南落照時。","洗竹澆莎足公事，一來贏寫一聯詩。"]', '["冷曹孤宦本相宜，山在牆南落照时。","洗竹澆莎足公事，一来贏寫一聯诗。"]', '诗', 'shi', '', NULL, '小北廰閑題 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8659fcdb-5c76-4529-a218-2099d20c0889', '菊', '菊', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["日日池邊載酒行，黃昏猶自遶黃英。","重陽過後頻來此，甚覺多情勝薄情。"]', '["日日池邊載酒行，黄昏猶自遶黄英。","重陽過後頻来此，甚覺多情勝薄情。"]', '诗', 'shi', '', NULL, '菊 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4626e2b1-8836-4df3-a67d-137231006e39', '贈楊夔二首 一', '贈楊夔二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["散賦宂書高且奇，百篇仍有百篇詩。","江湖休灑春風淚，十軸香於一桂枝。"]', '["散賦宂书高且奇，百篇仍有百篇诗。","江湖休灑春风泪，十軸香於一桂枝。"]', '诗', 'shi', '', NULL, '贈楊夔二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1010dda-0424-49da-8d74-bac2dab4dcd6', '贈楊夔二首 二', '贈楊夔二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["時無韓柳道難窮，也覺天公不至公。","看取年年金牓上，幾人才氣似揚雄。"]', '["时無韓柳道难窮，也覺天公不至公。","看取年年金牓上，幾人才氣似揚雄。"]', '诗', 'shi', '', NULL, '贈楊夔二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9298b80e-7bc7-4fed-8eae-c852558a6c13', '中秋夜有懷', '中秋夜有懷', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["趨馳早晚休，一歲又殘秋。","若只如今日，何難致白頭。","滄波歸處遠，旅舍向邊愁。","賴見前賢說，窮通不自由。"]', '["趨驰早晚休，一歲又殘秋。","若只如今日，何难致白头。","滄波归处远，旅舍向邊愁。","賴见前賢说，窮通不自由。"]', '诗', 'shi', '', NULL, '中秋夜有懷 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ca960f-3153-4838-af1e-b1242e1443c8', '尋白石山人澗', '尋白石山人澗', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["路窮川島上，果值古仙家。","陰洞長鳴磬，石泉寒泛花。","莓苔深峭壁，煙靄積層崖。","難見囊中術，人間有歲華。"]', '["路窮川島上，果值古仙家。","陰洞长鳴磬，石泉寒泛花。","莓苔深峭壁，煙靄積層崖。","难见囊中術，人间有歲华。"]', '诗', 'shi', '', NULL, '尋白石山人澗 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c5c73fa-2f2a-4cb9-9a69-4640eb4e8bb6', '遊頭陀寺上方', '游头陀寺上方', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["高步陟崔嵬，吟閑路惜迴。","寺從何代有，僧是梵宮來。","暮靄連沙積，餘霞逼檻開。","更期招靜者，長嘯上方臺。"]', '["高步陟崔嵬，吟闲路惜迴。","寺從何代有，僧是梵宮来。","暮靄連沙積，餘霞逼檻开。","更期招静者，长嘯上方台。"]', '诗', 'shi', '', NULL, '遊頭陀寺上方 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a194fa86-5a90-4f00-a0e3-26137a24ae7b', '歸山夜發湖中', '归山夜發湖中', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["廣澤去無邊，夜程風信偏。","疎星遙抵浪，遠燒似迎船。","響嶽猿相次，翻空雁接連。","北歸家業就，深處更踰年。"]', '["廣澤去無邊，夜程风信偏。","疎星遙抵浪，远燒似迎船。","响嶽猿相次，翻空雁接連。","北归家業就，深处更踰年。"]', '诗', 'shi', '', NULL, '歸山夜發湖中 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ad35a2-f000-4211-a0bf-25997d09b6ee', '同友人會裴明府縣樓', '同友人會裴明府縣楼', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["開閣雨吹塵，陶家揖上賓。","湖山萬疊翠，汀樹一行春。","景逼歸簷燕，歌喧已醉身。","登臨興未足，喜有數年因。"]', '["开閣雨吹塵，陶家揖上賓。","湖山万叠翠，汀樹一行春。","景逼归簷燕，歌喧已醉身。","登臨兴未足，喜有數年因。"]', '诗', 'shi', '', NULL, '同友人會裴明府縣樓 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('181300bf-da35-4eb7-a74e-b5ba6eb09038', '荆山夜泊與親友遇', '荆山夜泊與親友遇', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["山海兩分歧，停舟偶此期。","別來何限意，相見卻無詞。","坐永神疑夢，愁多鬢欲絲。","趨名易遲晚，此去莫經時。"]', '["山海兩分歧，停舟偶此期。","別来何限意，相见卻無词。","坐永神疑梦，愁多鬢欲絲。","趨名易遲晚，此去莫經时。"]', '诗', 'shi', '', NULL, '荆山夜泊與親友遇 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a6c904-645c-49d1-aa43-9d881f00ddc2', '北遊夜懷', '北游夜懷', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["苦心終是否，捨此復無營。","已致歸成晚，非緣去有程。","館空吟向月，霜曙坐聞更。","住久誰相問，馳羸又獨行。"]', '["苦心終是否，捨此复無營。","已致归成晚，非緣去有程。","館空吟向月，霜曙坐闻更。","住久誰相问，驰羸又独行。"]', '诗', 'shi', '', NULL, '北遊夜懷 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114dd663-8166-40ba-a687-3aa0952fca67', '重經漢南', '重經漢南', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["分散多如此，人情豈自由。","重來看月夕，不似去年秋。","息慮雖孤寢，論空未識愁。","須同醉鄉者，萬事付江流。"]', '["分散多如此，人情豈自由。","重来看月夕，不似去年秋。","息慮雖孤寢，論空未識愁。","須同醉乡者，万事付江流。"]', '诗', 'shi', '', NULL, '重經漢南 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beecc85d-bf46-4567-bbfe-7745f1f0442d', '湘江', '湘江', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["孤舟方此去，嘉景稱於聞。","煙盡九峰雪，雨生諸派雲。","沙寒鴻鵠聚，底極龜魚分。","異日誰爲侶，逍遙耕釣羣。"]', '["孤舟方此去，嘉景稱於闻。","煙尽九峰雪，雨生諸派云。","沙寒鴻鵠聚，底極龟鱼分。","異日誰爲侶，逍遙耕釣羣。"]', '诗', 'shi', '', NULL, '湘江 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f790d31e-22c7-4bce-b8c2-84f07a937924', '黔中書事', '黔中书事', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["巴蜀水南偏，山窮塞壘寬。","歲時將近臘，草樹未知寒。","獨狖啼朝雨，羣牛向暮灘。","更聞蠻俗近，烽火不艱難。"]', '["巴蜀水南偏，山窮塞壘寬。","歲时將近臘，草樹未知寒。","独狖啼朝雨，羣牛向暮灘。","更闻蠻俗近，烽火不艱难。"]', '诗', 'shi', '', NULL, '黔中書事 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ea444d-0c09-4cc3-bd76-295115cd814f', '經李翰林廬山屏風疊所居', '經李翰林廬山屏风叠所居', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["放逐非多罪，江湖偶不廻。","深居應有謂，濟代豈無才。","疊巘晴舒障，寒川暗動雷。","誰能續高興，醉死一千杯。"]', '["放逐非多罪，江湖偶不廻。","深居應有謂，濟代豈無才。","叠巘晴舒障，寒川暗动雷。","誰能續高兴，醉死一千杯。"]', '诗', 'shi', '', NULL, '經李翰林廬山屏風疊所居 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bda7434-051c-41c3-a046-2833d66a8972', '酬簡寂熊尊師以趙員外廬山草堂見借', '酬簡寂熊尊師以趙員外廬山草堂见借', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["豈易投居止，廬山得此峰。","主人曾已許，仙客偶相逢。","顧己恩難答，窮經業未慵。","還能勵僮僕，稍更補杉松。"]', '["豈易投居止，廬山得此峰。","主人曾已許，仙客偶相逢。","顧己恩难答，窮經業未慵。","還能勵僮僕，稍更補杉松。"]', '诗', 'shi', '', NULL, '酬簡寂熊尊師以趙員外廬山草堂見借 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e71e2a-d07e-4e5a-aeac-086914de180f', '寄懷孫處士', '寄懷孫处士', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["生平酌與吟，誰是見君心。","上國一歸去，滄波閑至今。","鐘繁秋寺遠，岸闊晚濤深。","疎放長如此，何人更得尋。"]', '["生平酌與吟，誰是见君心。","上国一归去，滄波闲至今。","鐘繁秋寺远，岸闊晚濤深。","疎放长如此，何人更得尋。"]', '诗', 'shi', '', NULL, '寄懷孫處士 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96d21ddb-a1da-473c-ac94-00546aa9bf0e', '漢南懷友人', '漢南懷友人', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["此身西復東，何計此相逢。","夢盡吳越水，恨深湘漢鐘。","積雲開去路，曙雪疊前峰。","誰即知非舊，憐君忽見容。"]', '["此身西复东，何計此相逢。","梦尽吳越水，恨深湘漢鐘。","積云开去路，曙雪叠前峰。","誰即知非旧，怜君忽见容。"]', '诗', 'shi', '', NULL, '漢南懷友人 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce73c81-7a08-43a1-9c6b-26425ff8bc73', '送人下第歸江州', '送人下第归江州', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["名高不俟召，操賦獻君門。","偶屈應緣數，他人盡爲冤。","新春城外路，舊隱水邊村。","歸去無勞久，知音待更論。"]', '["名高不俟召，操賦獻君门。","偶屈應緣數，他人尽爲冤。","新春城外路，旧隐水邊村。","归去無勞久，知音待更論。"]', '诗', 'shi', '', NULL, '送人下第歸江州 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288c1772-ce41-4ffa-8b81-58be8042b9a1', '送蘇處士歸西山', '送蘇处士归西山', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["南游何所爲，一篋又空歸。","守道安清世，無心換白衣。","深溪猿共暮，絕頂客來稀。","早晚還相見，論詩更及微。"]', '["南游何所爲，一篋又空归。","守道安清世，無心換白衣。","深溪猿共暮，絕頂客来稀。","早晚還相见，論诗更及微。"]', '诗', 'shi', '', NULL, '送蘇處士歸西山 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1291ca8f-6964-4cf5-a911-295e4f0791cc', '送李處士歸山', '送李处士归山', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["舊山來復去，不與世人論。","得道書留篋，忘機酒滿尊。","溪軒松偃坐，石室水臨門。","應有頻相訪，相看坐到昏。"]', '["旧山来复去，不與世人論。","得道书留篋，忘機酒满尊。","溪軒松偃坐，石室水臨门。","應有頻相訪，相看坐到昏。"]', '诗', 'shi', '', NULL, '送李處士歸山 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25886d8e-163c-45c1-8c3f-032f36cb36c9', '送新羅客歸', '送新羅客归', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["君家滄海外，一別見何因。","風土難知教，程途自致貧。","浸天波色晚，橫吹鳥行春。","明發千檣下，應爲更遠人。"]', '["君家滄海外，一別见何因。","风土难知教，程途自致貧。","浸天波色晚，橫吹鸟行春。","明發千檣下，應爲更远人。"]', '诗', 'shi', '', NULL, '送新羅客歸 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff08281-f9c1-4c35-af53-faa1d085076f', '府試萊城晴日望三山', '府試萊城晴日望三山', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["不易識蓬瀛，憑高望有程。","盤根出巨浸，遠色到孤城。","隱隱排雲峻，層層就日明。","淨收殘靄盡，浮動嫩嵐輕。","縱目徒多暇，馳心累發誠。","從容更何往，此路徹三清。"]', '["不易識蓬瀛，憑高望有程。","盤根出巨浸，远色到孤城。","隐隐排云峻，層層就日明。","淨收殘靄尽，浮动嫩嵐轻。","縱目徒多暇，驰心累發誠。","從容更何往，此路徹三清。"]', '诗', 'shi', '', NULL, '府試萊城晴日望三山 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('444ef586-4750-4ce8-9a2a-b56c65bae04d', '題故李賓客廬山草堂', '題故李賓客廬山草堂', 'f21c45c1-a29e-4b22-9031-ad036e28876a', '唐', '["難窮林下趣，坐使致君恩。","術業行當代，封章動諫垣。","已明邪佞迹，幾雪薜蘿冤。","報主深知此，憂民詎可論。","名將山共古，跡與道俱存。","爲謝重來者，何人更及門。"]', '["难窮林下趣，坐使致君恩。","術業行當代，封章动諫垣。","已明邪佞迹，幾雪薜蘿冤。","報主深知此，憂民詎可論。","名將山共古，跡與道俱存。","爲謝重来者，何人更及门。"]', '诗', 'shi', '', NULL, '題故李賓客廬山草堂 許彬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('193e0151-be6a-4975-a7fa-a4bfc513bd84', '秋夕送友人歸吳', '秋夕送友人归吳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["離心醉豈懽，把酒彊相寬。","世路須求達，還家亦未安。","旅程愁算遠，江月坐吟殘。","莫羨扁舟興，功成去不難。"]', '["離心醉豈懽，把酒彊相寬。","世路須求達，還家亦未安。","旅程愁算远，江月坐吟殘。","莫羨扁舟兴，功成去不难。"]', '诗', 'shi', '', NULL, '秋夕送友人歸吳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e15e5e9-e94f-4881-9429-089ac51b58a5', '長安逢江南僧', '长安逢江南僧', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["孤雲無定蹤，忽到又相逢。","說盡天涯事，聽殘上國鐘。","問人尋寺僻，乞食過街慵。","憶到曾棲處，開門對數峰。"]', '["孤云無定蹤，忽到又相逢。","说尽天涯事，听殘上国鐘。","问人尋寺僻，乞食過街慵。","憶到曾棲处，开门对數峰。"]', '诗', 'shi', '', NULL, '長安逢江南僧 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d7fc04a-f1db-42df-9da0-33e8db1c798c', '晚次修路僧', '晚次修路僧', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["平盡不平處，尚嫌功未深。","應難將世路，便得稱師心。","高鳥下殘照，白煙生遠林。","更聞清磬發，聊喜緩塵襟。"]', '["平尽不平处，尚嫌功未深。","應难將世路，便得稱師心。","高鸟下殘照，白煙生远林。","更闻清磬發，聊喜緩塵襟。"]', '诗', 'shi', '', NULL, '晚次修路僧 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0097f48-d494-4cc4-9c6f-b40719043b14', '湖外送友人遊邊', '湖外送友人游邊', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["我泛瀟湘浦，君行指塞雲。","兩鄉天外隔，一徑渡頭分。","雨暗江花老，笳愁隴月曛。","不堪來去鴈，迢遞思離羣。"]', '["我泛瀟湘浦，君行指塞云。","兩乡天外隔，一徑渡头分。","雨暗江花老，笳愁隴月曛。","不堪来去鴈，迢遞思離羣。"]', '诗', 'shi', '', NULL, '湖外送友人遊邊 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f238165d-617e-499f-abac-797b26b03e4c', '讀段太尉碑', '读段太尉碑', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["憤激計潛成，臨危豈顧生。","秪空持一笏，便欲碎長鯨。","國已酬徽烈，家猶聳義聲。","不知青史上，誰可計功名。"]', '["憤激計潛成，臨危豈顧生。","秪空持一笏，便欲碎长鯨。","国已酬徽烈，家猶聳義声。","不知青史上，誰可計功名。"]', '诗', 'shi', '', NULL, '讀段太尉碑 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79c2ecbb-4e08-4bfe-978e-ed90eaa11275', '夕次洛陽道中', '夕次洛陽道中', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["秋風吹故城，城下獨吟行。","高樹鳥已息，古原人尚耕。","流年川暗度，往事月空明。","不復歎岐路，馬前塵夜生。"]', '["秋风吹故城，城下独吟行。","高樹鸟已息，古原人尚耕。","流年川暗度，往事月空明。","不复歎岐路，马前塵夜生。"]', '诗', 'shi', '', NULL, '夕次洛陽道中 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae49898a-82d5-457e-83cb-3a5555f8036b', '讀方干詩因懷別業', '读方干诗因懷別業', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["把君詩一吟，萬里見君心。","華髮新知少，滄洲舊隱深。","潮衝虛閣上，山入暮窗沈。","憶宿高齋夜，庭枝識海禽。"]', '["把君诗一吟，万里见君心。","华髮新知少，滄洲旧隐深。","潮衝虛閣上，山入暮窗沈。","憶宿高斋夜，庭枝識海禽。"]', '诗', 'shi', '', NULL, '讀方干詩因懷別業 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42fc0ab0-3f65-4651-9fc8-55e0546350a6', '題嵩陽隱者', '題嵩陽隐者', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["四十年高夢，生涯指一丘。","無人同久住，有鶴對冥修。","草雜芝田出，泉和石髓流。","更嫌庭樹老，疑是世間秋。"]', '["四十年高梦，生涯指一丘。","無人同久住，有鹤对冥修。","草杂芝田出，泉和石髓流。","更嫌庭樹老，疑是世间秋。"]', '诗', 'shi', '', NULL, '題嵩陽隱者 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0b4b5a-3d40-49f6-98ef-b19a32dd0fc1', '友人問卜見招', '友人问卜见招', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["何必問蓍龜，行藏自可期。","但逢公道日，即是命通時。","樂善知無厭，操心幸不欺。","豈能花下淚，長似去年垂。"]', '["何必问蓍龟，行藏自可期。","但逢公道日，即是命通时。","乐善知無厭，操心幸不欺。","豈能花下泪，长似去年垂。"]', '诗', 'shi', '', NULL, '友人問卜見招 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f6327e-f4ff-4113-8733-968532b2c994', '江行晚望', '江行晚望', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["木落曙江晴，寒郊極望平。","孤舟三楚去，萬里獨吟行。","鳥占橫查立，人當故里耕。","十年來復去，不覺二毛生。"]', '["木落曙江晴，寒郊極望平。","孤舟三楚去，万里独吟行。","鸟占橫查立，人當故里耕。","十年来复去，不覺二毛生。"]', '诗', 'shi', '', NULL, '江行晚望 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be1bfc4-d05a-4dd6-b41b-e596fb8d0912', '巫山廟', '巫山廟', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["雙黛儼如嚬，應傷故國春。","江山非舊主，雲雨是前身。","夢覺傳詞客，靈猶福楚人。"]', '["雙黛儼如嚬，應傷故国春。","江山非旧主，云雨是前身。","梦覺傳词客，靈猶福楚人。"]', '诗', 'shi', '', NULL, '巫山廟 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce22705-20bd-4ae7-84de-a8d7dea5406c', '秋夕與友人話別', '秋夕與友人話別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["懷君非一夕，此夕倍堪悲。","華髮猶漂泊，滄洲又別離。","冷禽棲不定，衰葉墮無時。","況值干戈隔，相逢未可期。"]', '["懷君非一夕，此夕倍堪悲。","华髮猶漂泊，滄洲又別離。","冷禽棲不定，衰葉墮無时。","況值干戈隔，相逢未可期。"]', '诗', 'shi', '', NULL, '秋夕與友人話別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da01ed4-0663-4719-8104-dc0fe29a54cc', '與友人同懷江南別業', '與友人同懷江南別業', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["因君話故國，此夕倍依依。","舊業臨秋水，何人在釣磯。","浮名如縱得，滄海亦終歸。","却是風塵裏，如何便息機。"]', '["因君話故国，此夕倍依依。","旧業臨秋水，何人在釣磯。","浮名如縱得，滄海亦終归。","却是风塵裏，如何便息機。"]', '诗', 'shi', '', NULL, '與友人同懷江南別業 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cf692c-8cf8-4c1e-8792-e225f78e21ed', '苦吟', '苦吟', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["朝吟復暮吟，只此望知音。","舉世輕孤立，何人念苦心。","他鄉無舊識，落日羨歸禽。","況住寒江上，漁家似故林。"]', '["朝吟复暮吟，只此望知音。","舉世轻孤立，何人念苦心。","他乡無旧識，落日羨归禽。","況住寒江上，漁家似故林。"]', '诗', 'shi', '', NULL, '苦吟 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bd6f86-5b79-4db5-8193-f5c5d9a00500', '春日郊居酬友人見貽', '春日郊居酬友人见貽', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["荒齋原上掩，不出動經旬。","忽覺草木變，始知天地春。","方期五字達，未厭一簞貧。","麗句勞相勉，余非樂釣綸。"]', '["荒斋原上掩，不出动經旬。","忽覺草木变，始知天地春。","方期五字達，未厭一簞貧。","丽句勞相勉，余非乐釣綸。"]', '诗', 'shi', '', NULL, '春日郊居酬友人見貽 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145c084e-4428-458d-88ea-45e4a9802521', '問卜', '问卜', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["承家望一名，幾欲問君平。","自小非無志，何年即有成。","豈能長失路，爭忍學歸耕。","不擬逢昭代，悠悠過此生。"]', '["承家望一名，幾欲问君平。","自小非無志，何年即有成。","豈能长失路，爭忍学归耕。","不擬逢昭代，悠悠過此生。"]', '诗', 'shi', '', NULL, '問卜 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78da2e02-38d6-41d5-97f5-0f1d0baa3d64', '蜀城春', '蜀城春', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["天涯憔悴身，一望一霑巾。","在處有芳草，滿城無故人。","懷才皆得路，失計自傷春。","清鏡不能照，鬢毛愁更新。"]', '["天涯憔悴身，一望一霑巾。","在处有芳草，满城無故人。","懷才皆得路，失計自傷春。","清镜不能照，鬢毛愁更新。"]', '诗', 'shi', '', NULL, '蜀城春 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b6a16bc-67e1-41ed-a1d6-7f60da051ac6', '送道士于千齡游南岳', '送道士于千齡游南岳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["物外與誰期，人間又別離。","四方多事日，高岳獨游時。","猨狖瀟湘樹，煙波屈宋祠。","無因陪此去，空惜鬢將衰。"]', '["物外與誰期，人间又別離。","四方多事日，高岳独游时。","猨狖瀟湘樹，煙波屈宋祠。","無因陪此去，空惜鬢將衰。"]', '诗', 'shi', '', NULL, '送道士于千齡游南岳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cf09977-fdd7-4887-9a53-5a2062731b58', '入蜀赴舉秋夜與先生話別', '入蜀赴舉秋夜與先生話別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["欲愴峨嵋別，中宵寢不能。","聽殘池上雨，吟盡枕前燈。","失計方期隱，修心未到僧。","雲門一萬里，應笑又擔簦。"]', '["欲愴峨嵋別，中宵寢不能。","听殘池上雨，吟尽枕前灯。","失計方期隐，修心未到僧。","云门一万里，應笑又擔簦。"]', '诗', 'shi', '', NULL, '入蜀赴舉秋夜與先生話別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31532d72-a2b9-4637-b029-ff108bb59228', '春晚懷進士韋澹', '春晚懷進士韋澹', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["故里花應盡，江樓夢尚殘。","半生吟欲過，一命達何難。","特立珪無玷，相思草有蘭。","二年春悵望，不似在長安。"]', '["故里花應尽，江楼梦尚殘。","半生吟欲過，一命達何难。","特立珪無玷，相思草有蘭。","二年春悵望，不似在长安。"]', '诗', 'shi', '', NULL, '春晚懷進士韋澹 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b85418a6-17d9-4b3b-b7f8-0cb1f907cadc', '言懷', '言懷', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["干時雖苦節，趨世且無機。","及覺知音少，翻疑所業非。","青雲如不到，白首亦難歸。","所以滄江上，年年別釣磯。"]', '["干时雖苦節，趨世且無機。","及覺知音少，翻疑所業非。","青云如不到，白首亦难归。","所以滄江上，年年別釣磯。"]', '诗', 'shi', '', NULL, '言懷 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0945906d-3734-4661-a9fb-f9e923217761', '秋夜興上人別', '秋夜兴上人別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["常時豈不別，此別異常情。","南國初聞鴈，中原未息兵。","暗蛩侵語歇，疎磬入吟清。","曾聽無生說，辭師話此行。"]', '["常时豈不別，此別異常情。","南国初闻鴈，中原未息兵。","暗蛩侵語歇，疎磬入吟清。","曾听無生说，辞師話此行。"]', '诗', 'shi', '', NULL, '秋夜興上人別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dea0929-dffd-40cf-9361-1f0e00bf8212', '感花', '感花', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["繡軛香韉夜不歸，少年爭惜最紅枝。","東風一陣黃昏雨，又到繁華夢覺時。"]', '["繡軛香韉夜不归，少年爭惜最紅枝。","东风一陣黄昏雨，又到繁华梦覺时。"]', '诗', 'shi', '', NULL, '感花 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b0c3a7-e2c2-4427-aa53-e7e29e0d0b4b', '秋宿天彭僧舍', '秋宿天彭僧舍', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["身世兩相惜，秋雲每獨興。","難將塵界事，話向雪山僧。","力善知誰許，歸耕又未能。","此懷平不得，挑盡草堂燈。"]', '["身世兩相惜，秋云每独兴。","难將塵界事，話向雪山僧。","力善知誰許，归耕又未能。","此懷平不得，挑尽草堂灯。"]', '诗', 'shi', '', NULL, '秋宿天彭僧舍 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b03d28c4-7dd4-4f68-afa3-decc4bebb1ab', '秋夜僧舍聞猨', '秋夜僧舍闻猨', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["哀猨聽未休，禪景夜方幽。","暫得同僧靜，那能免客愁。","影搖雲外樹，聲褭月中秋。","曾向巴江宿，當時淚亦流。"]', '["哀猨听未休，禪景夜方幽。","暫得同僧静，那能免客愁。","影搖云外樹，声褭月中秋。","曾向巴江宿，當时泪亦流。"]', '诗', 'shi', '', NULL, '秋夜僧舍聞猨 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b408736b-d72f-4619-9fd4-f6b03755b432', '過昭君故宅', '過昭君故宅', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["以色靜胡塵，名還異衆嬪。","免勞征戰力，無愧綺羅身。","骨竟埋青塚，魂應怨畫人。","不堪逢舊宅，寥落對江濱。"]', '["以色静胡塵，名還異衆嬪。","免勞征戰力，無愧綺羅身。","骨竟埋青塚，魂應怨畫人。","不堪逢旧宅，寥落对江濱。"]', '诗', 'shi', '', NULL, '過昭君故宅 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e31dcea2-2d4a-47d5-83c0-18bc1a1819a3', '過洛陽故城', '過洛陽故城', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["三十世皇都，蕭條是霸圖。","片墻看破盡，遺跡漸應無。","野徑通荒苑，高槐映遠衢。","獨吟人不問，清冷自嗚嗚。"]', '["三十世皇都，蕭條是霸圖。","片墻看破尽，遺跡漸應無。","野徑通荒苑，高槐映远衢。","独吟人不问，清冷自嗚嗚。"]', '诗', 'shi', '', NULL, '過洛陽故城 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df49da5f-bd2d-4b39-9221-0faecbba8b46', '秋夕與友人同會', '秋夕與友人同會', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["章句積微功，星霜二十空。","僻應如我少，吟喜得君同。","月上僧歸後，詩成客夢中。","更聞棲鶴警，清露滴青松。"]', '["章句積微功，星霜二十空。","僻應如我少，吟喜得君同。","月上僧归後，诗成客梦中。","更闻棲鹤警，清露滴青松。"]', '诗', 'shi', '', NULL, '秋夕與友人同會 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ab68f44-fe46-4317-ad9f-5c8d3db9e900', '春日登吳門', '春日登吳门', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["故國望不見，愁襟難暫開。","春潮映楊柳，細雨入樓臺。","靜少人同到，晴逢鴈正來。","長安遠於日，搔首獨徘徊。"]', '["故国望不见，愁襟难暫开。","春潮映楊柳，細雨入楼台。","静少人同到，晴逢鴈正来。","长安远於日，搔首独徘徊。"]', '诗', 'shi', '', NULL, '春日登吳門 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('767a855e-d581-424e-a016-d99328580238', '湘中秋懷遷客', '湘中秋懷遷客', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["蘭杜曉香薄，汀洲夕露繁。","併聞燕塞鴈，獨立楚人村。","霧散孤城上，灘迴曙枕喧。","不堪逢賈傅，還欲弔湘沅。"]', '["蘭杜晓香薄，汀洲夕露繁。","併闻燕塞鴈，独立楚人村。","霧散孤城上，灘迴曙枕喧。","不堪逢賈傅，還欲弔湘沅。"]', '诗', 'shi', '', NULL, '湘中秋懷遷客 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35a30de2-c57e-4a79-a4c5-a51ada6709a9', '南山旅舍與故人別', '南山旅舍與故人別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["一日又將暮，一年看即殘。","病知新事少，老別舊交難。","山盡路猶險，雨餘春却寒。","那堪試迴首，烽火是長安。"]', '["一日又將暮，一年看即殘。","病知新事少，老別旧交难。","山尽路猶險，雨餘春却寒。","那堪試迴首，烽火是长安。"]', '诗', 'shi', '', NULL, '南山旅舍與故人別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ec64a5-3de4-4137-b9a6-eaee895afc4a', '東林愿禪師院', '东林愿禪師院', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["與世漸無緣，身心獨了然。","講銷林下日，臘長定中年。","磬絕朝齋後，香焚古寺前。","非因送小朗，不到虎谿邊。"]', '["與世漸無緣，身心独了然。","講銷林下日，臘长定中年。","磬絕朝斋後，香焚古寺前。","非因送小朗，不到虎谿邊。"]', '诗', 'shi', '', NULL, '東林愿禪師院 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45aca44a-f366-4f97-b2ac-1a8581a57d39', '孤鴈 一', '孤鴈 一', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["湘浦離應晚，邊城去已孤。","如何萬里計，只在一枝蘆。","迥起波搖楚，寒棲月映蒲。"]', '["湘浦離應晚，邊城去已孤。","如何万里計，只在一枝蘆。","迥起波搖楚，寒棲月映蒲。"]', '诗', 'shi', '', NULL, '孤鴈 一 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c836e52f-2346-4a3e-84bb-97514b17faf6', '孤鴈 二', '孤鴈 二', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["幾行歸去盡，片影獨何之。","暮雨相呼失，寒塘獨下遲。","渚雲低暗度，關月冷遙隨。","未必逢矰繳，孤飛自可疑。"]', '["幾行归去尽，片影独何之。","暮雨相呼失，寒塘独下遲。","渚云低暗度，关月冷遙隨。","未必逢矰繳，孤飞自可疑。"]', '诗', 'shi', '', NULL, '孤鴈 二 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a24cec6-4f9f-47a5-b17e-b702f4a11ef0', '寄青城山颢禪師', '寄青城山颢禪師', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["懷師不可攀，師往杳冥間。","林下誰聞法，塵中只見山。","終年人不到，盡日鳥空還。","曾聽無生說，應憐獨未還。"]', '["懷師不可攀，師往杳冥间。","林下誰闻法，塵中只见山。","終年人不到，尽日鸟空還。","曾听無生说，應怜独未還。"]', '诗', 'shi', '', NULL, '寄青城山颢禪師 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af0eb744-9295-4b03-818b-06139b92af84', '秋夕與王處士話別', '秋夕與王处士話別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["微燈照寂寥，此夕正迢迢。","丹桂得已晚，故山歸尚遙。","蟲聲移暗壁，月色動寒條。","此去如真隱，期君試一瓢。"]', '["微灯照寂寥，此夕正迢迢。","丹桂得已晚，故山归尚遙。","蟲声移暗壁，月色动寒條。","此去如真隐，期君試一瓢。"]', '诗', 'shi', '', NULL, '秋夕與王處士話別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0681ee53-6856-453b-afb3-b2ed911f6745', '秋日犍爲道中', '秋日犍爲道中', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["久客厭岐路，出門吟且悲。","平生未到處，落日獨行時。","芳草不長綠，故人無重期。","那堪更南渡，鄉國已天涯。"]', '["久客厭岐路，出门吟且悲。","平生未到处，落日独行时。","芳草不长綠，故人無重期。","那堪更南渡，乡国已天涯。"]', '诗', 'shi', '', NULL, '秋日犍爲道中 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77cb8bc-263c-4042-9615-480715b043bd', '送僧歸江東', '送僧归江东', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["坐徹秦城夏，行登越客船。","去留那有著，語默不離禪。","葉擁臨關路，霞明近海天。","更尋同社侶，應得虎溪邊。"]', '["坐徹秦城夏，行登越客船。","去留那有著，語默不離禪。","葉擁臨关路，霞明近海天。","更尋同社侶，應得虎溪邊。"]', '诗', 'shi', '', NULL, '送僧歸江東 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d6fdcf-4db3-4604-b278-d1dc60bf5ce7', '喜友人及第', '喜友人及第', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["孤吟望至公，已老半生中。","不有同人達，兼疑此道窮。","只應才自薄，豈是命難通。","尚激摶溟勢，期君借北風。"]', '["孤吟望至公，已老半生中。","不有同人達，兼疑此道窮。","只應才自薄，豈是命难通。","尚激摶溟勢，期君借北风。"]', '诗', 'shi', '', NULL, '喜友人及第 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11f62453-4078-4079-9ee7-da3ef4f4f4e7', '上巳日永崇里言懷', '上巳日永崇里言懷', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["未敢分明賞物華，十年如見夢中花。","遊人過盡衡門掩，獨自凭欄到日斜。"]', '["未敢分明賞物华，十年如见梦中花。","游人過尽衡门掩，独自凭欄到日斜。"]', '诗', 'shi', '', NULL, '上巳日永崇里言懷 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb8619f-07ea-49ad-9056-11036bbec986', '送僧歸天竺', '送僧归天竺', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["忽憶曾棲處，千峰近沃州。","別來秦樹老，歸去海門秋。","汲帶寒汀月，禪隣賈客舟。","遙思清興愜，不厭石林幽。"]', '["忽憶曾棲处，千峰近沃州。","別来秦樹老，归去海门秋。","汲带寒汀月，禪隣賈客舟。","遙思清兴愜，不厭石林幽。"]', '诗', 'shi', '', NULL, '送僧歸天竺 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470cf59b-dd76-4114-92b7-ff49731d254b', '牛渚夜泊', '牛渚夜泊', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["煙老石磯平，袁郎夜泛情。","數吟人不遇，千古月空明。","人事年年別，春潮日日生。","無因逢謝尚，風物自淒清。"]', '["煙老石磯平，袁郎夜泛情。","數吟人不遇，千古月空明。","人事年年別，春潮日日生。","無因逢謝尚，风物自淒清。"]', '诗', 'shi', '', NULL, '牛渚夜泊 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcfa77d3-26e9-4c9c-b765-02d69f7361c2', '送友人歸江南', '送友人归江南', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["渚田芳草徧，共憶故山春。","獨往滄洲暮，相看白髮新。","定過林下寺，應見社中人。","只恐東歸後，難將鷗鳥親。"]', '["渚田芳草徧，共憶故山春。","独往滄洲暮，相看白髮新。","定過林下寺，應见社中人。","只恐东归後，难將鷗鸟親。"]', '诗', 'shi', '', NULL, '送友人歸江南 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6a2c65-035c-43b3-b608-760c5895f454', '過陶徵君隱居', '過陶徵君隐居', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["陶令昔居此，弄琴遺世榮。","田園三畝綠，軒冕一銖輕。","衰柳自無主，白雲猶可耕。","不隨陵谷變，應只有高名。"]', '["陶令昔居此，弄琴遺世榮。","田园三畝綠，軒冕一銖轻。","衰柳自無主，白云猶可耕。","不隨陵谷变，應只有高名。"]', '诗', 'shi', '', NULL, '過陶徵君隱居 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a30c61d-6603-4070-8ad9-04adefcb36bf', '江上旅泊', '江上旅泊', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["汀洲一夜泊，久客半連檣。","盡說逢秋色，多同憶故鄉。","孤岡生晚燒，獨樹隱回塘。","欲問東歸路，遙知隔渺茫。"]', '["汀洲一夜泊，久客半連檣。","尽说逢秋色，多同憶故乡。","孤岡生晚燒，独樹隐回塘。","欲问东归路，遙知隔渺茫。"]', '诗', 'shi', '', NULL, '江上旅泊 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da97811-c1b4-4496-b6a5-76170faef6a5', '灞上', '灞上', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["長安名利路，役役古田今。","征騎少閑日，綠楊無舊陰。","水侵秦甸闊，草接漢陵深。","紫閣曾過處，依稀白鳥沈。"]', '["长安名利路，役役古田今。","征騎少闲日，綠楊無旧陰。","水侵秦甸闊，草接漢陵深。","紫閣曾過处，依稀白鸟沈。"]', '诗', 'shi', '', NULL, '灞上 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f6cf04-a977-4107-a788-5bafdd7ae14c', '寄舅', '寄舅', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["中朝軒冕內，久絕甯家親。","白社同孤立，青雲獨併伸。","致君期折檻，舉職在埋輪。","須信堯庭草，猶能指佞人。"]', '["中朝軒冕內，久絕甯家親。","白社同孤立，青云独併伸。","致君期折檻，舉職在埋輪。","須信堯庭草，猶能指佞人。"]', '诗', 'shi', '', NULL, '寄舅 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd6b1e5-17e3-49cf-86e7-eb1a769ce36d', '贈休糧僧', '贈休糧僧', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["聞鐘獨不齋，何事更關懷。","靜少人過院，閑從草上堦。","生臺無鳥下，石路有雲埋。","爲憶禪中舊，時猶夢百崖。"]', '["闻鐘独不斋，何事更关懷。","静少人過院，闲從草上堦。","生台無鸟下，石路有云埋。","爲憶禪中旧，时猶梦百崖。"]', '诗', 'shi', '', NULL, '贈休糧僧 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4babb757-d44d-42a7-b88a-5f98393d7e24', '題絕島山寺', '題絕島山寺', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["絕島跨危欄，登臨到此難。","夕陽高鳥過，疎雨一鐘殘。","駭浪搖空闊，靈山厭渺漫。","那堪更回首，鄉樹隔雲端。"]', '["絕島跨危欄，登臨到此难。","夕陽高鸟過，疎雨一鐘殘。","駭浪搖空闊，靈山厭渺漫。","那堪更回首，乡樹隔云端。"]', '诗', 'shi', '', NULL, '題絕島山寺 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7520d77e-233f-4367-9f09-a89aaa4af120', '讀侯道華真人傳', '读侯道华真人傳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["漢皇輕萬乘，方士說三丹。","不得修心要，翻知出世難。","茂陵春竟綠，金掌曙空寒。","何似先生去，翩翩逐彩鸞。"]', '["漢皇轻万乘，方士说三丹。","不得修心要，翻知出世难。","茂陵春竟綠，金掌曙空寒。","何似先生去，翩翩逐彩鸾。"]', '诗', 'shi', '', NULL, '讀侯道華真人傳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41dcc72d-ee84-4019-b9d1-2dfcb374ae93', '殘花', '殘花', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["遲遲傍曉陰，昨夜色猶深。","畢竟終須落，堪悲古與今。","明年何處見，盡日此時心。","蜂蝶無情極，殘香更不尋。"]', '["遲遲傍晓陰，昨夜色猶深。","畢竟終須落，堪悲古與今。","明年何处见，尽日此时心。","蜂蝶無情極，殘香更不尋。"]', '诗', 'shi', '', NULL, '殘花 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2ac2ea-673b-4d01-8b0e-e6e182bf4f1b', '題興善寺隋松院與人期不至', '題兴善寺隋松院與人期不至', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["青青伊澗松，移植在蓮宮。","蘚色前朝雨，秋聲半夜風。","長閑應未得，暫賞亦難同。","不及禪棲者，相看老此中。"]', '["青青伊澗松，移植在蓮宮。","蘚色前朝雨，秋声半夜风。","长闲應未得，暫賞亦难同。","不及禪棲者，相看老此中。"]', '诗', 'shi', '', NULL, '題興善寺隋松院與人期不至 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e828f50-094c-432c-a727-872eb3143101', '樵者', '樵者', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["行山行採薇，閑翦蕙爲衣。","避世嫌山淺，逢人說姓稀。","有時還獨醉，何處掩衡扉？","莫看棋終局，溪風晚待歸。"]', '["行山行採薇，闲翦蕙爲衣。","避世嫌山淺，逢人说姓稀。","有时還独醉，何处掩衡扉？","莫看棋終局，溪风晚待归。"]', '诗', 'shi', '', NULL, '樵者 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33164e3-64ca-43f3-a829-0675cb105595', '南澗耕叟', '南澗耕叟', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["年年南澗濱，力盡志猶存。","雨雪朝耕苦，桑麻歲計貧。","戰添丁壯役，老憶太平春。","見說經荒後，田園半屬人。"]', '["年年南澗濱，力尽志猶存。","雨雪朝耕苦，桑麻歲計貧。","戰添丁壯役，老憶太平春。","见说經荒後，田园半屬人。"]', '诗', 'shi', '', NULL, '南澗耕叟 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7163d43-99ac-4fee-80c3-f597f1dcc6b7', '春日閑居憶江南舊業', '春日闲居憶江南旧業', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["杜門朝復夕，豈是解謀身。","夢不離泉石，林唯稱隱淪。","漸諳浮世事，轉憶故山春。","南國水風暖，又應生白蘋。"]', '["杜门朝复夕，豈是解謀身。","梦不離泉石，林唯稱隐淪。","漸諳浮世事，轉憶故山春。","南国水风暖，又應生白蘋。"]', '诗', 'shi', '', NULL, '春日閑居憶江南舊業 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e101eab1-9e6c-46c8-a3d9-27531f821293', '屈原廟', '屈原廟', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["讒勝禍難防，沈冤信可傷。","本圖安楚國，不是怨懷王。","廟古碑無字，洲晴蕙有香。","獨醒人尚笑，誰與奠椒漿。"]', '["讒勝禍难防，沈冤信可傷。","本圖安楚国，不是怨懷王。","廟古碑無字，洲晴蕙有香。","独醒人尚笑，誰與奠椒漿。"]', '诗', 'shi', '', NULL, '屈原廟 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10023796-9225-452d-8f14-65a3b0ccf9ad', '宿廬山絕頂山舍', '宿廬山絕頂山舍', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["一磴出林端，千峰次第看。","長閑如未遂，暫到亦應難。","谷樹雲埋老，僧窗瀑影寒。","自嫌心不達，向此夢長安。"]', '["一磴出林端，千峰次第看。","长闲如未遂，暫到亦應难。","谷樹云埋老，僧窗瀑影寒。","自嫌心不達，向此梦长安。"]', '诗', 'shi', '', NULL, '宿廬山絕頂山舍 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4eb8b07-e96e-478a-b9b4-f9402669bab7', '王逸人隱居', '王逸人隐居', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["一徑入千岑，幽人許重尋。","不逢秦世亂，未覺武陵深。","石轉生寒色，雲歸帶夕陰。","却愁危坐久，看盡暝棲禽。"]', '["一徑入千岑，幽人許重尋。","不逢秦世亂，未覺武陵深。","石轉生寒色，云归带夕陰。","却愁危坐久，看尽暝棲禽。"]', '诗', 'shi', '', NULL, '王逸人隱居 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba010328-07c5-4e6c-83ff-2f5bafdafd3d', '申州道中', '申州道中', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["風緊日淒淒，鄉心向此迷。","水分平楚闊，山接故關低。","客路緣烽火，人家厭鼓鼙。","那堪獨馳馬，江樹穆陵西。"]', '["风緊日淒淒，乡心向此迷。","水分平楚闊，山接故关低。","客路緣烽火，人家厭鼓鼙。","那堪独驰马，江樹穆陵西。"]', '诗', 'shi', '', NULL, '申州道中 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b82932-a1c5-4791-a8f1-0743f1c1d61b', '江上懷翠微寺空上人', '江上懷翠微寺空上人', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["旅泛本無定，相逢那可期。","空懷白閣夜，未荅碧雲詩。","暮雨潮生早，春寒鴈到遲。","所思今不見，鄉國正天涯。"]', '["旅泛本無定，相逢那可期。","空懷白閣夜，未荅碧云诗。","暮雨潮生早，春寒鴈到遲。","所思今不见，乡国正天涯。"]', '诗', 'shi', '', NULL, '江上懷翠微寺空上人 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd7bdd89-da7b-496b-b8c0-8a4119702a5d', '秋宿鶴林寺', '秋宿鹤林寺', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["步步入林中，山窮意未窮。","偏逢僧話久，轉與鶴棲同。","燭焰風銷盡，蘭條露濕空。","又須從此別，江上正秋鴻。"]', '["步步入林中，山窮意未窮。","偏逢僧話久，轉與鹤棲同。","燭焰风銷尽，蘭條露濕空。","又須從此別，江上正秋鴻。"]', '诗', 'shi', '', NULL, '秋宿鶴林寺 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682909dd-b9df-4666-b88a-1824fd167ffc', '遠望', '远望', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["長爲鄉思侵，望極即霑襟。","不是前山色，能傷愁客心。","平蕪連海盡，獨樹隱雲深。","況復斜陽外，分明有去禽。"]', '["长爲乡思侵，望極即霑襟。","不是前山色，能傷愁客心。","平蕪連海尽，独樹隐云深。","況复斜陽外，分明有去禽。"]', '诗', 'shi', '', NULL, '遠望 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d693b670-78ab-4b3f-b851-0875e9229739', '秋晚書懷', '秋晚书懷', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["看看秋色晚，又是出門時。","白髮生非早，青雲去自遲。","夢唯懷上國，跡不到他岐。","以此堅吾道，還無媿已知。"]', '["看看秋色晚，又是出门时。","白髮生非早，青云去自遲。","梦唯懷上国，跡不到他岐。","以此堅吾道，還無媿已知。"]', '诗', 'shi', '', NULL, '秋晚書懷 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90b9759a-9ba7-4b41-b457-de1b5245cd03', '途中秋晚送友人歸江南', '途中秋晚送友人归江南', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["又指煙波算路岐，此生多是厭羇離。","正逢搖落仍須別，不待登臨已合悲。","里巷半空兵過後，水雲初冷鴈來時。","扁舟未得如君去，空向滄江夢所思。"]', '["又指煙波算路岐，此生多是厭羇離。","正逢搖落仍須別，不待登臨已合悲。","里巷半空兵過後，水云初冷鴈来时。","扁舟未得如君去，空向滄江梦所思。"]', '诗', 'shi', '', NULL, '途中秋晚送友人歸江南 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15cb3d75-36b7-4707-b201-9caae039b327', '己亥歲感事', '己亥歲感事', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["正聞青犢起葭萌，又報黃巾犯漢營。","豈是將皆無上略，直疑天自棄蒼生。","瓜沙舊戍猶傳檄，吳楚新春已廢耕。","見說聖君能仄席，不知誰是請長纓。"]', '["正闻青犢起葭萌，又報黄巾犯漢營。","豈是將皆無上略，直疑天自棄蒼生。","瓜沙旧戍猶傳檄，吳楚新春已廢耕。","见说聖君能仄席，不知誰是請长纓。"]', '诗', 'shi', '', NULL, '己亥歲感事 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0eb2d0-eb15-4e0d-a02b-bd4a212f0cae', '金陵晚眺', '金陵晚眺', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["葦聲騷屑水天秋，吟對金陵古渡頭。","千古是非輸蝶夢，一輪風雨屬漁舟。","若無仙分應須老，幸有歸山即合休。","何必登臨更惆悵，比來身世只如浮。"]', '["葦声騷屑水天秋，吟对金陵古渡头。","千古是非輸蝶梦，一輪风雨屬漁舟。","若無仙分應須老，幸有归山即合休。","何必登臨更惆悵，比来身世只如浮。"]', '诗', 'shi', '', NULL, '金陵晚眺 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05358d91-44b7-4a9d-afd2-9614680fa5d8', '過長江賈島主簿舊廳', '過长江賈島主簿旧廳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["雕琢文章字字精，我經此處倍傷情。","身從謫宦方霑祿，才被槌埋更有聲。","過縣已無曾識吏，到廳空見舊題名。","長江一曲年年水，應爲先生萬古清。"]', '["雕琢文章字字精，我經此处倍傷情。","身從謫宦方霑祿，才被槌埋更有声。","過縣已無曾識吏，到廳空见旧題名。","长江一曲年年水，應爲先生万古清。"]', '诗', 'shi', '', NULL, '過長江賈島主簿舊廳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70bf0a2b-3276-46c6-aa9c-68e0962c0c9b', '途中感懷寄青城李明府', '途中感懷寄青城李明府', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["鱗鬣催殘志未休，壯心飜是此身讐。","併聞寒雨多因夜，不得鄉書又到秋。","耕釣舊交吟好憶，雪霜危棧去堪愁。","如何只是三年別，君著朱衣我白頭。"]', '["鱗鬣催殘志未休，壯心飜是此身讐。","併闻寒雨多因夜，不得乡书又到秋。","耕釣旧交吟好憶，雪霜危棧去堪愁。","如何只是三年別，君著朱衣我白头。"]', '诗', 'shi', '', NULL, '途中感懷寄青城李明府 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('121192f9-8b5f-43b7-a720-3ca9ad510a9a', '夏日書懷寄道友', '夏日书懷寄道友', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["達即匡邦退即耕，是非何足撓平生。","終期道向希夷得，未省心因寵辱驚。","峰轉暫無當戶影，雉飛時有隔林聲。","十年惟悟吟詩句，待得中原欲鑄兵。"]', '["達即匡邦退即耕，是非何足撓平生。","終期道向希夷得，未省心因寵辱驚。","峰轉暫無當戶影，雉飞时有隔林声。","十年惟悟吟诗句，待得中原欲鑄兵。"]', '诗', 'shi', '', NULL, '夏日書懷寄道友 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0755669-f89d-4318-a111-450bc347a181', '和進士張曙聞鴈見寄', '和進士張曙闻鴈见寄', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["斷行哀響遞相催，爭趁高秋作恨媒。","雲外關山聞獨去，渡頭風雨見初來。","也知榆塞寒須別，莫戀蘋汀暖不迴。","試向富春江畔過，故園猶合有池臺。"]', '["斷行哀响遞相催，爭趁高秋作恨媒。","云外关山闻独去，渡头风雨见初来。","也知榆塞寒須別，莫戀蘋汀暖不迴。","試向富春江畔過，故园猶合有池台。"]', '诗', 'shi', '', NULL, '和進士張曙聞鴈見寄 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('337330c6-3aa1-4214-934a-44e3b20f5cd4', '鸚鵡洲即事', '鸚鵡洲即事', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["悵望春襟鬱未開，重吟鸚鵡益堪哀。","曹瞞尚不能容物，黃祖何曾解愛才。","幽島暖聞燕鴈去，曉江晴覺蜀波來。","何人正得風濤便，一點輕帆萬里迴。"]', '["悵望春襟鬱未开，重吟鸚鵡益堪哀。","曹瞞尚不能容物，黄祖何曾解愛才。","幽島暖闻燕鴈去，晓江晴覺蜀波来。","何人正得风濤便，一点轻帆万里迴。"]', '诗', 'shi', '', NULL, '鸚鵡洲即事 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd52052-facd-4990-a7d4-0d247c80e20a', '讀留侯傳', '读留侯傳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["覆楚讐韓勢有餘，男兒遭遇更難如。","偶成漢室千年業，只讀圯橋一卷書。","翻把壯心輕尺組，却煩商皓正皇儲。","若能終始匡天子，何必□□□□□。"]', '["覆楚讐韓勢有餘，男兒遭遇更难如。","偶成漢室千年業，只读圯橋一卷书。","翻把壯心轻尺組，却煩商皓正皇儲。","若能終始匡天子，何必□□□□□。"]', '诗', 'shi', '', NULL, '讀留侯傳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('414134d3-a4e7-414b-83fa-a63b719d3671', '赤壁懷古', '赤壁懷古', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["漢室河山鼎勢分，勤王誰肯顧元勳。","不知征伐由天子，唯許英雄共使君。","江上戰餘陵是谷，渡頭春在草連雲。","分明勝敗無尋處，空聽漁歌到夕曛。"]', '["漢室河山鼎勢分，勤王誰肯顧元勳。","不知征伐由天子，唯許英雄共使君。","江上戰餘陵是谷，渡头春在草連云。","分明勝敗無尋处，空听漁歌到夕曛。"]', '诗', 'shi', '', NULL, '赤壁懷古 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce0da344-799e-4078-8fb3-de84bc7d9d28', '東晉 一', '东晉 一', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["五陵豪俠笑爲儒，將爲儒生只讀書。","看取不成投筆後，謝安功業復何如。"]', '["五陵豪俠笑爲儒，將爲儒生只读书。","看取不成投笔後，謝安功業复何如。"]', '诗', 'shi', '', NULL, '東晉 一 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a430b3dd-bfa4-4d20-96d4-365470d53e39', '東晉 二', '东晉 二', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["秦國金陵王氣全，一龍正道始東遷。","興亡竟不關人事，虛倚長淮五百年。"]', '["秦国金陵王氣全，一龙正道始东遷。","兴亡竟不关人事，虛倚长淮五百年。"]', '诗', 'shi', '', NULL, '東晉 二 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8c69c3-6ae6-48ff-bf8c-1e18b0f42133', '春夕', '春夕', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["水流花謝兩無情，送盡東風過楚城。","胡蝶夢中家萬里，子規枝上月三更。","故園書動經年絕，華髮春唯滿鏡生。","自是不歸歸便得，五湖煙景有誰爭。"]', '["水流花謝兩無情，送尽东风過楚城。","胡蝶梦中家万里，子規枝上月三更。","故园书动經年絕，华髮春唯满镜生。","自是不归归便得，五湖煙景有誰爭。"]', '诗', 'shi', '', NULL, '春夕 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb25fca-d489-4c56-926e-09e0f2ea9bbe', '澗松', '澗松', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["寸寸凌霜長勁條，路人猶笑未干霄。","南園桃李雖堪羨，爭奈春殘又寂寥。"]', '["寸寸凌霜长勁條，路人猶笑未干霄。","南园桃李雖堪羨，爭奈春殘又寂寥。"]', '诗', 'shi', '', NULL, '澗松 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a70700-4400-4f4f-9796-0e031d9749da', '湘中弦 一', '湘中弦 一', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["蒼山遙遙江潾潾，路傍老盡沒閑人。","王孫不見草空綠，惆悵渡頭春復春。"]', '["蒼山遙遙江潾潾，路傍老尽沒闲人。","王孫不见草空綠，惆悵渡头春复春。"]', '诗', 'shi', '', NULL, '湘中弦 一 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6e4f97-889c-4ac3-aea8-b7641fefba1b', '湘中弦 二', '湘中弦 二', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["煙愁雨細雲冥冥，杜蘭香老三湘清。","故山望斷不知處，鶗鴂隔花時一聲。"]', '["煙愁雨細云冥冥，杜蘭香老三湘清。","故山望斷不知处，鶗鴂隔花时一声。"]', '诗', 'shi', '', NULL, '湘中弦 二 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16758d7d-ecdc-41b7-a2bc-13bf010bdf9e', '續紀漢武', '續紀漢武', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["分明三鳥下儲胥，一覺鈞天夢不如。","爭那白頭方士到，茂陵紅葉已蕭疎。"]', '["分明三鸟下儲胥，一覺鈞天梦不如。","爭那白头方士到，茂陵紅葉已蕭疎。"]', '诗', 'shi', '', NULL, '續紀漢武 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f733392-8a94-4c3d-8b77-ad595c4a6aa1', '隴上逢江南故人', '隴上逢江南故人', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["三聲戍角邊城暮，萬里鄉心塞草春。","莫學少年輕遠別，隴關西少向東人。"]', '["三声戍角邊城暮，万里乡心塞草春。","莫学少年轻远別，隴关西少向东人。"]', '诗', 'shi', '', NULL, '隴上逢江南故人 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9be2ffa-7287-42e1-923a-01afbd062933', '夷陵夜泊', '夷陵夜泊', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["家依楚塞窮秋別，身逐孤舟萬里行。","一曲巴歌半江月，便應消得二毛生。"]', '["家依楚塞窮秋別，身逐孤舟万里行。","一曲巴歌半江月，便應消得二毛生。"]', '诗', 'shi', '', NULL, '夷陵夜泊 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8da7d9c-3b0d-4943-ab4a-09b38a1cc769', '櫓聲', '櫓声', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["煙外橈聲遠，天涯幽夢迴。","爭知江上客，不是故鄉來。"]', '["煙外橈声远，天涯幽梦迴。","爭知江上客，不是故乡来。"]', '诗', 'shi', '', NULL, '櫓聲 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dfcc935-097a-4706-b15d-eb91f97d44d9', '海棠圖', '海棠圖', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["海棠花底三年客，不見海棠花盛開。","却向江南看圖畫，始慙虛到蜀城來。"]', '["海棠花底三年客，不见海棠花盛开。","却向江南看圖畫，始慙虛到蜀城来。"]', '诗', 'shi', '', NULL, '海棠圖 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a9ee17-c5e9-4444-906e-5bd4073db083', '雲', '云', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["得路直爲霖濟物，不然閑共鶴忘機。","無端却向陽臺畔，長送襄王暮雨歸。"]', '["得路直爲霖濟物，不然闲共鹤忘機。","無端却向陽台畔，长送襄王暮雨归。"]', '诗', 'shi', '', NULL, '雲 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfb4c590-44c7-4f77-9593-edd68a261311', '過二妃廟', '過二妃廟', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["殘陽楚水畔，獨弔舜時人。","不及廟前草，至今江上春。"]', '["殘陽楚水畔，独弔舜时人。","不及廟前草，至今江上春。"]', '诗', 'shi', '', NULL, '過二妃廟 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4953f68b-5357-4d74-a2a7-89d1916ac9ea', '送友人', '送友人', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["登高迎送遠，春恨併依依。","不得滄洲信，空看白鶴歸。"]', '["登高迎送远，春恨併依依。","不得滄洲信，空看白鹤归。"]', '诗', 'shi', '', NULL, '送友人 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b79e1a5-af89-4a58-a673-e98cc8980808', '聲', '声', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["歡戚猶來恨不平，此中高下本無情。","韓娥絕唱唐衢哭，盡是人間第一聲。"]', '["歡戚猶来恨不平，此中高下本無情。","韓娥絕唱唐衢哭，尽是人间第一声。"]', '诗', 'shi', '', NULL, '聲 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('643820d7-50d8-4b43-8474-3db1af060d2a', '放鷓鴣', '放鷓鴣', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["秋入池塘風露微，曉開籠檻看初飛。","滿身金翠畫不得，無限煙波何處歸。"]', '["秋入池塘风露微，晓开籠檻看初飞。","满身金翠畫不得，無限煙波何处归。"]', '诗', 'shi', '', NULL, '放鷓鴣 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00e3b9e-d1b7-41e3-a3fd-f0c95e334f74', '泉', '泉', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["遠辭巖竇瀉潺潺，靜拂雲根別故山。","可惜寒聲留不得，旋添波浪向人間。"]', '["远辞巖竇瀉潺潺，静拂云根別故山。","可惜寒声留不得，旋添波浪向人间。"]', '诗', 'shi', '', NULL, '泉 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b691e895-11ba-4c9c-b788-a140c9e08c0c', '巫山旅別', '巫山旅別', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["五千里外三年客，十二峰前一望秋。","無限別魂招不得，夕陽西下水東流。"]', '["五千里外三年客，十二峰前一望秋。","無限別魂招不得，夕陽西下水东流。"]', '诗', 'shi', '', NULL, '巫山旅別 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ea18b1d-eab4-4f62-bc66-fff4e7b1d76a', '幽蘭', '幽蘭', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["幽植衆寧知，芬芳只暗持。","自無君子佩，未是國香衰。","白露霑長草，春風到每遲。","不如當路草，芬馥欲何爲。"]', '["幽植衆寧知，芬芳只暗持。","自無君子佩，未是国香衰。","白露霑长草，春风到每遲。","不如當路草，芬馥欲何爲。"]', '诗', 'shi', '', NULL, '幽蘭 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7012b44-6953-4ddf-bee7-79b0fc5c6e3b', '讀庾信集', '读庾信集', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["四朝十帝盡風流，建業長安兩醉遊。","唯有一篇楊柳曲，江南江北爲君愁。"]', '["四朝十帝尽风流，建業长安兩醉游。","唯有一篇楊柳曲，江南江北爲君愁。"]', '诗', 'shi', '', NULL, '讀庾信集 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26473a08-45c4-4c1d-aeb0-ef05efd33bdd', '過繡嶺宮', '過繡嶺宮', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["古殿春殘綠野陰，上皇曾此駐泥金。","三城帳屬升平夢，一曲鈴關悵望心。","苑路暗迷香輦絕，繚垣秋斷草煙深。","前朝舊物東流在，猶爲年年下翠岑。"]', '["古殿春殘綠野陰，上皇曾此駐泥金。","三城帳屬升平梦，一曲鈴关悵望心。","苑路暗迷香輦絕，繚垣秋斷草煙深。","前朝旧物东流在，猶爲年年下翠岑。"]', '诗', 'shi', '', NULL, '過繡嶺宮 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d33c118-cde9-49af-b572-c43427a10b48', '巴山道中除夜書懷', '巴山道中除夜书懷', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["迢遰三巴路，羇危萬里身。","亂山殘雪夜，孤燭異鄉春。","漸與骨肉遠，轉於僮僕親。","那堪正漂泊，明日歲華新。"]', '["迢遰三巴路，羇危万里身。","亂山殘雪夜，孤燭異乡春。","漸與骨肉远，轉於僮僕親。","那堪正漂泊，明日歲华新。"]', '诗', 'shi', '', NULL, '巴山道中除夜書懷 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4257ee-1330-4d11-9e10-9a86d065eb19', '題淨衆寺古松', '題淨衆寺古松', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["百尺森疎倚梵臺，昔人誰見此初栽。","故園未有偏堪戀，浮世如閑即合來。","天暝豈分蒼翠色，歲寒應識棟梁材。","清陰可惜不駐得，歸去暮城空首回。"]', '["百尺森疎倚梵台，昔人誰见此初栽。","故园未有偏堪戀，浮世如闲即合来。","天暝豈分蒼翠色，歲寒應識棟梁材。","清陰可惜不駐得，归去暮城空首回。"]', '诗', 'shi', '', NULL, '題淨衆寺古松 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8d2179-8111-4cfe-9abc-d82137e102a7', '折楊柳', '折楊柳', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["朝朝車馬如蓬轉，處處江山待客歸。","若使人間少離別，楊花應合過春飛。"]', '["朝朝车马如蓬轉，处处江山待客归。","若使人间少離別，楊花應合過春飞。"]', '诗', 'shi', '', NULL, '折楊柳 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ddfdf6-b540-4c91-a0c1-53402bd5410b', '七夕', '七夕', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["年年七夕渡瑤軒，誰道秋期有淚痕。","自是人間一週歲，何妨天上只黃昏。"]', '["年年七夕渡瑤軒，誰道秋期有泪痕。","自是人间一週歲，何妨天上只黄昏。"]', '诗', 'shi', '', NULL, '七夕 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5fc74cd-ebe1-45af-9985-a6b7bc495cb9', '泛楚江', '泛楚江', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["九重城外家書遠，百里洲前客棹還。","金印碧幢如見問，一生安穩是長閑。"]', '["九重城外家书远，百里洲前客棹還。","金印碧幢如见问，一生安穩是长闲。"]', '诗', 'shi', '', NULL, '泛楚江 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4ad536f-639a-4dc4-bb1c-aae1d7f34165', '初過漢江', '初過漢江', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["襄陽好向峴亭看，人物蕭條值歲闌。","爲報習家多置酒，夜來風雪過江寒。"]', '["襄陽好向峴亭看，人物蕭條值歲闌。","爲報習家多置酒，夜来风雪過江寒。"]', '诗', 'shi', '', NULL, '初過漢江 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98845b0c-e9b0-4d14-ab8e-bac4354eefce', '題授陽鎮路', '題授陽鎮路', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["越鳥巢邊溪路斷，秦人耕處洞門開。","小桃花發春風起，千里江山一夢回。"]', '["越鸟巢邊溪路斷，秦人耕处洞门开。","小桃花發春风起，千里江山一梦回。"]', '诗', 'shi', '', NULL, '題授陽鎮路 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53773b6d-17a1-469a-8ae3-4ddcaa5acc31', '初識梅花', '初識梅花', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["江北不如南地暖，江南好斷北人腸。","燕脂桃頰棃花粉，共作寒梅一面粧。"]', '["江北不如南地暖，江南好斷北人腸。","燕脂桃頰棃花粉，共作寒梅一面粧。"]', '诗', 'shi', '', NULL, '初識梅花 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d423c1c-664a-44cf-811b-d956a6e4b49f', '江雨望花', '江雨望花', 'd4ff64e6-663b-4294-8c3a-2b5c6234841d', '唐', '["細雨滿江春水漲，好風留客野梅香。","避秦不是無歸意，一度逢花一斷腸。"]', '["細雨满江春水漲，好风留客野梅香。","避秦不是無归意，一度逢花一斷腸。"]', '诗', 'shi', '', NULL, '江雨望花 崔塗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c0bc51-afe4-4edf-9297-4760bb68907b', '雨後月中玉堂閑坐', '雨後月中玉堂闲坐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["銀臺直北金鑾外，暑雨初晴皓月中。","唯對松篁聽刻漏，更無塵土翳虛空。","綠香熨齒冰盤果，清冷侵肌水殿風。","夜久忽聞鈴索動，玉堂西畔響丁東。"]', '["銀台直北金鑾外，暑雨初晴皓月中。","唯对松篁听刻漏，更無塵土翳虛空。","綠香熨齒冰盤果，清冷侵肌水殿风。","夜久忽闻鈴索动，玉堂西畔响丁东。"]', '诗', 'shi', '', NULL, '雨後月中玉堂閑坐 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2e14ca2-a34e-4e44-9d2c-bd584526e3cb', '六月十七日召對自辰及申方歸本院', '六月十七日召对自辰及申方归本院', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["清[暑]簾開散異香，恩深咫尺對龍章。","花應洞裏尋常發，日向壺中特地長。","坐久忽疑槎犯斗，歸來兼恐海生桑。","如今冷笑東方朔，唯用詼諧侍漢皇。"]', '["清[暑]簾开散異香，恩深咫尺对龙章。","花應洞裏尋常發，日向壺中特地长。","坐久忽疑槎犯斗，归来兼恐海生桑。","如今冷笑东方朔，唯用詼諧侍漢皇。"]', '诗', 'shi', '', NULL, '六月十七日召對自辰及申方歸本院 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a284014c-d8b9-4965-9e22-9c3c8b1d024e', '與吳子華侍郎同年玉堂同直懷恩敘懇因成長句四韻兼呈諸同年', '與吳子华侍郎同年玉堂同直懷恩敘懇因成长句四韻兼呈諸同年', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["往年鶯谷接清塵，今日鼇山作侍臣。","二紀計偕勞筆研，一朝宣入掌絲綸。","聲名烜赫文章士，金紫雍容富貴身。","絳帳恩深無路報，語餘相顧却酸辛。"]', '["往年鶯谷接清塵，今日鼇山作侍臣。","二紀計偕勞笔研，一朝宣入掌絲綸。","声名烜赫文章士，金紫雍容富貴身。","絳帳恩深無路報，語餘相顧却酸辛。"]', '诗', 'shi', '', NULL, '與吳子華侍郎同年玉堂同直懷恩敘懇因成長句四韻兼呈諸同年 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63102bb-ba42-4b33-be65-d49aac33a104', '和吳子華侍郎令狐昭化舍人歎白菊衰謝之絕次山本韻', '和吳子华侍郎令狐昭化舍人歎白菊衰謝之絕次山本韻', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["正憐香雪披千片，忽訝殘霞覆一叢。","還似妖姬長年後，酒酣雙臉却微紅。"]', '["正怜香雪披千片，忽訝殘霞覆一叢。","還似妖姬长年後，酒酣雙臉却微紅。"]', '诗', 'shi', '', NULL, '和吳子華侍郎令狐昭化舍人歎白菊衰謝之絕次山本韻 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51b3616-0006-43b0-8db9-5daa895868b0', '中秋禁直', '中秋禁直', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["星斗疎明禁漏殘，紫泥封後獨凭闌。","露和玉屑金盤冷，月射珠光貝闕寒。","天襯樓臺籠苑外，風吹歌管下雲端。","長卿秪爲長門賦，未識君臣際會難。"]', '["星斗疎明禁漏殘，紫泥封後独凭闌。","露和玉屑金盤冷，月射珠光貝闕寒。","天襯楼台籠苑外，风吹歌管下云端。","长卿秪爲长门賦，未識君臣際會难。"]', '诗', 'shi', '', NULL, '中秋禁直 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('965672f8-8e76-4bfa-9ef6-da341f985909', '侍宴', '侍宴', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["蠭黃蝶粉兩依依，狎宴臨春日正遲。","密旨不教江令醉，麗華微笑認皇慈。"]', '["蠭黄蝶粉兩依依，狎宴臨春日正遲。","密旨不教江令醉，丽华微笑認皇慈。"]', '诗', 'shi', '', NULL, '侍宴 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3651949-bfae-4589-ba3b-33eee7f6e77a', '錫宴日作', '錫宴日作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["玉銜花馬蹋香街，詔遣追歡綺席開。","中使押從天上去外人知自日邊來。","臣心淨比漪漣水，聖澤深於瀲灩杯。","纔有異恩頒稷契，已將優禮及鄒枚。","清商適向棃園降，妙妓新行峽雨迴。","不敢通宵離禁直，晚乘殘醉入銀臺。"]', '["玉銜花马蹋香街，詔遣追歡綺席开。","中使押從天上去外人知自日邊来。","臣心淨比漪漣水，聖澤深於瀲灩杯。","纔有異恩頒稷契，已將優禮及鄒枚。","清商適向棃园降，妙妓新行峽雨迴。","不敢通宵離禁直，晚乘殘醉入銀台。"]', '诗', 'shi', '', NULL, '錫宴日作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083229cb-4ef5-4c37-8922-d9abc021d5d8', '宮柳', '宮柳', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["莫道秋來芳意違，宮娃猶似妒蛾眉。","幸當玉輦經過處，不怕金風浩蕩時。","草色長承垂地葉，日華先動映樓枝。","澗松亦有凌雲分，爭似移根太液池。"]', '["莫道秋来芳意違，宮娃猶似妒蛾眉。","幸當玉輦經過处，不怕金风浩蕩时。","草色长承垂地葉，日华先动映楼枝。","澗松亦有凌云分，爭似移根太液池。"]', '诗', 'shi', '', NULL, '宮柳 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2735f18c-b45d-4f53-b83d-1e6db5b4036e', '苑中', '苑中', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["上苑離宮處處迷，相風高與露盤齊。","金階鑄出狻猊立，玉樹雕成狒𤝞啼。","外使調鷹初得按，中官過馬不教嘶。","笙歌錦繡雲霄裏，獨許詞臣醉似泥。"]', '["上苑離宮处处迷，相风高與露盤齊。","金階鑄出狻猊立，玉樹雕成狒𤝞啼。","外使調鷹初得按，中官過马不教嘶。","笙歌錦繡云霄裏，独許词臣醉似泥。"]', '诗', 'shi', '', NULL, '苑中 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fa1b676-0b4a-424d-b644-dd9f8da8227e', '從獵三首 一', '從獵三首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["獵犬諳斜路，宮嬪識認旗。","馬前雙兔起，宣爾羽林兒。"]', '["獵犬諳斜路，宮嬪識認旗。","马前雙兔起，宣爾羽林兒。"]', '诗', 'shi', '', NULL, '從獵三首 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('325d59bb-d131-4c7d-9ede-2fea977a75b9', '從獵三首 二', '從獵三首 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["小鐙狹鞦鞘，鞍輕妓細腰。","有時齊走馬，也學唱交交。"]', '["小鐙狹鞦鞘，鞍轻妓細腰。","有时齊走马，也学唱交交。"]', '诗', 'shi', '', NULL, '從獵三首 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35034dbf-6d75-4cbb-8e09-fac41be51f46', '從獵三首 三', '從獵三首 三', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["蹀躞巴陵駿，毰毸碧野雞。","忽聞仙樂動，賜酒玉偏提。"]', '["蹀躞巴陵駿，毰毸碧野雞。","忽闻仙乐动，賜酒玉偏提。"]', '诗', 'shi', '', NULL, '從獵三首 三 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38795a47-717c-46f2-8c53-00bfec573df1', '辛酉歲冬十一月隨駕幸岐下作', '辛酉歲冬十一月隨駕幸岐下作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["曳裾談笑殿西頭，忽聽征鐃從冕旒。","鳳蓋行時移紫氣，鸞旗駐處認皇州。","曉題御服頒羣吏，夜發宮嬪詔列侯。","雨露涵濡三百載，不知誰擬殺身酬。"]', '["曳裾談笑殿西头，忽听征鐃從冕旒。","鳳蓋行时移紫氣，鸾旗駐处認皇州。","晓題御服頒羣吏，夜發宮嬪詔列侯。","雨露涵濡三百載，不知誰擬殺身酬。"]', '诗', 'shi', '', NULL, '辛酉歲冬十一月隨駕幸岐下作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24bbc744-35b5-4c1c-a69d-7befafa8989e', '冬至夜作', '冬至夜作', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["中宵忽見動葭灰，料得南枝有早梅。","四野便應枯草綠，九重先覺凍雲開。","陰冰莫向河源塞，陽氣今從地底迴。","不道慘舒無定分，却憂蚊響又成雷。"]', '["中宵忽见动葭灰，料得南枝有早梅。","四野便應枯草綠，九重先覺凍云开。","陰冰莫向河源塞，陽氣今從地底迴。","不道慘舒無定分，却憂蚊响又成雷。"]', '诗', 'shi', '', NULL, '冬至夜作 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee885aa9-21bf-403b-ac58-72792c2fe6ba', '秋霖夜憶家', '秋霖夜憶家', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["垂老何時見弟兄，背燈愁泣到天明。","不知短髮能多少，一滴秋霖白一莖。"]', '["垂老何时见弟兄，背灯愁泣到天明。","不知短髮能多少，一滴秋霖白一莖。"]', '诗', 'shi', '', NULL, '秋霖夜憶家 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e37c39e8-8658-4652-8b46-a7148b984084', '恩賜櫻桃分寄朝士', '恩賜櫻桃分寄朝士', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["未許鶯偷出漢宮，上林初進半金籠。","蔗漿自透銀杯冷，朱實相輝玉椀紅。","俱有亂離終日恨，貴將滋味片時同。","霜威食檗應難近，宜在紗窗繡戶中。"]', '["未許鶯偷出漢宮，上林初進半金籠。","蔗漿自透銀杯冷，朱實相輝玉椀紅。","俱有亂離終日恨，貴將滋味片时同。","霜威食檗應难近，宜在紗窗繡戶中。"]', '诗', 'shi', '', NULL, '恩賜櫻桃分寄朝士 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc6d4bc-3a89-4e5a-9925-eaf8cc031f7c', '出官經硤石縣', '出官經硤石縣', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["謫宦過東畿，所抵州名濮。","故里欲清明，臨風堪慟哭。","溪長柳似帷，山暖花如醭。","逆旅訝簪裾，野老悲陵谷。","暝鳥影連翩，驚狐尾纛簌。","尚得佐方州，信是皇恩沐。"]', '["謫宦過东畿，所抵州名濮。","故里欲清明，臨风堪慟哭。","溪长柳似帷，山暖花如醭。","逆旅訝簪裾，野老悲陵谷。","暝鸟影連翩，驚狐尾纛簌。","尚得佐方州，信是皇恩沐。"]', '诗', 'shi', '', NULL, '出官經硤石縣 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33927a94-a928-4a22-b321-bafc60c6323e', '訪同年虞部李郎中', '訪同年虞部李郎中', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["策蹇相尋犯雪泥，廚煙未動日平西。","門庭野水䙰褷鷺，鄰里短牆咿喔雞。","未入慶霄君擇肉，畏逢華轂我吹韲。","地爐貰酒成狂醉，更覺襟懷得喪齊。"]', '["策蹇相尋犯雪泥，廚煙未动日平西。","门庭野水䙰褷鷺，鄰里短牆咿喔雞。","未入慶霄君擇肉，畏逢华轂我吹韲。","地爐貰酒成狂醉，更覺襟懷得喪齊。"]', '诗', 'shi', '', NULL, '訪同年虞部李郎中 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc9be77-d206-4380-9bc5-689c0a6b0a92', '贈漁者', '贈漁者', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["箇儂居處近誅茅，枳棘籬兼用荻梢。","盡日風扉從自掩，無人筒釣是誰拋。","城方四面牆陰直，江闊中心水脈坳。","我亦好閑求老伴，莫嫌遷客且論交。"]', '["箇儂居处近誅茅，枳棘籬兼用荻梢。","尽日风扉從自掩，無人筒釣是誰拋。","城方四面牆陰直，江闊中心水脈坳。","我亦好闲求老伴，莫嫌遷客且論交。"]', '诗', 'shi', '', NULL, '贈漁者 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b99d11d-e823-483a-9a6a-d26b7b2981c0', '春陰獨酌寄同年虞部李郎中', '春陰独酌寄同年虞部李郎中', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["春陰漠漠土脈潤，春寒微微風意和。","閑嗤入甲奔競態，醉唱落調漁樵歌。","詩道揣量疑可進，宦情刓缺轉無多。","酒酣狂興依然在，其奈千莖鬢雪何。"]', '["春陰漠漠土脈潤，春寒微微风意和。","闲嗤入甲奔競態，醉唱落調漁樵歌。","诗道揣量疑可進，宦情刓缺轉無多。","酒酣狂兴依然在，其奈千莖鬢雪何。"]', '诗', 'shi', '', NULL, '春陰獨酌寄同年虞部李郎中 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ad9399-d822-4988-aca5-6500a848ece9', '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇時李常侍洵嚴諫議龜李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 一', '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇时李常侍洵嚴諫議龟李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["敏手何妨誤汰金，敢懷私忿斅羊斟。","直應宣室還三接，未必豐城便陸沈。","熾炭一爐真玉性，濃霜千澗老松心。","私恩尚有捐驅誓，況是君恩萬倍深。"]', '["敏手何妨誤汰金，敢懷私忿斅羊斟。","直應宣室還三接，未必豐城便陸沈。","熾炭一爐真玉性，濃霜千澗老松心。","私恩尚有捐驱誓，況是君恩万倍深。"]', '诗', 'shi', '', NULL, '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇時李常侍洵嚴諫議龜李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 一 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd6fef66-ea3b-42e9-829a-3a51d354c516', '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇時李常侍洵嚴諫議龜李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 二', '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇时李常侍洵嚴諫議龟李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 二', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["征途安敢更遷延，冒入重圍勢使然。","衆果却應存苦李，五缾惟恐竭甘泉。","多端莫撼三珠樹，密策尋遺七寶鞭。","黃篾舫中梅雨裏，野人無事日高眠。"]', '["征途安敢更遷延，冒入重圍勢使然。","衆果却應存苦李，五缾惟恐竭甘泉。","多端莫撼三珠樹，密策尋遺七寶鞭。","黄篾舫中梅雨裏，野人無事日高眠。"]', '诗', 'shi', '', NULL, '奉和峽州孫舍人肇荆南重圍中寄諸朝士二篇時李常侍洵嚴諫議龜李起居殷衡李郎中冉皆有繼和余久有是債今至湖南方暇牽課 二 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34b9c6ed-e301-49f8-8645-124cfed3effd', '雪中過重湖信筆偶題', '雪中過重湖信笔偶題', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["道方時險擬如何，謫去甘心隱薜蘿。","青草湖將天暗合，白頭浪與雪相和。","旗亭臘酎踰年熟，水國春寒向晚多。","處困不忙仍不怨，醉來唯是欲傞傞。"]', '["道方时險擬如何，謫去甘心隐薜蘿。","青草湖將天暗合，白头浪與雪相和。","旗亭臘酎踰年熟，水国春寒向晚多。","处困不忙仍不怨，醉来唯是欲傞傞。"]', '诗', 'shi', '', NULL, '雪中過重湖信筆偶題 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07561bdc-b2f1-4d04-9fb3-4c4079961ba6', '寄湖南從事', '寄湖南從事', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["索寞襟懷酒半醒，無人一爲解餘酲。","岸頭柳色春將盡，船背雨聲天欲明。","去國正悲同旅雁，隔江何忍更啼鶯。","蓮花幕下風流客，試與溫存譴逐情。"]', '["索寞襟懷酒半醒，無人一爲解餘酲。","岸头柳色春將尽，船背雨声天欲明。","去国正悲同旅雁，隔江何忍更啼鶯。","蓮花幕下风流客，試與溫存譴逐情。"]', '诗', 'shi', '', NULL, '寄湖南從事 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbea9ea3-9250-477e-aa04-125c768cafd9', '翫水禽', '翫水禽', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["兩兩珍禽渺渺溪，翠衿紅掌淨無泥。","向陽眠處莎成毯，蹋水飛時浪作梯。","依倚雕梁輕社燕，抑揚金距笑晨雞。","勸君細認漁翁意，莫遣絚羅誤穩棲。"]', '["兩兩珍禽渺渺溪，翠衿紅掌淨無泥。","向陽眠处莎成毯，蹋水飞时浪作梯。","依倚雕梁轻社燕，抑揚金距笑晨雞。","勸君細認漁翁意，莫遣絚羅誤穩棲。"]', '诗', 'shi', '', NULL, '翫水禽 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a189ba-3400-4dac-8d96-bedbc4700f76', '早翫雪梅有懷親屬', '早翫雪梅有懷親屬', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["北陸候纔變，南枝花已開。","無人同悵望，把酒獨裴回。","凍白雪爲伴，寒香風是媒。","何因逢越使，腸斷謫仙才。"]', '["北陸候纔变，南枝花已开。","無人同悵望，把酒独裴回。","凍白雪爲伴，寒香风是媒。","何因逢越使，腸斷謫仙才。"]', '诗', 'shi', '', NULL, '早翫雪梅有懷親屬 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eca84f6-8861-4a14-82a7-5b537353fe9e', '欲明', '欲明', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["欲明籬被風吹倒，過午門因客到開。","忍苦可能遭鬼笑，息機應免致鷗猜。","岳僧互乞新詩去，酒保頻徵舊債來。","唯有狂吟與沈飲，時時猶自觸靈臺。"]', '["欲明籬被风吹倒，過午门因客到开。","忍苦可能遭鬼笑，息機應免致鷗猜。","岳僧互乞新诗去，酒保頻徵旧債来。","唯有狂吟與沈饮，时时猶自觸靈台。"]', '诗', 'shi', '', NULL, '欲明 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2dbb64b-5632-406a-849c-0847f43ec6d0', '梅花', '梅花', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["梅花不肯傍春光，自向深冬著豔陽。","龍笛遠吹胡地月，燕釵初試漢宮妝。","風雖強暴翻添思，雪欲侵凌更助香。","應笑暫時桃李樹，盜天和氣作年芳。"]', '["梅花不肯傍春光，自向深冬著豔陽。","龙笛远吹胡地月，燕釵初試漢宮妝。","风雖強暴翻添思，雪欲侵凌更助香。","應笑暫时桃李樹，盜天和氣作年芳。"]', '诗', 'shi', '', NULL, '梅花 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ebcb07-c980-4a17-bf0b-b6e64de1ac07', '小隱', '小隐', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["借得茅齋岳麓西，擬將身世老鋤犂。","清晨向市煙含郭，寒夜歸村月照溪。","爐爲窗明僧偶坐，松因雪折鳥驚啼。","靈椿朝菌由來事，却笑莊生始欲齊。"]', '["借得茅斋岳麓西，擬將身世老鋤犂。","清晨向市煙含郭，寒夜归村月照溪。","爐爲窗明僧偶坐，松因雪折鸟驚啼。","靈椿朝菌由来事，却笑莊生始欲齊。"]', '诗', 'shi', '', NULL, '小隱 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dee61727-039f-4a5f-a899-84aa07de92da', '曛黑', '曛黑', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["古木侵天日已沈，露華涼冷潤衣襟。","江城曛黑人行絕，唯有啼鳥伴夜碪。"]', '["古木侵天日已沈，露华涼冷潤衣襟。","江城曛黑人行絕，唯有啼鸟伴夜碪。"]', '诗', 'shi', '', NULL, '曛黑 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a2d76e-07dc-40d0-a810-b04303fc49cf', '曉日', '晓日', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["天際霞光入水中，水中天際一時紅。","直須日觀三更後，首送金烏上碧空。"]', '["天際霞光入水中，水中天際一时紅。","直須日观三更後，首送金烏上碧空。"]', '诗', 'shi', '', NULL, '曉日 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1f784d0-7857-4031-87fd-84397d0828f4', '醉著', '醉著', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["萬里清江萬里天，一村桑柘一村煙。","漁翁醉著無人喚，過午醒來雪滿船。"]', '["万里清江万里天，一村桑柘一村煙。","漁翁醉著無人喚，過午醒来雪满船。"]', '诗', 'shi', '', NULL, '醉著 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5172c647-ac04-4a4f-a32d-af08b6fef814', '柳', '柳', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["一籠金線拂彎橋，幾被兒童損細腰。","無奈靈和標格在，春來依舊褭長條。"]', '["一籠金線拂彎橋，幾被兒童損細腰。","無奈靈和標格在，春来依旧褭长條。"]', '诗', 'shi', '', NULL, '柳 韓偓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e300db24-6ef9-4712-b2b9-43d7304cfd70', '病中初聞復官二首 一', '病中初闻复官二首 一', '6f7c6dc6-031d-4d59-bd7a-8ec0bdf37658', '唐', '["抽毫連夜侍明光，執靮三年從省方。","燒玉謾勞曾歷試，鑠金寧爲欠周防。","也知恩澤招讒口，還痛神祇誤直腸。","聞道復官飜涕泗，屬車何在水茫茫。"]', '["抽毫連夜侍明光，執靮三年從省方。","燒玉謾勞曾歷試，鑠金寧爲欠周防。","也知恩澤招讒口，還痛神祇誤直腸。","闻道复官飜涕泗，屬车何在水茫茫。"]', '诗', 'shi', '', NULL, '病中初聞復官二首 一 韓偓 shi');
